INSERT INTO supervisor_analyses (id, audit_id, organization_id, protocol_version, prompt_version, overall_score, overall_label, classification, executive_summary, raw_json, table_price_presented, silence_applied, who_spoke_first, protagonist_transition_quality, cac_explained, negotiation_firmness, downsell_used, downsell_narrative_quality, priority_improvements, training_actions, objections_detected, modelo_analise, tokens_input, tokens_output, custo_estimado, created_at, updated_at) VALUES ('50843289-0dda-45f4-ae2b-f79281d8ba4f', '35597e31-aa45-4026-b864-84d53f13a2cc', '4ecd8f2d-d0c5-419c-a5bc-b2e94dca0465', '16-stage-commercial-audit-v1', '1.0', 2.8, 'CRÍTICA', 'CRITICA', 'A closer Evelyn conduziu uma call de 43 minutos com a Dra. Luciana Dias (médica dermatologista vinculada a hospital) que apresentou alto potencial de dor e desejo de solução. Contudo, o protocolo comercial foi gravemente comprometido: a call iniciou com interrupção por atendimento médico emergencial (gerenciada de forma inadequada), o diagnóstico SPIN foi superficial e desestruturado, e o maior erro crítico foi a closer autodescartando a venda de forma prematura e reiterada, sem tentar isolar objeções, ancorar valor, apresentar soluções adaptadas ou conduzir qualquer tentativa real de fechamento. Evelyn essencialmente convenceu a lead de que a empresa NÃO poderia ajudá-la, deixando a call sem proposta formal, sem próximo passo definido e sem down sell estruturado. A lead demonstrou alta receptividade, verbalizou dores claras, budget implícito e abertura para soluções — sinais de compra completamente ignorados. Resultado: oportunidade perdida, sem pipeline gerado.', '{"stages": [{"gaps": ["Nenhuma frase de aquecimento ou humanização", "Não recuperou o ambiente após a interrupção", "Tentativa de reagendamento prematura sem avaliar viabilidade da continuação"], "name": "Quebra-gelo", "score": 2, "stage": 1, "status": "critical", "findings": "A abertura foi caótica: câmera apagada, ruídos de setup, lead falando com terceiros sobre atendimento de paciente, interrupção imediata para pronto-socorro. Evelyn não estabeleceu qualquer elemento de rapport ou leveza. Tentou reagendar sem explorar a oportunidade, perdendo controle do frame logo no início.", "highlights": [], "weight_pct": 3}, {"gaps": ["Zero espelhamento emocional", "Nenhuma validação da experiência médica da lead", "Closer não criou identidade de parceiro — posicionou-se como avaliadora crítica desde o início"], "name": "Rapport", "score": 2, "stage": 2, "status": "critical", "findings": "Evelyn pulou direto para explicações sobre o método da empresa assim que a lead fez a primeira pergunta sobre entrega de pacientes. Não houve reconhecimento genuíno da trajetória da Dra. Luciana, elogio ao posicionamento dela ou criação de conexão emocional. A lead foi quem dominou o diálogo com informações espontâneas.", "highlights": [], "weight_pct": 5}, {"gaps": ["Sem definição clara do propósito da reunião", "Sem acordo de tempo", "Sem comprometimento da lead para ouvir a proposta ao final", "A interrupção do pronto-socorro não foi gerenciada com pacto de retomada"], "name": "Pacto Inicial", "score": 2, "stage": 3, "status": "critical", "findings": "Não houve alinhamento de agenda, definição de tempo, objetivo da reunião ou comprometimento mútuo. Evelyn mencionou ''diagnóstico'' de forma vaga, mas não estabeleceu as regras do jogo. A lead chegou com dúvidas sobre o produto sem saber o que a call significava, e isso nunca foi corrigido.", "highlights": [], "weight_pct": 5}, {"gaps": ["Não mapeou há quanto tempo está no mercado de estética", "Não investigou volume atual de procedimentos particulares", "Não perguntou sobre canais de comunicação ativos", "Perguntas situacionais vieram misturadas com explicações do produto"], "name": "SPIN - Situação", "score": 4, "stage": 4, "status": "warning", "findings": "Evelyn coletou dados básicos de situação de forma reativa — respondendo às falas espontâneas da lead. Mapeou: vínculo com hospital, estrutura de secretária, ticket atual (R$15-20k/mês), especialidades, público majoritariamente plano/baixa renda. Contudo, as perguntas foram dispersas e não seguiram uma sequência lógica de diagnóstico.", "highlights": ["Identificou que a secretária é exclusiva", "Entendeu a dinâmica de atendimento dentro do hospital", "Mapeou faturamento atual"], "weight_pct": 5}, {"gaps": ["Evelyn não fez perguntas exploratórias sobre os problemas", "Não quantificou as perdas financeiras com agências anteriores", "Não perguntou sobre tentativas de venda direta para pacientes da base"], "name": "SPIN - Problema", "score": 4, "stage": 5, "status": "warning", "findings": "A lead verbalizou os problemas espontaneamente e com riqueza: falta de conversão de pacientes, frustração com agências anteriores, base de pacientes de baixa renda, queda de movimento no hospital, isolamento dentro da estrutura hospitalar. Evelyn ouviu mas não aprofundou ativamente — deixou a lead diagnosticar sozinha.", "highlights": ["Lead verbalizou claramente ''já gastei muito dinheiro e não tive retorno''", "Identificou gargalo de conversão (''morendo na praia'')"], "weight_pct": 5}, {"gaps": ["Nenhuma pergunta de implicação formulada", "Não conectou os problemas a consequências financeiras mensuráveis", "Não explorou o risco de inação", "Perdeu a oportunidade de aprofundar a dor quando a lead disse ''estou cansada de pagar e não ter retorno''"], "name": "SPIN - Implicação", "score": 1, "stage": 6, "status": "critical", "findings": "Etapa praticamente ausente. Evelyn nunca explorou as consequências dos problemas identificados: quanto a lead está deixando de ganhar por mês, qual o impacto na renda de longo prazo, o que acontece se continuar sem solução, o risco de perder espaço no mercado local de estética, o custo emocional do desânimo acumulado. A implicação é a etapa que cria urgência — e foi completamente negligenciada.", "highlights": [], "weight_pct": 8}, {"gaps": ["Evelyn não perguntou ''O que significaria para você atingir esses 70k?''", "Não explorou o sonho por trás da meta", "Não fez a lead imaginar a solução funcionando"], "name": "SPIN - Necessidade", "score": 2, "stage": 7, "status": "critical", "findings": "A lead sinalizou necessidade de valor em múltiplos momentos (''quero método'', ''preciso de retorno'', ''preciso organizar a casa''), mas Evelyn não conduziu perguntas que fizessem a lead verbalizar o valor da solução. Não houve construção da necessidade de payoff — o que a solução representaria para a Dra. Luciana em termos de realização, crescimento e alívio.", "highlights": ["Lead verbalizou meta de R$60-70k/mês espontaneamente", "Lead reconheceu necessidade de treinamento de vendas para si e secretária"], "weight_pct": 7}, {"gaps": ["Sem resumo das dores identificadas antes da transição", "Sem validação da lead para prosseguir", "Apresentação de produto iniciada sem convite formal"], "name": "Pacto de Transição", "score": 1, "stage": 8, "status": "critical", "findings": "Não houve transição estruturada para a apresentação. Evelyn começou a falar sobre produtos da empresa de forma orgânica e confusa, misturando diagnóstico com apresentação. Nenhuma frase de transição como ''Baseado no que você me contou, vou te apresentar como a gente pode ajudar'' foi utilizada.", "highlights": [], "weight_pct": 5}, {"gaps": ["Sem estrutura clara (início, meio, fim)", "Sem prova social ou case de médico em contexto similar", "Sem demonstração visual ou storytelling", "Método foi usado como argumento de exclusão (''não se encaixa no seu cenário'') em vez de solução"], "name": "Apresentação do Método", "score": 2, "stage": 9, "status": "critical", "findings": "O método foi descrito de forma fragmentada, reativa e repetitiva ao longo de toda a call, sem uma apresentação estruturada. Evelyn mencionou as frentes de tráfego pago + estrutura comercial, a importância da secretária, esteira de produtos e oferta — mas sempre de forma introdutória, nunca aprofundando o diferencial. Não usou cases, não demonstrou resultados, não conectou o método à realidade específica da lead.", "highlights": ["Mencionou que o foco não é tráfego pago isolado", "Explicou a lógica de ''organizar a casa antes de trazer pacientes''"], "weight_pct": 10}, {"gaps": ["Nenhum produto foi apresentado com seus benefícios e resultados", "Evelyn autodescartou todos os produtos sem dar chance à lead de decidir", "Sem demonstração de ROI potencial", "Sem storytelling de transformação vinculado a cada oferta"], "name": "Apresentação do Produto", "score": 2, "stage": 10, "status": "critical", "findings": "Três produtos foram mencionados (Aceleração ~R$70k, Ativação, Mentoria ~R$550/mês) de forma passageira e desqualificadora. Evelyn apresentou cada produto já sinalizando por que não serviria para a lead, sem construir valor em nenhum deles. A apresentação foi feita ao contrário: em vez de elevar desejo e depois endereçar objeções, começou descartando antes mesmo de apresentar.", "highlights": ["Apresentou três níveis de produto, o que demonstra ecossistema"], "weight_pct": 10}, {"gaps": ["Nenhuma técnica de isolamento aplicada", "Evelyn validou todas as objeções como intransponíveis", "Perdeu a oportunidade de perguntar: ''Se o cenário fosse diferente, faria sentido avançar?''", "Não separou objeção de preço de objeção de viabilidade"], "name": "Isolamento de Objeções", "score": 0, "stage": 11, "status": "skipped", "findings": "Etapa completamente ausente. A lead levantou múltiplas objeções implícitas (preço alto, cenário limitante, base fraca, vinculação ao hospital) e Evelyn as aceitou e reforçou em vez de isolá-las. Não foi feita nenhuma tentativa de separar a objeção real da objeção de fumaça, nem de entender se havia uma objeção principal bloqueando a decisão.", "highlights": [], "weight_pct": 8}, {"gaps": ["Preço apresentado sem preparação de valor", "Sem âncora de perda (''quanto você deixa de ganhar por mês sem isso?'')", "Sem comparação com investimentos anteriores sem retorno", "Sem contextualização do ROI potencial antes do preço"], "name": "Ancoragem", "score": 0, "stage": 12, "status": "skipped", "findings": "Nenhuma ancoragem de valor foi realizada. O preço do Aceleração (R$70k) foi jogado de forma crua, sem contexto, sem comparação com o custo do problema, sem âncora alta para criar percepção de valor relativo. A lead reagiu com choque (''Nossa Senhora'') e Evelyn imediatamente concordou que não fazia sentido — encerrando qualquer possibilidade de negociação.", "highlights": [], "weight_pct": 8}, {"gaps": ["Preço revelado sem valor construído previamente", "Linguagem informal e despreparada na revelação do preço", "Sem apresentação de condições de pagamento", "Sem contextualização de o que está incluído em cada preço"], "name": "Preço Tabela", "score": 1, "stage": 13, "status": "critical", "findings": "O preço foi mencionado de forma improvisada (''deixa eu abrir minha tabela'') sem preparação. Aceleração: ~R$70k. Mentoria: ~R$550/mês (~R$6k). Não houve apresentação formal de tabela, pacotes ou condições. A forma de revelar o preço comunicou insegurança e falta de preparo.", "highlights": [], "weight_pct": 5}, {"gaps": ["Sem cálculo de ROI conduzido com a lead", "Sem projeção de cenário futuro", "Sem técnica de ''se você fechar X procedimentos por mês, em quanto tempo recupera?''"], "name": "Preço Protagonista", "score": 0, "stage": 14, "status": "skipped", "findings": "Etapa completamente ausente. Após mencionar o preço, Evelyn não conduziu nenhuma técnica de protagonismo — como fazer a lead calcular o retorno sobre o investimento, visualizar o cenário após 90 dias, ou comparar o investimento com o custo da inação. A lead foi deixada sozinha com o número, sem narrativa de transformação.", "highlights": [], "weight_pct": 5}, {"gaps": ["Zero tentativa de fechamento", "Sem proposta formal apresentada", "Sem criação de urgência ou escassez", "Sem definição de próximo passo (follow-up, nova reunião, proposta por escrito)"], "name": "Negociação", "score": 0, "stage": 15, "status": "skipped", "findings": "Nenhuma negociação ocorreu. Evelyn não apresentou proposta formal, não tentou customizar condição, não ofereceu plano de entrada, não criou urgência, não usou concessão estratégica. A call encerrou sem qualquer tentativa de fechamento ou próximo passo concreto.", "highlights": [], "weight_pct": 7}, {"gaps": ["Down sell descartado pela própria closer antes de ser tentado", "Não explorou o interesse demonstrado pela lead na mentoria", "Não criou uma proposta de entrada mínima para manter o relacionamento", "Não ofereceu diagnóstico gratuito, conteúdo ou qualquer isca para próximo contato"], "name": "Down Sell", "score": 1, "stage": 16, "status": "critical", "findings": "Embora a Mentoria (~R$550/mês) tenha sido mencionada como opção mais acessível, ela foi apresentada e imediatamente descartada pela própria closer (''não te recomendaria comprar nem esse''). O down sell foi suicidado antes de ser oferecido. A lead demonstrou interesse implícito (''quanto custa essa mentoria?'') e mesmo assim Evelyn não aproveitou o sinal de compra.", "highlights": ["Lead perguntou espontaneamente o preço da mentoria — sinal de compra claro"], "weight_pct": 4}], "negotiation": {"diagnosis": "A closer ignorou 6 sinais de compra identificados e encerrou a call sem proposta, sem fechamento e sem pipeline estruturado. A lead estava comprada em dor e aberta a solução — a venda foi perdida por desistência unilateral da closer.", "attempt_made": false, "closing_attempt": false, "next_step_defined": false, "proposal_presented": false, "signals_acted_upon": false, "lead_buying_signals_detected": ["Lead perguntou espontaneamente o preço da mentoria (00:39:xx)", "Lead verbalizou meta clara de faturamento: R$60-70k/mês", "Lead reconheceu necessidade de treinamento para si e secretária", "Lead sugeriu envolver o hospital como cliente maior (''posso conversar com os diretores'')", "Lead disse ''qualquer coisa eu passo o contato'' — abertura para continuidade", "Lead usou metáfora ''morrendo na praia'' — alta consciência do problema e desejo de solução"]}, "overall_label": "CRÍTICA", "overall_score": 2.8, "classification": "CRITICA", "protocol_version": "16-stage-commercial-audit-v1", "training_actions": [{"action": "Role-play de isolamento de objeções", "deadline": "7 dias", "priority": "urgente", "description": "Simulações semanais com as objeções mais comuns do nicho médico (preço, cenário limitante, experiências negativas anteriores). A closer deve praticar a sequência: validar → isolar → reverter → confirmar."}, {"action": "Treinamento em ancoragem e apresentação de preço", "deadline": "7 dias", "priority": "urgente", "description": "Workshop interno sobre como construir valor antes de revelar o preço: custo do problema + ROI projetado + comparação com alternativas + condições de pagamento. Gravar simulações e revisar com feedback."}, {"action": "Calibração de SPIN — foco em Implicação e Necessidade", "deadline": "14 dias", "priority": "alta", "description": "Revisão estruturada das perguntas de implicação e necessidade de payoff com exemplos aplicados ao nicho de saúde estética. A closer deve ter um banco de perguntas consultáveis durante a call."}, {"action": "Protocolo de leitura de sinais de compra", "deadline": "14 dias", "priority": "alta", "description": "Treinamento para identificar e agir sobre sinais verbais e comportamentais de compra durante a call. A closer perdeu ao menos 6 sinais nessa call. Deve aprender a redirecionar para proposta ao detectar o primeiro sinal claro."}, {"action": "Script de pacto inicial e transição", "deadline": "14 dias", "priority": "alta", "description": "Desenvolver e memorizar script padronizado de abertura (pacto inicial) e transição para apresentação, incluindo protocolo de retomada após imprevistos. Testar em role-play com supervisor."}, {"action": "Revisão do caso com a closer Evelyn — sessão individual de feedback", "deadline": "48 horas", "priority": "urgente", "description": "Sessão de revisão da transcrição desta call com a closer, apontando os momentos específicos de erro e os sinais de compra perdidos. Objetivo: criar consciência dos padrões limitantes de comportamento comercial (autodescarte, concordância excessiva com objeções)."}, {"action": "Desenvolvimento de cases e prova social para médicos hospitalares", "deadline": "21 dias", "priority": "média", "description": "Levantar e documentar cases de médicos em contextos similares (vínculo hospitalar, público misto, início de estruturação estética) para uso em calls como esta. A ausência de prova social foi fator determinante para a perda de credibilidade."}], "executive_summary": "A closer Evelyn conduziu uma call de 43 minutos com a Dra. Luciana Dias (médica dermatologista vinculada a hospital) que apresentou alto potencial de dor e desejo de solução. Contudo, o protocolo comercial foi gravemente comprometido: a call iniciou com interrupção por atendimento médico emergencial (gerenciada de forma inadequada), o diagnóstico SPIN foi superficial e desestruturado, e o maior erro crítico foi a closer autodescartando a venda de forma prematura e reiterada, sem tentar isolar objeções, ancorar valor, apresentar soluções adaptadas ou conduzir qualquer tentativa real de fechamento. Evelyn essencialmente convenceu a lead de que a empresa NÃO poderia ajudá-la, deixando a call sem proposta formal, sem próximo passo definido e sem down sell estruturado. A lead demonstrou alta receptividade, verbalizou dores claras, budget implícito e abertura para soluções — sinais de compra completamente ignorados. Resultado: oportunidade perdida, sem pipeline gerado.", "objections_detected": [{"type": "preço", "moment": "00:35:40", "handled": false, "objection": "Preço muito alto (''Nossa Senhora. Não tem condições de jeito nenhum'')", "recommended_approach": "Isolar a objeção de preço da objeção de valor. Conduzir cálculo de ROI: ''Se você fechar 3 blefaroplastias de R$7k, você recupera o investimento em um mês. O que impediria isso com o método estruturado?''"}, {"type": "viabilidade", "moment": "00:28:30", "handled": false, "objection": "Base de pacientes de baixa renda — não consegue vender procedimentos caros", "recommended_approach": "Explorar a vertente de captação externa via tráfego pago + posicionamento digital. A lead não depende exclusivamente da base hospitalar para procedimentos particulares."}, {"type": "ceticismo / experiência negativa", "moment": "00:03:50", "handled": "parcialmente", "objection": "Já tentei agências e não tive retorno", "recommended_approach": "Diferenciar com prova social e case específico de médico em contexto similar. Mostrar o que foi feito diferente e por que as agências anteriores falharam (sem estrutura comercial)."}, {"type": "cenário", "moment": "00:13:30", "handled": false, "objection": "Vinculação ao hospital pode ser limitante", "recommended_approach": "A própria lead explicou que pode atender particulares dentro do hospital sem vínculo formal. A objeção foi criada pela closer e não pela lead — erro grave de framing."}, {"type": "viabilidade operacional", "moment": "00:27:00", "handled": false, "objection": "Não sei se terei pacientes suficientes para aplicar o método", "recommended_approach": "Apresentar o componente de tráfego pago do Aceleração como solução exatamente para esse gap, mostrando que a captação externa é parte do pacote — não um custo adicional."}], "priority_improvements": [{"area": "Não desistir da venda prematuramente", "priority": 1, "description": "A closer encerrou a call convencendo a lead de que não poderia ser ajudada. Este é o erro mais grave: nunca cabe ao closer decretar a inviabilidade sem esgotar todas as alternativas. A lead demonstrou desejo real de solução e múltiplos sinais de compra que foram ignorados."}, {"area": "Construção de valor antes do preço", "priority": 2, "description": "O preço do Aceleração (R$70k) foi jogado sem nenhuma construção de valor, âncora de perda ou projeção de ROI. O choque da lead era previsível e evitável. O preço deve ser sempre precedido de: custo do problema + resultado esperado + comparação com alternativas."}, {"area": "Isolamento e reversão de objeções", "priority": 3, "description": "Todas as objeções foram aceitas e reforçadas pela closer. É necessário dominar técnicas de isolamento: identificar a objeção real, separá-la das secundárias, validar sem concordar, e oferecer contra-argumento com evidência."}, {"area": "SPIN de Implicação e Necessidade", "priority": 4, "description": "A etapa de implicação foi completamente negligenciada. Sem explorar as consequências dos problemas (financeiras, emocionais, de mercado), a lead não sente urgência para agir. Perguntas como ''O que acontece com seu consultório daqui a 12 meses se esse cenário continuar?'' são indispensáveis."}, {"area": "Down sell e manutenção de pipeline", "priority": 5, "description": "Mesmo sem fechar o produto principal, a closer deveria ter convertido a lead para a Mentoria (R$550/mês) — produto que a própria lead demonstrou interesse — ou para um próximo passo concreto (nova reunião com dados do hospital, envio de proposta, diagnóstico expandido). A call encerrou sem nenhum ativo de pipeline."}, {"area": "Gestão de imprevistos e controle do frame", "priority": 6, "description": "A interrupção por atendimento de emergência no início da call não foi gerenciada profissionalmente. A closer deve ter um protocolo para situações assim: propor uma pausa cronometrada, manter o controle emocional, e ao retomar, fazer um reset de energia antes de continuar."}]}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"area": "Não desistir da venda prematuramente", "priority": 1, "description": "A closer encerrou a call convencendo a lead de que não poderia ser ajudada. Este é o erro mais grave: nunca cabe ao closer decretar a inviabilidade sem esgotar todas as alternativas. A lead demonstrou desejo real de solução e múltiplos sinais de compra que foram ignorados."}, {"area": "Construção de valor antes do preço", "priority": 2, "description": "O preço do Aceleração (R$70k) foi jogado sem nenhuma construção de valor, âncora de perda ou projeção de ROI. O choque da lead era previsível e evitável. O preço deve ser sempre precedido de: custo do problema + resultado esperado + comparação com alternativas."}, {"area": "Isolamento e reversão de objeções", "priority": 3, "description": "Todas as objeções foram aceitas e reforçadas pela closer. É necessário dominar técnicas de isolamento: identificar a objeção real, separá-la das secundárias, validar sem concordar, e oferecer contra-argumento com evidência."}, {"area": "SPIN de Implicação e Necessidade", "priority": 4, "description": "A etapa de implicação foi completamente negligenciada. Sem explorar as consequências dos problemas (financeiras, emocionais, de mercado), a lead não sente urgência para agir. Perguntas como ''O que acontece com seu consultório daqui a 12 meses se esse cenário continuar?'' são indispensáveis."}, {"area": "Down sell e manutenção de pipeline", "priority": 5, "description": "Mesmo sem fechar o produto principal, a closer deveria ter convertido a lead para a Mentoria (R$550/mês) — produto que a própria lead demonstrou interesse — ou para um próximo passo concreto (nova reunião com dados do hospital, envio de proposta, diagnóstico expandido). A call encerrou sem nenhum ativo de pipeline."}, {"area": "Gestão de imprevistos e controle do frame", "priority": 6, "description": "A interrupção por atendimento de emergência no início da call não foi gerenciada profissionalmente. A closer deve ter um protocolo para situações assim: propor uma pausa cronometrada, manter o controle emocional, e ao retomar, fazer um reset de energia antes de continuar."}]'::jsonb, '[{"action": "Role-play de isolamento de objeções", "deadline": "7 dias", "priority": "urgente", "description": "Simulações semanais com as objeções mais comuns do nicho médico (preço, cenário limitante, experiências negativas anteriores). A closer deve praticar a sequência: validar → isolar → reverter → confirmar."}, {"action": "Treinamento em ancoragem e apresentação de preço", "deadline": "7 dias", "priority": "urgente", "description": "Workshop interno sobre como construir valor antes de revelar o preço: custo do problema + ROI projetado + comparação com alternativas + condições de pagamento. Gravar simulações e revisar com feedback."}, {"action": "Calibração de SPIN — foco em Implicação e Necessidade", "deadline": "14 dias", "priority": "alta", "description": "Revisão estruturada das perguntas de implicação e necessidade de payoff com exemplos aplicados ao nicho de saúde estética. A closer deve ter um banco de perguntas consultáveis durante a call."}, {"action": "Protocolo de leitura de sinais de compra", "deadline": "14 dias", "priority": "alta", "description": "Treinamento para identificar e agir sobre sinais verbais e comportamentais de compra durante a call. A closer perdeu ao menos 6 sinais nessa call. Deve aprender a redirecionar para proposta ao detectar o primeiro sinal claro."}, {"action": "Script de pacto inicial e transição", "deadline": "14 dias", "priority": "alta", "description": "Desenvolver e memorizar script padronizado de abertura (pacto inicial) e transição para apresentação, incluindo protocolo de retomada após imprevistos. Testar em role-play com supervisor."}, {"action": "Revisão do caso com a closer Evelyn — sessão individual de feedback", "deadline": "48 horas", "priority": "urgente", "description": "Sessão de revisão da transcrição desta call com a closer, apontando os momentos específicos de erro e os sinais de compra perdidos. Objetivo: criar consciência dos padrões limitantes de comportamento comercial (autodescarte, concordância excessiva com objeções)."}, {"action": "Desenvolvimento de cases e prova social para médicos hospitalares", "deadline": "21 dias", "priority": "média", "description": "Levantar e documentar cases de médicos em contextos similares (vínculo hospitalar, público misto, início de estruturação estética) para uso em calls como esta. A ausência de prova social foi fator determinante para a perda de credibilidade."}]'::jsonb, '[{"type": "preço", "moment": "00:35:40", "handled": false, "objection": "Preço muito alto (''Nossa Senhora. Não tem condições de jeito nenhum'')", "recommended_approach": "Isolar a objeção de preço da objeção de valor. Conduzir cálculo de ROI: ''Se você fechar 3 blefaroplastias de R$7k, você recupera o investimento em um mês. O que impediria isso com o método estruturado?''"}, {"type": "viabilidade", "moment": "00:28:30", "handled": false, "objection": "Base de pacientes de baixa renda — não consegue vender procedimentos caros", "recommended_approach": "Explorar a vertente de captação externa via tráfego pago + posicionamento digital. A lead não depende exclusivamente da base hospitalar para procedimentos particulares."}, {"type": "ceticismo / experiência negativa", "moment": "00:03:50", "handled": "parcialmente", "objection": "Já tentei agências e não tive retorno", "recommended_approach": "Diferenciar com prova social e case específico de médico em contexto similar. Mostrar o que foi feito diferente e por que as agências anteriores falharam (sem estrutura comercial)."}, {"type": "cenário", "moment": "00:13:30", "handled": false, "objection": "Vinculação ao hospital pode ser limitante", "recommended_approach": "A própria lead explicou que pode atender particulares dentro do hospital sem vínculo formal. A objeção foi criada pela closer e não pela lead — erro grave de framing."}, {"type": "viabilidade operacional", "moment": "00:27:00", "handled": false, "objection": "Não sei se terei pacientes suficientes para aplicar o método", "recommended_approach": "Apresentar o componente de tráfego pago do Aceleração como solução exatamente para esse gap, mostrando que a captação externa é parte do pacote — não um custo adicional."}]'::jsonb, 'claude-sonnet-4-6', 14634, 6829, 0.1463, '2026-03-28T01:32:42.942895+00:00', '2026-03-28T01:32:42.942895+00:00');
INSERT INTO supervisor_analyses (id, audit_id, organization_id, protocol_version, prompt_version, overall_score, overall_label, classification, executive_summary, raw_json, table_price_presented, silence_applied, who_spoke_first, protagonist_transition_quality, cac_explained, negotiation_firmness, downsell_used, downsell_narrative_quality, priority_improvements, training_actions, objections_detected, modelo_analise, tokens_input, tokens_output, custo_estimado, created_at, updated_at) VALUES ('f411560b-e95f-430c-9b7d-c267bfcf94ee', '30b18ba9-fdc1-4f4d-b812-9eb667c2a54b', '4ecd8f2d-d0c5-419c-a5bc-b2e94dca0465', '16-stage-commercial-audit-v1', '1.0', 6.1, 'ok', 'BOA', 'Call de diagnóstico de 53 minutos entre a closer Evelyn e o lead Bruno Louzada, dentista clínico geral de Cotia/SP, em transição para cirurgias da face após conclusão do curso FaceCode com Alexandre. O protocolo foi executado de forma parcial: os estágios iniciais de rapport e situacional foram muito bem conduzidos, gerando alto nível de confiança e abertura do lead. A closer demonstra domínio sobre o mercado, empatia e capacidade de construção de vínculo. No entanto, a call encerrou sem apresentação de preço, sem ancoragem de valor, sem negociação efetiva e sem fechamento — todos os estágios finais foram ou zerados ou comprometidos pela decisão de adiar para uma segunda call com a presença da esposa. A gestão de objeção sobre a esposa foi parcialmente acertada (insistência em trazê-la), mas gerou frustração e desengajamento do lead, que solicitava o valor explicitamente. O isolamento de objeções foi executado de forma defensiva e não resolutiva. A call terminou em reagendamento sem data confirmada, o que representa risco real de perda do lead.', '{"stages": [{"name": "Quebra-gelo", "score": 8, "stage": 1, "status": "excellent", "weight_pct": 3, "observations": "Evelyn inicia com leveza, pergunta sobre a cidade do lead, menciona experiência pessoal em Barueri/Alphaville, palestra do Pablo Marçal, cria conexão geográfica natural. Conversa fluiu de forma orgânica nos primeiros 2 minutos. Ponto de melhoria: poderia ter sido um pouco mais curta para não gastar tempo em tópicos sem relação com o perfil do lead."}, {"name": "Rapport", "score": 9, "stage": 2, "status": "excellent", "weight_pct": 5, "observations": "Rapport muito bem construído ao longo de toda a call. Evelyn conecta experiência laboratorial/clínica com o universo do lead, cria identificação genuína com a jornada de pai dentista, família, três filhos, transição de carreira. Lead compartilhou informações pessoais profundas (relação com o pai, casamento anterior, bebê de 6 meses, rotina da esposa), sinal claro de alta confiança estabelecida. Pontos de conexão humanizados foram consistentes e bem distribuídos na call."}, {"name": "Pacto Inicial", "score": 7, "stage": 3, "status": "ok", "weight_pct": 5, "observations": "Executado em ~04:17 com a frase ''eu queria entender um pouquinho mais de você… antes de eu iniciar aqui para fazer algumas perguntas''. Há uma segunda tentativa mais estruturada em ~22:51 onde Evelyn propõe ir até parte da apresentação e agendar segunda call para negociação. O pacto foi cumprido, porém com linguagem difusa e sem alinhamento claro de tempo e agenda da call. A condição do sim/não ao final foi bem posicionada, mas a divisão em duas calls não foi apresentada como standard desde o início, o que gerou estranheza quando foi invocada para justificar a ausência de preço."}, {"name": "SPIN – Situação", "score": 8, "stage": 4, "status": "excellent", "weight_pct": 5, "observations": "Coleta situacional robusta: clínica solo sem secretária, ticket médio R$25-35k/mês, especialidade principal em resinas, 20% de taxa de conversão, investimento de ~R$1.200/mês em tráfego próprio, lead a R$5, 5-10 leads/dia, experiência prévia de 18 meses com a Smile de Curitiba, esposa dentista com clínica separada, pai dentista com referência de resultado em cirurgias. Dados coletados naturalmente durante o diálogo, sem soar como formulário."}, {"name": "SPIN – Problema", "score": 7, "stage": 5, "status": "ok", "weight_pct": 5, "observations": "Problemas identificados: estagnação de faturamento, leads não qualificados, dependência de processo próprio sem time, ausência de secretária, desgaste operacional, hora clínica depreciando com recorrência, falta de tempo para família (3 filhos). A closer mapeou corretamente os problemas mas não aprofundou perguntas específicas do tipo ''quanto tempo você perde com leads que não convertem?'' ou ''o que acontece quando você tira um dia de folga?''. Problemas vieram mais pelo relato espontâneo do lead do que por perguntas diagnósticas intencionais."}, {"name": "SPIN – Implicação", "score": 5, "stage": 6, "status": "warning", "weight_pct": 8, "observations": "A implicação foi tocada superficialmente: Evelyn menciona que sem processo comercial a secretária leva o processo embora ao sair, que leads caros sem qualificação queimam dinheiro, e que sobrecarga leva à frustração. Mas não houve pergunta de implicação estruturada do tipo ''o que acontece com a sua família se você continuar faturando R$30k/mês pelos próximos 6 meses?'' ou ''se você não resolver o lado comercial agora que vai entrar em cirurgias, qual o risco de iniciar mal esse novo serviço?''. A dor ficou identificada mas não amplificada suficientemente para criar urgência emocional e financeira no lead."}, {"name": "SPIN – Necessidade", "score": 6, "stage": 7, "status": "ok", "weight_pct": 7, "observations": "O lead verbalizou sua necessidade de forma espontânea: ticket maior, mais tempo com a família, escalabilidade com cirurgias, ter alguém para cuidar do comercial. Evelyn validou bem esses pontos e conectou à solução. Porém, a closer não aprofundou a visão de futuro do lead com perguntas como ''se em 6 meses você estiver operando e com faturamento de R$100k, como isso muda sua vida?'' — o que teria fortalecido o desejo de solução antes da apresentação."}, {"name": "Pacto de Transição", "score": 6, "stage": 8, "status": "ok", "weight_pct": 5, "observations": "Executado em ~25:54 com a frase ''Deixa eu te apresentar um pouquinho então agora sobre o que que é System Digital''. Há uma tentativa de validação antes de iniciar a apresentação. O pacto foi feito, mas sem pedir permissão explícita ou confirmar que o lead estava pronto para avançar para o próximo estágio. A transição da fase de diagnóstico para apresentação poderia ter sido marcada com mais clareza e energia."}, {"name": "Apresentação do Método", "score": 7, "stage": 9, "status": "ok", "weight_pct": 10, "observations": "Apresentação do método Face Sem K executada com clareza: 6 pilares (tráfego, posicionamento, esteira de produtos, funil de vendas, pré-vendas/secretária, revenda de base). Uso de casos (Dra. Débora: R$70k/semana) para validação social. Evelyn conectou bem os resultados ao cenário do Bruno, especialmente o estratégia de revender cirurgias para a base de pacientes de resina. Pontos negativos: apresentação foi interrompida várias vezes por perguntas do lead que poderiam ter sido gerenciadas de forma mais controlada; a explicação sobre LTV foi correta mas longa; o slide de ''sistema da System'' foi descrito sem clareza visual para o auditor, indicando possível falta de fluidez na apresentação gráfica."}, {"name": "Apresentação do Produto", "score": 6, "stage": 10, "status": "ok", "weight_pct": 10, "observations": "Produto apresentado como programa de 6 meses com: tráfego pago incluso, treinamento de secretária, funil de pré-vendas, CRM, protocolos de caixa rápido, acompanhamento individual (não mentoria em grupo), reuniões personalizadas, grupo exclusivo. Evelyn diferenciou bem da mentoria tradicional e da agência de tráfego pago. Porém, os entregáveis não foram listados de forma sequencial e organizada — o lead fez a síntese (''é uma mentoria para minha clínica rodar e vender''), indicando que a apresentação não foi suficientemente clara sobre o que é entregue, quando e como. Faltou apresentar SLA de atendimento, frequência das reuniões e cronograma dos 6 meses."}, {"name": "Isolamento de Objeções", "score": 4, "stage": 11, "status": "warning", "weight_pct": 8, "observations": "A principal objeção gerenciada foi a presença da esposa para tomada de decisão financeira. Evelyn identificou corretamente que a esposa é influenciadora de decisão e insistiu em trazê-la para a segunda call. A técnica foi aplicada de forma repetitiva e gerou tensão com o lead, que pediu explicitamente o valor (''me fala porque daí eu já vou meio que conversar com ela''). Evelyn não isolou outras possíveis objeções (momento de início, estrutura atual sem secretária, incerteza sobre o novo serviço de cirurgias). Não houve checagem de outras objeções antes de encerrar a call."}, {"name": "Ancoragem", "score": 2, "stage": 12, "status": "critical", "weight_pct": 8, "observations": "Ancoragem praticamente ausente. Evelyn mencionou que há ''dois tipos de valores: para tomada de decisão em call e para depois da call'' — o que é uma âncora de urgência, não de valor. Não houve ancoragem pelo custo do problema (ex: ''você fatura R$30k, com cirurgias e processo comercial poderia fazer R$100k em duas semanas — quanto você deixa de ganhar por mês sem isso?''), nem ancoragem por comparação de mercado, nem ancoragem pelo investimento da concorrência. A ausência de ancoragem enfraquece significativamente o poder de persuasão antes da revelação do preço."}, {"name": "Preço Tabela", "score": 0, "stage": 13, "status": "skipped", "weight_pct": 5, "observations": "Preço tabela não apresentado. Evelyn optou conscientemente por não revelar o valor sem a presença da esposa do lead, afirmando que valores são diferentes ''em call'' e ''fora da call''. Lead solicitou explicitamente o valor e foi bloqueado. Essa decisão, embora estratégica para proteger o desconto em call, pode ter gerado frustração e reduzido a probabilidade de fechamento na segunda call."}, {"name": "Preço Protagonista", "score": 0, "stage": 14, "status": "skipped", "weight_pct": 5, "observations": "Não executado. Consequência direta da ausência do Preço Tabela. A estratégia de apresentar o investimento como protagonista do lead (conectado ao ROI e ao cenário de transformação) não ocorreu. Oportunidade perdida de fazer o lead calcular mentalmente o retorno antes de ver o valor real."}, {"name": "Negociação", "score": 0, "stage": 15, "status": "skipped", "weight_pct": 7, "observations": "Não executado. Nenhuma negociação foi conduzida. A call encerrou em reagendamento. Evelyn mencionou que o valor fica ''congelado por até 30 dias'' como alternativa à negociação imediata, mas sem especificar percentuais, condições de parcelamento ou bônus por fechamento imediato que poderiam ter motivado o lead a tomar decisão ainda nesta call."}, {"name": "Down Sell", "score": 0, "stage": 16, "status": "skipped", "weight_pct": 4, "observations": "Não executado. Sem apresentação de valor, sem negociação, não houve oportunidade de aplicar down sell. Nenhuma oferta alternativa de entrada foi apresentada (ex: um diagnóstico pago, acesso a um módulo inicial, período de teste). A call encerrou sem qualquer compromisso financeiro ou comercial do lead."}], "negotiation": {"reason": "Evelyn optou por não revelar o preço sem a presença da esposa do lead, postergando toda a fase de negociação para uma segunda call. Lead solicitou o valor ao menos duas vezes explicitamente e foi redirecionado. A estratégia de proteger o valor ''em call'' gerou tensão e encerrou a conversa sem avanço comercial concreto.", "outcome": "Reagendamento sem data confirmada com presença da esposa. Valor congelado por 30 dias prometido verbalmente.", "reached": false, "anchor_used": false, "price_revealed": false, "close_attempted": false, "risk_assessment": "ALTO — Lead demonstrou interesse genuíno mas sem data de segunda call confirmada, sem urgência estabelecida e com 30 dias de ''janela congelada'', o risco de esfriamento e não-comparecimento é significativo. Lead pode buscar concorrentes ou simplesmente postergar indefinidamente."}, "overall_label": "ok", "overall_score": 6.1, "classification": "BOA", "protocol_version": "16-stage-commercial-audit-v1", "training_actions": [{"action": "Roleplay de Objeção Cônjuge", "format": "Simulação ao vivo com feedback imediato", "frequency": "2x por semana por 30 dias", "description": "Treinar Evelyn e todo o time de closers em pelo menos 3 variações de resposta para objeção de cônjuge como decisor, incluindo a opção de revelar o preço com contexto de urgência controlada e uso de âncoras de ROI antes da revelação.", "responsible": "Gestor comercial / Diretor de vendas"}, {"action": "Treinamento de Ancoragem de Valor", "format": "Workshop interno com script documentado", "frequency": "1x aplicação + revisão mensal", "description": "Criar e documentar script padrão de ancoragem para leads de clínicas em início de carreira cirúrgica, usando dados reais de faturamento (casos como Dra. Débora, pai do lead como prova de conceito) e cálculo de custo de inação. Script deve ser inserido obrigatoriamente antes da apresentação de preço.", "responsible": "Diretor comercial (Renan)"}, {"action": "Checklist de Estágios Finais da Call", "format": "Ferramenta de auto-auditoria em tempo real", "frequency": "Uso em todas as calls", "description": "Criar checklist obrigatório dos estágios 12 a 16 (ancoragem, preço tabela, preço protagonista, negociação, down sell) para que a closer verifique antes de encerrar qualquer call se todos os estágios foram tentados. Calls encerradas sem tentativa de fechamento devem ser justificadas por escrito.", "responsible": "Closer / Supervisão de QA"}, {"action": "Treinamento de SPIN Implicação e Necessidade", "format": "Estudo de caso + roleplay com gravações reais", "frequency": "Sessão semanal por 45 dias", "description": "Usar a transcrição desta call como material de estudo. Identificar os momentos em que perguntas de implicação poderiam ter sido inseridas e praticar as formulações corretas. Foco especial em transformar relatos espontâneos do lead em perguntas de implicação direcionadas pela closer.", "responsible": "Gestor de QA / Coach de vendas"}, {"action": "Protocolo de Segunda Call — Prevenção de No-Show", "format": "SOP documentado + template de confirmação", "frequency": "Imediato — aplicar nesta e em todas as próximas calls", "description": "Toda call encerrada em reagendamento deve: (a) ter data e horário confirmados antes de encerrar a chamada; (b) enviar confirmação por WhatsApp em até 2 horas com link de reunião e resumo do que foi discutido; (c) ter followup D-1 e D-0 antes da segunda call. Neste caso específico, contato com Bruno deve ser feito em até 24h para confirmar data com a esposa presente.", "responsible": "SDR / Closer responsável pelo lead"}], "executive_summary": "Call de diagnóstico de 53 minutos entre a closer Evelyn e o lead Bruno Louzada, dentista clínico geral de Cotia/SP, em transição para cirurgias da face após conclusão do curso FaceCode com Alexandre. O protocolo foi executado de forma parcial: os estágios iniciais de rapport e situacional foram muito bem conduzidos, gerando alto nível de confiança e abertura do lead. A closer demonstra domínio sobre o mercado, empatia e capacidade de construção de vínculo. No entanto, a call encerrou sem apresentação de preço, sem ancoragem de valor, sem negociação efetiva e sem fechamento — todos os estágios finais foram ou zerados ou comprometidos pela decisão de adiar para uma segunda call com a presença da esposa. A gestão de objeção sobre a esposa foi parcialmente acertada (insistência em trazê-la), mas gerou frustração e desengajamento do lead, que solicitava o valor explicitamente. O isolamento de objeções foi executado de forma defensiva e não resolutiva. A call terminou em reagendamento sem data confirmada, o que representa risco real de perda do lead.", "objections_detected": [{"moment": "00:50:49", "handling": "Parcialmente adequado — Evelyn identificou corretamente a esposa como influenciadora e insistiu em incluí-la na segunda call. Porém, não explorou alternativas como apresentar o valor para o lead e deixá-lo decidir em conjunto depois, ou construir a urgência suficiente para o lead querer decidir imediatamente.", "severity": "alta", "objection": "Precisa conversar com a esposa antes de decidir", "resolution": "Não resolvida — call encerrada sem fechamento"}, {"moment": "00:49:41", "handling": "Inadequado — Evelyn bloqueou a revelação do preço com argumento de que há dois tipos de preço (em call e fora dela) e que prefere esperar a esposa estar presente. Lead ficou insatisfeito com a resposta.", "severity": "alta", "objection": "Qual é o valor do programa?", "resolution": "Não resolvida"}, {"moment": "00:05:29", "handling": "Bem tratada — Evelyn validou a transição como oportunidade e apresentou casos de resultado desde o início do processo, incluindo referência ao pai do lead como prova de conceito.", "severity": "média", "objection": "Ainda está começando nas cirurgias da face — incerteza sobre o momento", "resolution": "Parcialmente resolvida"}, {"moment": "00:20:32", "handling": "Bem tratada — Evelyn explicou a lógica de definir o público-alvo e a adequação do consultório ao ICP antes de rodar campanhas. Resposta consultiva e pertinente.", "severity": "baixa", "objection": "Não sabe onde vai atender as cirurgias (Cotia ou Carapicuíba)", "resolution": "Resolvida"}, {"moment": "00:11:38", "handling": "Superficialmente tratada — Evelyn ouviu e reconheceu, mas não diferenciou com clareza suficiente o modelo da System do modelo anterior. Poderia ter explorado o contraste: ''diferente do que você viveu lá, aqui você tem X, Y, Z entregáveis com prazo definido''.", "severity": "média", "objection": "Experiência negativa anterior com serviço de mensalidade (Smile) — sensação de estagnação e custo fixo sem evolução", "resolution": "Parcialmente resolvida"}], "priority_improvements": [{"area": "Ancoragem de Valor", "priority": 1, "description": "Implementar ancoragem estruturada antes da revelação de preço em toda call. Usar o próprio faturamento do lead (R$25-35k/mês) como base de comparação: ''Seu pai fez R$140k em 20 dias. Você hoje faz R$30k em 30 dias. Qual o custo de mais 6 meses sem mudar isso?'' Criar urgência financeira concreta antes de falar em investimento."}, {"area": "Gestão de Objeção Cônjuge", "priority": 2, "description": "Desenvolver script específico para objeção de cônjuge como decisor. Alternativas recomendadas: (a) revelar o valor mesmo sem a esposa presente, validando que o lead pode apresentar internamente com os materiais de apoio; (b) fazer uma âncora de urgência real com prazo limitado e valor congelado com comprovação; (c) perguntar ''o que sua esposa precisaria ver ou ouvir para apoiar essa decisão?'' e responder ao vivo. A abordagem atual de recusar o preço gera frustração e aumenta risco de churn no pipeline."}, {"area": "Fechamento e Tentativa de Decisão em Call", "priority": 3, "description": "A closer deve sempre tentar ao menos uma tentativa de fechamento na mesma call, mesmo que haja objeção de cônjuge. Frases como ''Se dependesse só de você, você fecharia agora?'' permitem medir temperatura e construir o compromisso parcial do lead. A call encerrou sem qualquer tentativa de fechamento, o que é crítico para o pipeline."}, {"area": "SPIN Implicação", "priority": 4, "description": "Inserir perguntas de implicação estruturadas após o mapeamento de problemas. Exemplos aplicáveis a este lead: ''Se você entrar em cirurgias sem processo comercial, o que acontece com os leads que vão chegar e não forem convertidos?'' / ''Você falou que tem três filhos e quer mais tempo. Quanto tempo você acha que vai levar para chegar nesse nível sozinho?'' Ampliar a dor antes de apresentar a solução aumenta a percepção de valor e reduz resistência ao preço."}, {"area": "Entregáveis do Produto — Clareza e Sequência", "priority": 5, "description": "A apresentação do produto gerou uma síntese imprecisa do lead (''é uma mentoria para minha clínica rodar''). Estruturar a apresentação com lista clara de entregáveis, cronograma dos 6 meses e diferencial versus mentoria/agência de forma visual e sequencial. Ao final da apresentação, pedir confirmação: ''De tudo que eu apresentei, o que fez mais sentido para você?''"}]}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"area": "Ancoragem de Valor", "priority": 1, "description": "Implementar ancoragem estruturada antes da revelação de preço em toda call. Usar o próprio faturamento do lead (R$25-35k/mês) como base de comparação: ''Seu pai fez R$140k em 20 dias. Você hoje faz R$30k em 30 dias. Qual o custo de mais 6 meses sem mudar isso?'' Criar urgência financeira concreta antes de falar em investimento."}, {"area": "Gestão de Objeção Cônjuge", "priority": 2, "description": "Desenvolver script específico para objeção de cônjuge como decisor. Alternativas recomendadas: (a) revelar o valor mesmo sem a esposa presente, validando que o lead pode apresentar internamente com os materiais de apoio; (b) fazer uma âncora de urgência real com prazo limitado e valor congelado com comprovação; (c) perguntar ''o que sua esposa precisaria ver ou ouvir para apoiar essa decisão?'' e responder ao vivo. A abordagem atual de recusar o preço gera frustração e aumenta risco de churn no pipeline."}, {"area": "Fechamento e Tentativa de Decisão em Call", "priority": 3, "description": "A closer deve sempre tentar ao menos uma tentativa de fechamento na mesma call, mesmo que haja objeção de cônjuge. Frases como ''Se dependesse só de você, você fecharia agora?'' permitem medir temperatura e construir o compromisso parcial do lead. A call encerrou sem qualquer tentativa de fechamento, o que é crítico para o pipeline."}, {"area": "SPIN Implicação", "priority": 4, "description": "Inserir perguntas de implicação estruturadas após o mapeamento de problemas. Exemplos aplicáveis a este lead: ''Se você entrar em cirurgias sem processo comercial, o que acontece com os leads que vão chegar e não forem convertidos?'' / ''Você falou que tem três filhos e quer mais tempo. Quanto tempo você acha que vai levar para chegar nesse nível sozinho?'' Ampliar a dor antes de apresentar a solução aumenta a percepção de valor e reduz resistência ao preço."}, {"area": "Entregáveis do Produto — Clareza e Sequência", "priority": 5, "description": "A apresentação do produto gerou uma síntese imprecisa do lead (''é uma mentoria para minha clínica rodar''). Estruturar a apresentação com lista clara de entregáveis, cronograma dos 6 meses e diferencial versus mentoria/agência de forma visual e sequencial. Ao final da apresentação, pedir confirmação: ''De tudo que eu apresentei, o que fez mais sentido para você?''"}]'::jsonb, '[{"action": "Roleplay de Objeção Cônjuge", "format": "Simulação ao vivo com feedback imediato", "frequency": "2x por semana por 30 dias", "description": "Treinar Evelyn e todo o time de closers em pelo menos 3 variações de resposta para objeção de cônjuge como decisor, incluindo a opção de revelar o preço com contexto de urgência controlada e uso de âncoras de ROI antes da revelação.", "responsible": "Gestor comercial / Diretor de vendas"}, {"action": "Treinamento de Ancoragem de Valor", "format": "Workshop interno com script documentado", "frequency": "1x aplicação + revisão mensal", "description": "Criar e documentar script padrão de ancoragem para leads de clínicas em início de carreira cirúrgica, usando dados reais de faturamento (casos como Dra. Débora, pai do lead como prova de conceito) e cálculo de custo de inação. Script deve ser inserido obrigatoriamente antes da apresentação de preço.", "responsible": "Diretor comercial (Renan)"}, {"action": "Checklist de Estágios Finais da Call", "format": "Ferramenta de auto-auditoria em tempo real", "frequency": "Uso em todas as calls", "description": "Criar checklist obrigatório dos estágios 12 a 16 (ancoragem, preço tabela, preço protagonista, negociação, down sell) para que a closer verifique antes de encerrar qualquer call se todos os estágios foram tentados. Calls encerradas sem tentativa de fechamento devem ser justificadas por escrito.", "responsible": "Closer / Supervisão de QA"}, {"action": "Treinamento de SPIN Implicação e Necessidade", "format": "Estudo de caso + roleplay com gravações reais", "frequency": "Sessão semanal por 45 dias", "description": "Usar a transcrição desta call como material de estudo. Identificar os momentos em que perguntas de implicação poderiam ter sido inseridas e praticar as formulações corretas. Foco especial em transformar relatos espontâneos do lead em perguntas de implicação direcionadas pela closer.", "responsible": "Gestor de QA / Coach de vendas"}, {"action": "Protocolo de Segunda Call — Prevenção de No-Show", "format": "SOP documentado + template de confirmação", "frequency": "Imediato — aplicar nesta e em todas as próximas calls", "description": "Toda call encerrada em reagendamento deve: (a) ter data e horário confirmados antes de encerrar a chamada; (b) enviar confirmação por WhatsApp em até 2 horas com link de reunião e resumo do que foi discutido; (c) ter followup D-1 e D-0 antes da segunda call. Neste caso específico, contato com Bruno deve ser feito em até 24h para confirmar data com a esposa presente.", "responsible": "SDR / Closer responsável pelo lead"}]'::jsonb, '[{"moment": "00:50:49", "handling": "Parcialmente adequado — Evelyn identificou corretamente a esposa como influenciadora e insistiu em incluí-la na segunda call. Porém, não explorou alternativas como apresentar o valor para o lead e deixá-lo decidir em conjunto depois, ou construir a urgência suficiente para o lead querer decidir imediatamente.", "severity": "alta", "objection": "Precisa conversar com a esposa antes de decidir", "resolution": "Não resolvida — call encerrada sem fechamento"}, {"moment": "00:49:41", "handling": "Inadequado — Evelyn bloqueou a revelação do preço com argumento de que há dois tipos de preço (em call e fora dela) e que prefere esperar a esposa estar presente. Lead ficou insatisfeito com a resposta.", "severity": "alta", "objection": "Qual é o valor do programa?", "resolution": "Não resolvida"}, {"moment": "00:05:29", "handling": "Bem tratada — Evelyn validou a transição como oportunidade e apresentou casos de resultado desde o início do processo, incluindo referência ao pai do lead como prova de conceito.", "severity": "média", "objection": "Ainda está começando nas cirurgias da face — incerteza sobre o momento", "resolution": "Parcialmente resolvida"}, {"moment": "00:20:32", "handling": "Bem tratada — Evelyn explicou a lógica de definir o público-alvo e a adequação do consultório ao ICP antes de rodar campanhas. Resposta consultiva e pertinente.", "severity": "baixa", "objection": "Não sabe onde vai atender as cirurgias (Cotia ou Carapicuíba)", "resolution": "Resolvida"}, {"moment": "00:11:38", "handling": "Superficialmente tratada — Evelyn ouviu e reconheceu, mas não diferenciou com clareza suficiente o modelo da System do modelo anterior. Poderia ter explorado o contraste: ''diferente do que você viveu lá, aqui você tem X, Y, Z entregáveis com prazo definido''.", "severity": "média", "objection": "Experiência negativa anterior com serviço de mensalidade (Smile) — sensação de estagnação e custo fixo sem evolução", "resolution": "Parcialmente resolvida"}]'::jsonb, 'claude-sonnet-4-6', 19658, 6171, 0.1515, '2026-03-28T01:37:11.664988+00:00', '2026-03-28T01:37:11.664988+00:00');
INSERT INTO supervisor_analyses (id, audit_id, organization_id, protocol_version, prompt_version, overall_score, overall_label, classification, executive_summary, raw_json, table_price_presented, silence_applied, who_spoke_first, protagonist_transition_quality, cac_explained, negotiation_firmness, downsell_used, downsell_narrative_quality, priority_improvements, training_actions, objections_detected, modelo_analise, tokens_input, tokens_output, custo_estimado, created_at, updated_at) VALUES ('adaafc04-1533-4737-9205-9844a79d88d9', '06cf2436-1314-417b-811e-c067dfdbf9f8', '4ecd8f2d-d0c5-419c-a5bc-b2e94dca0465', '16-stage-v1.0', '1.0', 5.6, 'REGULAR', 'REGULAR', 'A closer Evelyn conduziu uma call de 74 minutos com a Dra. Karina Vuolo, dentista especializada em harmonização facial e lipo de papada, faturando ~R$20-22k/mês com meta de R$100k. A call apresentou pontos positivos relevantes: rapport genuíno, diagnóstico de dor preciso (baixa conversão/captação), boa apresentação de cases e entusiasmo da lead. Contudo, o protocolo sofreu falhas estruturais críticas: a apresentação do produto ocorreu muito antes do mapeamento completo das dores (SPIN executado parcialmente e fora de ordem), o pacto inicial foi omitido, a ancoragem foi aplicada de forma tecnicamente incorreta (valor R$268k sem credibilidade estabelecida), o isolamento de objeções não foi executado, e a negociação foi conduzida sem autoridade — com Evelyn cedendo a R$3.500/12x sem resistência e pedindo aprovação ao Renan ao vivo, sinalizando fragilidade no processo. A lead demonstrou alto interesse (nota 10, desejo expresso de fechar), mas a ausência de isolamento de objeções e fechamento estruturado resultou em uma negociação aberta e sem confirmação de venda. A call terminou sem conversão concreta.', '{"stages": [{"name": "Quebra-gelo", "score": 7, "stage": 1, "status": "ok", "weight_pct": 3, "observations": "Quebra-gelo natural e espontâneo. Evelyn compartilhou contexto pessoal (chuva em Cascavel), gerou reciprocidade e identificou localização da lead. Houve humor leve e conexão genuína. Ponto fraco: duração um pouco extensa para a função (>2 min) e encerramento abrupto com ''Vamos lá, então, Karina'' sem transição suave para o próximo estágio.", "timestamp_end": "00:02:06", "timestamp_start": "00:00:00"}, {"name": "Rapport", "score": 7, "stage": 2, "status": "ok", "weight_pct": 5, "observations": "Bom rapport construído através de perguntas sobre a trajetória profissional da Karina: formação, especialização, clínica própria, estrutura de equipe e expansão para o Pará. Evelyn demonstrou interesse genuíno e validou respostas com expressões positivas. Ponto negativo: rapport misturou-se com SPIN situação sem delimitação clara, diluindo a fase de conexão emocional pura. A celebração dos cases da lead (''já tem case já!'') foi eficaz como reforço positivo.", "timestamp_end": "00:05:41", "timestamp_start": "00:02:06"}, {"name": "Pacto Inicial", "score": 0, "stage": 3, "status": "skipped", "weight_pct": 5, "observations": "Etapa completamente omitida. Evelyn não estabeleceu as regras do jogo para a reunião: não definiu agenda, não obteve comprometimento da lead com honestidade nas respostas, não alinhou expectativas de tempo nem obteve permissão explícita para fazer perguntas. Isso impactou negativamente o controle da call — a lead fez perguntas no meio da apresentação (ex.: ''Quanto custa uma lipo de papada?'', ''Quem vai fazer cada fatia do bolo?'') desviando o fluxo protocolar várias vezes.", "timestamp_end": null, "timestamp_start": null}, {"name": "SPIN - Situação", "score": 6, "stage": 4, "status": "ok", "weight_pct": 5, "observations": "Levantamento situacional razoável: identificou especialidade (harmonização + lipo de papada iniciante), clínica própria, equipe (secretária + enfermeira), presença no Pará por 8-10 dias/mês, faturamento atual de R$20-22k/mês e meta de R$100k. Pontos negativos: SPIN foi misturado com rapport e apresentação prematura do produto (Evelyn começou a apresentar a System antes de concluir o diagnóstico situacional completo). Perguntas situacionais foram superficiais em algumas áreas — não aprofundou ticket médio atual de harmonização, volume de pacientes, tempo médio de atendimento ou sazonalidade.", "timestamp_end": "00:18:01", "timestamp_start": "00:02:06"}, {"name": "SPIN - Problema", "score": 6, "stage": 5, "status": "ok", "weight_pct": 5, "observations": "Problema central identificado corretamente: baixa conversão de leads (70 leads, zero vendas de lipo), falta de processo comercial, leads não comparecem, secretária sem treinamento em vendas high ticket. A lead confirmou espontaneamente ''vender, converter'' como seu maior desafio. Ponto negativo: o problema foi identificado de forma reativa (a lead revelou) e não extraído ativamente por Evelyn. A pergunta ''o que que você considera mais desafiador?'' foi boa mas veio tardiamente. Evelyn começou a apresentar soluções prematuramente antes de concluir todo o SPIN.", "timestamp_end": "00:21:39", "timestamp_start": "00:05:41"}, {"name": "SPIN - Implicação", "score": 4, "stage": 6, "status": "warning", "weight_pct": 8, "observations": "Implicação foi conduzida de forma superficial e misturada com apresentação de produto. Evelyn fez algumas conexões causa-efeito (''não adianta fazer só marketing, se o comercial não souber o processo, todo trabalho é perdido'', ''queimou dinheiro''), mas não aprofundou as consequências emocionais e financeiras reais do problema para a Karina. Não quantificou a perda: ''70 leads não convertidos × R$9k = R$630k deixados na mesa''. Não explorou o impacto na dependência do marido (tema emocional poderoso que a própria lead citou). A implicação foi didática/racional e não visceral/emocional, perdendo oportunidade de ampliar a dor.", "timestamp_end": "00:20:27", "timestamp_start": "00:08:16"}, {"name": "SPIN - Necessidade", "score": 5, "stage": 7, "status": "ok", "weight_pct": 7, "observations": "Necessidade parcialmente trabalhada. A meta de R$100k foi identificada e conectada ao desejo de liberdade financeira e independência do marido — elemento emocional poderoso revelado pela lead. Evelyn validou (''liberdade financeira e pessoal também'') mas não aprofundou nem fez a lead verbalizar o custo de não resolver o problema. A pergunta ''qual o seu maior objetivo em bater esse faturamento?'' foi excelente e extraiu a motivação real. Contudo, a necessidade de solução não foi suficientemente amarrada antes da transição para apresentação.", "timestamp_end": "00:22:49", "timestamp_start": "00:19:05"}, {"name": "Pacto de Transição", "score": 3, "stage": 8, "status": "critical", "weight_pct": 5, "observations": "Pacto de transição executado de forma muito fraca. A frase ''Vamos lá, vou me apresentar um pouquinho'' foi usada prematuramente (antes de concluir o SPIN) e sem obter comprometimento da lead. Evelyn abriu o mapa mental dizendo ''vou abrir um mapa mental para entender seus objetivos, a partir dele criamos estratégia específica'' — isso é positivo como intenção, mas não configurou um pacto formal com compromisso de reciprocidade. A lead não confirmou explicitamente que, se a solução fizesse sentido, avançaria. Ausência de ''se eu mostrar X, você estaria disposta a Y?''", "timestamp_end": "00:16:40", "timestamp_start": "00:15:31"}, {"name": "Apresentação do Método", "score": 6, "stage": 9, "status": "ok", "weight_pct": 10, "observations": "Apresentação do método estruturada e com clareza razoável. Evelyn apresentou: método ''Face sem K'' / R$100k, histórico de 6 anos da System, perfil dos sócios (Renan e Mateus), cases relevantes (Débora 150k→500k, Sandy 70k em uma semana), diferencial de parceria vs agência. Utilizou compartilhamento de tela e mostrou a mandala de pilares. Pontos negativos: apresentação foi longa (~16 minutos), com repetições e desvios de fluxo por perguntas da lead (que não foram controladas pelo pacto inicial ausente). O case da Débora foi apresentado com inconsistências (ora ''4 meses para 500k'', ora ''dentista de Parauapebas perto de mim'' — coincidência usada bem). Faltou storytelling mais emocional conectado diretamente à dor da Karina.", "timestamp_end": "00:55:43", "timestamp_start": "00:39:05"}, {"name": "Apresentação do Produto", "score": 6, "stage": 10, "status": "ok", "weight_pct": 10, "observations": "Apresentação do produto (programa de 6 meses) razoável: explicou reuniões de onboarding, grupo VIP estratégico + operacional, tutorias diárias, CRM de bônus, gestor de tráfego exclusivo, scripts/playbooks com acesso ilimitado, protocolos de caixa rápida. A divisão entre grupo estratégico (Karina) e operacional (secretária) foi bem explicada. Pontos negativos: apresentação muito técnica/racional sem ancoragem emocional adequada nos benefícios. Não personalizou suficientemente a apresentação ao perfil da Karina (8-10 dias no Pará, secretária única, início com lipo de papada). A pergunta ''de 0 a 10 você daria qual nota?'' foi boa técnica de validação — lead respondeu 10.", "timestamp_end": "01:03:54", "timestamp_start": "00:55:43"}, {"name": "Isolamento de Objeções", "score": 1, "stage": 11, "status": "critical", "weight_pct": 8, "observations": "Etapa praticamente ausente. Quando a lead sinalizou preocupação com o preço (''Tô com medo do valor'', ''minha mão tá gelada''), Evelyn tentou tranquilizar de forma genérica (''conta preso, fica tranquila'') mas não isolou a objeção adequadamente. Não fez perguntas como: ''Além do investimento, existe alguma outra coisa que te impediria de avançar hoje?'' ou ''Se resolvermos a questão financeira, você estaria pronta para começar?''. A objeção financeira emergiu naturalmente (''comprei muita máquina'', ''preciso começar a ganhar'') mas nunca foi formalmente isolada e trabalhada. Isso enfraqueceu toda a negociação subsequente.", "timestamp_end": null, "timestamp_start": null}, {"name": "Ancoragem", "score": 4, "stage": 12, "status": "warning", "weight_pct": 8, "observations": "Ancoragem executada com estrutura correta (analogia do imóvel + valor âncora de R$268k com 75% de desconto) mas com falhas de execução relevantes. Pontos positivos: usou analogia tangível do imóvel, contextualizou diferença entre valor e preço, trouxe o âncora antes do preço real. Pontos negativos: o valor âncora de R$268k não foi construído progressivamente ao longo da call — surgiu de forma abrupta sem base sólida. A pergunta ''se eu te der 75% de desconto, você se tornaria cliente?'' foi respondida com hesitação pela lead (''hoje em potencial não é isso''), sinalizando que o âncora não foi suficientemente convincente. A analogia do imóvel foi genérica demais para uma profissional de saúde de alto nível.", "timestamp_end": "01:06:17", "timestamp_start": "01:04:52"}, {"name": "Preço Tabela", "score": 6, "stage": 13, "status": "ok", "weight_pct": 5, "observations": "Preço tabela apresentado de forma adequada: R$51.000 à vista ou 8x R$740 para o pacote completo de 6 meses. A apresentação foi direta e sem rodeios excessivos. Ponto positivo: Evelyn mencionou cases de resultado imediatamente antes do preço, reforçando valor. Ponto negativo: o parcelamento de 8x R$740 é inconsistente matematicamente (8 × 740 = R$5.920, muito abaixo do R$51k à vista), sugerindo erro de comunicação ou confusão entre modalidades — isso pode ter gerado confusão na lead. Não houve pausa estratégica após revelar o preço para deixar o lead processar.", "timestamp_end": "01:08:00", "timestamp_start": "01:07:35"}, {"name": "Preço Protagonista", "score": 4, "stage": 14, "status": "warning", "weight_pct": 5, "observations": "A técnica do preço protagonista foi parcialmente aplicada ao oferecer opção de ''programa de ativação'' antes do pacote completo como alternativa de entrada. Evelyn perguntou ''o quanto você estaria disposta a investir'' e abriu espaço para negociação. Pontos negativos: a oferta de down-sell foi apresentada prematuramente e sem estrutura clara de o que seria esse programa menor. Não houve uma oferta protagonista claramente definida e apresentada com orgulho antes de entrar em negociação. A transição do preço tabela para a negociação foi muito rápida, sem sustentar o valor do investimento.", "timestamp_end": "01:09:20", "timestamp_start": "01:07:35"}, {"name": "Negociação", "score": 3, "stage": 15, "status": "critical", "weight_pct": 7, "observations": "Negociação conduzida sem autoridade e com múltiplas concessões unilaterais. Evelyn aceitou R$3.500/12x (total R$42k) sem resistência, sem contrapartida e sem consultar limites previamente. Precisou interromper a call para ligar ao Renan ao vivo para aprovação, sinalizando à lead que a closer não tem poder decisório — enfraquecendo a autoridade e criando janela para lead reconsiderar. A lead propôs os termos (''3.500 em 12 vezes'') e Evelyn simplesmente aceitou. Não houve técnica de concessão gradual, não houve pedido de contrapartida (entrada, assinatura, compromisso formal), e o fechamento ficou em aberto com ''vou ligar pro Renan, aguenta aí''.", "timestamp_end": "01:14:29", "timestamp_start": "01:09:20"}, {"name": "Down Sell", "score": 4, "stage": 16, "status": "warning", "weight_pct": 4, "observations": "Down sell mencionado superficialmente (''programa de ativação primeiro, depois upgrade'') mas sem estrutura definida. Evelyn citou a possibilidade de fazer 3 meses em vez de 6 meses, mas não apresentou um produto down sell claro com nome, entregáveis, prazo e preço específico. A oferta alternativa ficou vaga (''faz uma ativação primeiro''). Não foi posicionado como opção legítima e valorosa — pareceu mais uma concessão defensiva do que uma oferta estratégica. A lead não demonstrou interesse no down sell pois sinalizou querer o programa completo mas com condições de pagamento ajustadas.", "timestamp_end": "01:09:20", "timestamp_start": "01:08:00"}], "negotiation": {"result": "Em aberto — Evelyn interrompeu call para consultar Renan; sem confirmação de fechamento", "final_proposal": "R$42.000 em 12x R$3.500 (proposto pela lead, aceito sem resistência)", "authority_signal": "FRACA — closer precisou consultar sócio ao vivo para validar condições, sinalizando ausência de autonomia decisória", "anchor_value_used": "R$268.000 (com 75% de desconto)", "discount_given_pct": 17.6, "objections_handled": [{"objection": "Preço elevado / falta de capital imediato", "effectiveness": "Parcial — gerou avanço na conversa mas sem comprometimento formal", "technique_used": "Suavização emocional + oferta de parcelamento"}], "concession_structure": "Unilateral — lead propôs condições e foram aceitas sem contrapartida ou gradação de concessões", "price_table_presented": "R$51.000 à vista ou 8x R$740", "closing_technique_used": "Nenhuma técnica formal de fechamento identificada"}, "overall_label": "REGULAR", "overall_score": 5.6, "classification": "REGULAR", "protocol_version": "16-stage-v1.0", "training_actions": [{"type": "Role-play", "focus": "Pacto Inicial e controle de fluxo da call", "action_id": 1, "description": "Simular 10 calls com diferentes perfis de lead onde o pacto inicial é executado nos primeiros 5 minutos. Treinar respostas a perguntas fora de ordem (''Ótima pergunta, vou responder isso exatamente quando chegarmos nessa parte — me permite continuar por aqui?''). Avaliar em gravação.", "responsible": "Gestora Comercial + Evelyn", "deadline_days": 7}, {"type": "Treinamento Técnico", "focus": "Isolamento e tratamento de objeções financeiras", "action_id": 2, "description": "Workshop de 2 horas focado exclusivamente em: (1) identificar momento exato de surgimento da objeção, (2) isolar com pergunta padrão, (3) confirmar unicidade, (4) entrar em negociação estruturada com concessões graduais e pedido de contrapartida. Criar script padrão para objeção ''não tenho dinheiro agora''.", "responsible": "Renan / Líder Comercial", "deadline_days": 5}, {"type": "Definição de Processo", "focus": "Limites de negociação e autonomia da closer", "action_id": 3, "description": "Criar tabela de autoridade de negociação: quais condições Evelyn pode conceder autonomamente (parcelamento máximo, desconto máximo, modalidade de entrada mínima) e quando escalar. Eliminar prática de ligar ao gestor durante a call — criar protocolo de ''verificação interna'' com script de saída sem expor estrutura.", "responsible": "Renan + Mateus", "deadline_days": 3}, {"type": "Role-play", "focus": "SPIN Implicação com amplificação emocional", "action_id": 4, "description": "Treinar especificamente a fase de implicação com perguntas de aprofundamento emocional. Praticar silêncio após revelações emocionais do lead. Treinar quantificação de perda: ''Você teve 70 leads e zero conversões — se tivesse convertido 40%, seriam R$252.000. Esse valor faz falta?'' Avaliar qualidade emocional da implicação em gravações.", "responsible": "Gestora Comercial", "deadline_days": 10}, {"type": "Revisão de Material", "focus": "Consistência matemática nas apresentações de preço", "action_id": 5, "description": "Revisar e corrigir inconsistência no parcelamento apresentado (8x R$740 ≠ R$51.000). Criar tabela de preços clara com todas as modalidades (à vista, 6x, 8x, 12x com e sem entrada) para consulta durante call. Evitar erro de comunicação que gera confusão e erosão de confiança.", "responsible": "Time Comercial + Marketing", "deadline_days": 2}, {"type": "Análise de Gravação", "focus": "Revisão individual desta call com feedback estruturado", "action_id": 6, "description": "Sessão de 1 hora com Evelyn revisando os momentos críticos desta call: (1) ausência do pacto inicial, (2) implicação superficial no tema independência financeira, (3) ancoragem sem build-up, (4) negociação sem isolamento de objeção, (5) ligação ao vivo para o Renan. Criar plano de melhoria individual com metas de reauditoria em 30 dias.", "responsible": "Gestora Comercial", "deadline_days": 5}], "executive_summary": "A closer Evelyn conduziu uma call de 74 minutos com a Dra. Karina Vuolo, dentista especializada em harmonização facial e lipo de papada, faturando ~R$20-22k/mês com meta de R$100k. A call apresentou pontos positivos relevantes: rapport genuíno, diagnóstico de dor preciso (baixa conversão/captação), boa apresentação de cases e entusiasmo da lead. Contudo, o protocolo sofreu falhas estruturais críticas: a apresentação do produto ocorreu muito antes do mapeamento completo das dores (SPIN executado parcialmente e fora de ordem), o pacto inicial foi omitido, a ancoragem foi aplicada de forma tecnicamente incorreta (valor R$268k sem credibilidade estabelecida), o isolamento de objeções não foi executado, e a negociação foi conduzida sem autoridade — com Evelyn cedendo a R$3.500/12x sem resistência e pedindo aprovação ao Renan ao vivo, sinalizando fragilidade no processo. A lead demonstrou alto interesse (nota 10, desejo expresso de fechar), mas a ausência de isolamento de objeções e fechamento estruturado resultou em uma negociação aberta e sem confirmação de venda. A call terminou sem conversão concreta.", "objections_detected": [{"id": 1, "type": "Financeira", "notes": "Evelyn tentou tranquilizar mas não isolou, não aprofundou e não converteu em comprometimento", "handled": true, "verbatim": "Eu tô com medo do valor. A minha mão já tá gelada.", "timestamp": "01:07:35", "handling_quality": "Insuficiente"}, {"id": 2, "type": "Financeira / Capital Imediato", "notes": "Evelyn abriu negociação mas cedeu sem estrutura, sem isolar se era a única objeção", "handled": true, "verbatim": "Mas o completo para 51 agora não dá, porque eu comprei muita máquina.", "timestamp": "01:09:20", "handling_quality": "Parcial"}, {"id": 3, "type": "Temporal / Resultado Imediato", "notes": "Objeção de ''preciso ver resultado antes de comprometer o investimento total'' não foi diretamente endereçada com SLA de resultados ou garantias", "handled": false, "verbatim": "Eu preciso começar a ganhar dinheiro para falar assim: Evelyn, bota tudo para mim.", "timestamp": "01:08:49", "handling_quality": "Não tratada"}, {"id": 4, "type": "Entrada / Fluxo de Caixa", "notes": "Evelyn aceitou que não há entrada hoje e propôs parcelar tudo, perdendo leverage para fechar com comprometimento imediato", "handled": false, "verbatim": "Para sexta-feira que vem, aí eu consigo (a entrada).", "timestamp": "01:12:30", "handling_quality": "Não tratada"}], "priority_improvements": [{"issue": "Etapa completamente ausente — lead controlou o ritmo da call fazendo perguntas fora de ordem durante toda a apresentação", "stage": "Pacto Inicial", "priority": 1, "recommended_action": "Implementar pacto inicial estruturado nos primeiros 5 minutos: definir agenda, obter permissão para perguntas, estabelecer comprometimento condicional (''se fizer sentido, você estaria disposta a avançar hoje?'') e alinhar tempo disponível"}, {"issue": "Closer sem autonomia decisória — precisou consultar sócio ao vivo, destruindo autoridade e abrindo janela para lead reconsiderar", "stage": "Negociação / Autoridade", "priority": 2, "recommended_action": "Definir limites de negociação pré-call com autonomia para a closer. Se necessário consultar liderança, ensaiar script de ''vou verificar a melhor condição para você'' sem expor fragilidade estrutural. Nunca interromper call para ligação ao vivo com gestor"}, {"issue": "Objeção financeira surgiu clara e não foi isolada — não se sabe se era a única barreira para fechamento", "stage": "Isolamento de Objeções", "priority": 3, "recommended_action": "Treinar pergunta de isolamento formal: ''Karina, além do investimento, existe alguma outra coisa que te impediria de começar hoje?'' Somente após confirmar que é a única objeção, entrar em negociação"}, {"issue": "Implicação racional/didática sem amplificação emocional das consequências — perdeu o gatilho mais poderoso da call (dependência financeira do marido)", "stage": "SPIN Implicação", "priority": 4, "recommended_action": "Após lead revelar ''o sim e não depende do meu marido'', aprofundar: ''E quanto tempo você já carrega esse peso? Como isso te afeta no dia a dia? O que mudaria na sua vida se você tivesse essa independência?'' Amplificar dor antes de apresentar solução"}, {"issue": "Âncora de R$268k apresentada de forma abrupta sem construção progressiva de valor ao longo da call", "stage": "Ancoragem", "priority": 5, "recommended_action": "Construir âncora ao longo da apresentação: somar valor percebido de cada entregável antes de revelar o âncora total. Ex: ''Só o gestor de tráfego no mercado custa X, o CRM Y, o treinamento Z...'' chegar organicamente ao âncora de R$268k com cada componente justificado"}]}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"issue": "Etapa completamente ausente — lead controlou o ritmo da call fazendo perguntas fora de ordem durante toda a apresentação", "stage": "Pacto Inicial", "priority": 1, "recommended_action": "Implementar pacto inicial estruturado nos primeiros 5 minutos: definir agenda, obter permissão para perguntas, estabelecer comprometimento condicional (''se fizer sentido, você estaria disposta a avançar hoje?'') e alinhar tempo disponível"}, {"issue": "Closer sem autonomia decisória — precisou consultar sócio ao vivo, destruindo autoridade e abrindo janela para lead reconsiderar", "stage": "Negociação / Autoridade", "priority": 2, "recommended_action": "Definir limites de negociação pré-call com autonomia para a closer. Se necessário consultar liderança, ensaiar script de ''vou verificar a melhor condição para você'' sem expor fragilidade estrutural. Nunca interromper call para ligação ao vivo com gestor"}, {"issue": "Objeção financeira surgiu clara e não foi isolada — não se sabe se era a única barreira para fechamento", "stage": "Isolamento de Objeções", "priority": 3, "recommended_action": "Treinar pergunta de isolamento formal: ''Karina, além do investimento, existe alguma outra coisa que te impediria de começar hoje?'' Somente após confirmar que é a única objeção, entrar em negociação"}, {"issue": "Implicação racional/didática sem amplificação emocional das consequências — perdeu o gatilho mais poderoso da call (dependência financeira do marido)", "stage": "SPIN Implicação", "priority": 4, "recommended_action": "Após lead revelar ''o sim e não depende do meu marido'', aprofundar: ''E quanto tempo você já carrega esse peso? Como isso te afeta no dia a dia? O que mudaria na sua vida se você tivesse essa independência?'' Amplificar dor antes de apresentar solução"}, {"issue": "Âncora de R$268k apresentada de forma abrupta sem construção progressiva de valor ao longo da call", "stage": "Ancoragem", "priority": 5, "recommended_action": "Construir âncora ao longo da apresentação: somar valor percebido de cada entregável antes de revelar o âncora total. Ex: ''Só o gestor de tráfego no mercado custa X, o CRM Y, o treinamento Z...'' chegar organicamente ao âncora de R$268k com cada componente justificado"}]'::jsonb, '[{"type": "Role-play", "focus": "Pacto Inicial e controle de fluxo da call", "action_id": 1, "description": "Simular 10 calls com diferentes perfis de lead onde o pacto inicial é executado nos primeiros 5 minutos. Treinar respostas a perguntas fora de ordem (''Ótima pergunta, vou responder isso exatamente quando chegarmos nessa parte — me permite continuar por aqui?''). Avaliar em gravação.", "responsible": "Gestora Comercial + Evelyn", "deadline_days": 7}, {"type": "Treinamento Técnico", "focus": "Isolamento e tratamento de objeções financeiras", "action_id": 2, "description": "Workshop de 2 horas focado exclusivamente em: (1) identificar momento exato de surgimento da objeção, (2) isolar com pergunta padrão, (3) confirmar unicidade, (4) entrar em negociação estruturada com concessões graduais e pedido de contrapartida. Criar script padrão para objeção ''não tenho dinheiro agora''.", "responsible": "Renan / Líder Comercial", "deadline_days": 5}, {"type": "Definição de Processo", "focus": "Limites de negociação e autonomia da closer", "action_id": 3, "description": "Criar tabela de autoridade de negociação: quais condições Evelyn pode conceder autonomamente (parcelamento máximo, desconto máximo, modalidade de entrada mínima) e quando escalar. Eliminar prática de ligar ao gestor durante a call — criar protocolo de ''verificação interna'' com script de saída sem expor estrutura.", "responsible": "Renan + Mateus", "deadline_days": 3}, {"type": "Role-play", "focus": "SPIN Implicação com amplificação emocional", "action_id": 4, "description": "Treinar especificamente a fase de implicação com perguntas de aprofundamento emocional. Praticar silêncio após revelações emocionais do lead. Treinar quantificação de perda: ''Você teve 70 leads e zero conversões — se tivesse convertido 40%, seriam R$252.000. Esse valor faz falta?'' Avaliar qualidade emocional da implicação em gravações.", "responsible": "Gestora Comercial", "deadline_days": 10}, {"type": "Revisão de Material", "focus": "Consistência matemática nas apresentações de preço", "action_id": 5, "description": "Revisar e corrigir inconsistência no parcelamento apresentado (8x R$740 ≠ R$51.000). Criar tabela de preços clara com todas as modalidades (à vista, 6x, 8x, 12x com e sem entrada) para consulta durante call. Evitar erro de comunicação que gera confusão e erosão de confiança.", "responsible": "Time Comercial + Marketing", "deadline_days": 2}, {"type": "Análise de Gravação", "focus": "Revisão individual desta call com feedback estruturado", "action_id": 6, "description": "Sessão de 1 hora com Evelyn revisando os momentos críticos desta call: (1) ausência do pacto inicial, (2) implicação superficial no tema independência financeira, (3) ancoragem sem build-up, (4) negociação sem isolamento de objeção, (5) ligação ao vivo para o Renan. Criar plano de melhoria individual com metas de reauditoria em 30 dias.", "responsible": "Gestora Comercial", "deadline_days": 5}]'::jsonb, '[{"id": 1, "type": "Financeira", "notes": "Evelyn tentou tranquilizar mas não isolou, não aprofundou e não converteu em comprometimento", "handled": true, "verbatim": "Eu tô com medo do valor. A minha mão já tá gelada.", "timestamp": "01:07:35", "handling_quality": "Insuficiente"}, {"id": 2, "type": "Financeira / Capital Imediato", "notes": "Evelyn abriu negociação mas cedeu sem estrutura, sem isolar se era a única objeção", "handled": true, "verbatim": "Mas o completo para 51 agora não dá, porque eu comprei muita máquina.", "timestamp": "01:09:20", "handling_quality": "Parcial"}, {"id": 3, "type": "Temporal / Resultado Imediato", "notes": "Objeção de ''preciso ver resultado antes de comprometer o investimento total'' não foi diretamente endereçada com SLA de resultados ou garantias", "handled": false, "verbatim": "Eu preciso começar a ganhar dinheiro para falar assim: Evelyn, bota tudo para mim.", "timestamp": "01:08:49", "handling_quality": "Não tratada"}, {"id": 4, "type": "Entrada / Fluxo de Caixa", "notes": "Evelyn aceitou que não há entrada hoje e propôs parcelar tudo, perdendo leverage para fechar com comprometimento imediato", "handled": false, "verbatim": "Para sexta-feira que vem, aí eu consigo (a entrada).", "timestamp": "01:12:30", "handling_quality": "Não tratada"}]'::jsonb, 'claude-sonnet-4-6', 27764, 7235, 0.1918, '2026-03-28T01:39:51.740517+00:00', '2026-03-28T01:39:51.740517+00:00');
INSERT INTO supervisor_analyses (id, audit_id, organization_id, protocol_version, prompt_version, overall_score, overall_label, classification, executive_summary, raw_json, table_price_presented, silence_applied, who_spoke_first, protagonist_transition_quality, cac_explained, negotiation_firmness, downsell_used, downsell_narrative_quality, priority_improvements, training_actions, objections_detected, modelo_analise, tokens_input, tokens_output, custo_estimado, created_at, updated_at) VALUES ('0c030f3c-ee45-4310-be50-0700928ee556', '700a5a81-9324-448f-b2a8-8ffe57259645', '4ecd8f2d-d0c5-419c-a5bc-b2e94dca0465', '16-stage-commercial-protocol-v1', '1.0', 1.8, 'critical', 'CRITICA', 'A call analisada representa uma falha estrutural severa no protocolo comercial de 16 etapas. Das 16 etapas obrigatórias, apenas 2 foram minimamente executadas (Quebra-gelo e Apresentação Produto parcial), enquanto 14 etapas foram completamente ignoradas ou skipped. A closer Evelyn não realizou rapport, nenhuma etapa do SPIN Selling, nenhum pacto, nenhuma ancoragem de valor, nenhum isolamento de objeção e nenhuma negociação estruturada. O preço foi revelado de forma reativa, sem contexto de valor, diretamente em resposta à pergunta do lead, resultando em objeção imediata (''preciso pensar'') que foi abandonada sem qualquer tratamento. A call durou aproximadamente 90 segundos e encerrou sem fechamento, sem diagnóstico do lead e sem qualquer mapeamento de necessidade. Risco alto de perda total do lead.', '{"stages": [{"gap": "Quebra-gelo genérico e frio. Ausência total de personalização ou referência à origem do lead.", "score": 2, "status": "critical", "evidence": "A closer disse apenas ''Olá, tudo bem?'' seguido de identificação institucional básica. Não houve personalização, referência ao contexto do lead ou elemento humano que crie abertura emocional.", "stage_id": 1, "stage_name": "Quebra-gelo", "weight_pct": 3, "recommendation": "Utilizar o nome do lead, referenciar a origem do contato e criar um momento leve antes de entrar no contexto comercial."}, {"gap": "Etapa completamente ausente. Sem rapport, o lead não tem razão emocional para continuar engajado.", "score": 0, "status": "skipped", "evidence": "Nenhuma tentativa de criar conexão genuína com o lead. A closer transicionou imediatamente para apresentação do programa sem qualquer construção de vínculo.", "stage_id": 2, "stage_name": "Rapport", "weight_pct": 5, "recommendation": "Dedicar 2 a 3 minutos para descobrir algo sobre o lead, validar sua situação e criar reciprocidade antes de qualquer conteúdo comercial."}, {"gap": "Sem pacto inicial, o lead não tem clareza sobre o que vai acontecer na conversa, gerando resistência passiva.", "score": 0, "status": "skipped", "evidence": "Nenhum acordo sobre agenda, tempo disponível, expectativas da call ou permissão para fazer perguntas foi estabelecido.", "stage_id": 3, "stage_name": "Pacto Inicial", "weight_pct": 5, "recommendation": "Estabelecer combinados claros no início: duração estimada, o que será abordado e o que se espera ao final da conversa."}, {"gap": "Sem diagnóstico situacional, a apresentação é genérica e desconectada da realidade do lead.", "score": 0, "status": "skipped", "evidence": "Nenhuma pergunta situacional foi realizada. A closer não coletou qualquer dado sobre o contexto atual do lead.", "stage_id": 4, "stage_name": "SPIN Situação", "weight_pct": 5, "recommendation": "Perguntar sobre o cenário atual do lead: área de atuação, momento de vida, o que já tentou antes, qual é sua rotina atual."}, {"gap": "Sem mapeamento do problema, a solução apresentada não tem ancoragem emocional ou racional.", "score": 0, "status": "skipped", "evidence": "Nenhuma pergunta sobre dores, frustrações ou desafios foi realizada. A closer não identificou o problema central do lead.", "stage_id": 5, "stage_name": "SPIN Problema", "weight_pct": 5, "recommendation": "Explorar as dores específicas do lead relacionadas à harmonização facial: insegurança, experiências anteriores negativas, impacto na autoestima ou vida profissional."}, {"gap": "Esta é uma das etapas de maior peso e foi completamente ignorada. Sem implicação, o lead não sente urgência para resolver o problema.", "score": 0, "status": "skipped", "evidence": "Nenhuma pergunta de implicação foi realizada. O impacto do problema na vida do lead não foi explorado.", "stage_id": 6, "stage_name": "SPIN Implicação", "weight_pct": 8, "recommendation": "Aprofundar as consequências do problema não resolvido: como isso afeta a confiança, os relacionamentos, a vida profissional ou o bem-estar do lead."}, {"gap": "Sem que o lead verbalize sua necessidade, ele não se apropria do desejo de mudança, tornando o fechamento muito mais difícil.", "score": 0, "status": "skipped", "evidence": "Nenhuma pergunta de necessidade-solução foi realizada. O lead não foi conduzido a verbalizar o que deseja alcançar.", "stage_id": 7, "stage_name": "SPIN Necessidade", "weight_pct": 7, "recommendation": "Fazer perguntas que levem o lead a descrever o resultado desejado: ''Se você resolvesse isso, como seria sua vida?'', ''O que mudaria para você?''"}, {"gap": "A ausência do pacto de transição faz a apresentação parecer um pitch genérico, sem conexão com o que foi diagnosticado.", "score": 0, "status": "skipped", "evidence": "Não houve qualquer transição estruturada entre o diagnóstico e a apresentação da solução.", "stage_id": 8, "stage_name": "Pacto Transição", "weight_pct": 5, "recommendation": "Após o SPIN, criar uma ponte explícita: ''Com base no que você me contou, posso te mostrar como nosso programa resolve exatamente isso?''"}, {"gap": "Sem apresentação do método, o lead não entende o que está comprando nem por que deveria confiar na solução.", "score": 0, "status": "skipped", "evidence": "Nenhuma apresentação de metodologia, processo ou diferencial foi realizada. A closer não explicou como o programa funciona.", "stage_id": 9, "stage_name": "Apresentação Método", "weight_pct": 10, "recommendation": "Apresentar o passo a passo do programa, os pilares da metodologia e os diferenciais que o tornam único e eficaz."}, {"gap": "Apresentação superficial e desconectada das dores do lead. Sem valor construído antes do preço.", "score": 2, "status": "critical", "evidence": "A closer mencionou apenas ''nosso programa é focado em resultados'' e ''trabalhamos com harmonização facial''. Nenhum benefício concreto, entrega, resultado esperado ou prova social foi apresentado.", "stage_id": 10, "stage_name": "Apresentação Produto", "weight_pct": 10, "recommendation": "Construir uma apresentação estruturada com benefícios tangíveis, resultados reais de clientes anteriores e conexão direta com as dores levantadas no SPIN."}, {"gap": "Esta é uma das etapas mais críticas e foi ignorada. A objeção ''preciso pensar'' encerrou a conversa sem resistência da closer.", "score": 0, "status": "skipped", "evidence": "O lead disse ''preciso pensar'' e a objeção foi completamente abandonada. Nenhuma tentativa de isolar, compreender ou tratar a objeção foi realizada.", "stage_id": 11, "stage_name": "Isolamento de Objeções", "weight_pct": 8, "recommendation": "Ao ouvir ''preciso pensar'', isolar a objeção real: ''Além de pensar, tem alguma outra coisa que te impede de avançar hoje?'' e identificar se é preço, confiança, tempo ou outra barreira."}, {"gap": "Sem ancoragem, o preço parece alto e sem contexto. O lead não tem referência para avaliar se o valor é justo.", "score": 0, "status": "skipped", "evidence": "Nenhuma ancoragem de valor foi realizada antes da revelação do preço. O preço de R$ 3.500 foi entregue de forma isolada e fria.", "stage_id": 12, "stage_name": "Ancoragem", "weight_pct": 8, "recommendation": "Antes de revelar o preço, ancorar o valor do resultado: custo do problema não resolvido, comparação com alternativas inferiores e o valor transformacional da solução."}, {"gap": "Preço revelado prematuramente como resposta a uma pergunta do lead, sem preparação ou contexto de valor.", "score": 1, "status": "critical", "evidence": "O preço de R$ 3.500 foi revelado de forma reativa e direta, sem qualquer estrutura de apresentação de preço tabela.", "stage_id": 13, "stage_name": "Preço Tabela", "weight_pct": 5, "recommendation": "O preço tabela deve ser apresentado após toda a construção de valor, com contexto claro de tudo que está incluído, nunca de forma reativa."}, {"gap": "Etapa completamente ausente.", "score": 0, "status": "skipped", "evidence": "Não houve apresentação do preço protagonista nem qualquer estrutura de preço personalizado ao perfil do lead.", "stage_id": 14, "stage_name": "Preço Protagonista", "weight_pct": 5, "recommendation": "Após apresentar o preço tabela, apresentar o preço protagonista com condições específicas e justificativa de valor agregado."}, {"gap": "Sem negociação, a call encerrou sem fechamento e sem qualquer avanço no processo de decisão do lead.", "score": 0, "status": "skipped", "evidence": "Nenhuma negociação foi conduzida. A closer aceitou passivamente o ''preciso pensar'' e encerrou a conversa.", "stage_id": 15, "stage_name": "Negociação", "weight_pct": 7, "recommendation": "Conduzir uma negociação estruturada: reforçar valor, explorar objeções, oferecer condições e criar urgência legítima para a decisão."}, {"gap": "Oportunidade de recuperação perdida. Sem down sell, o lead foi perdido sem alternativa de entrada.", "score": 0, "status": "skipped", "evidence": "Nenhuma oferta alternativa ou down sell foi apresentado após a resistência do lead.", "stage_id": 16, "stage_name": "Down Sell", "weight_pct": 4, "recommendation": "Caso o lead demonstre resistência financeira ou de comprometimento, apresentar uma oferta de entrada menor que permita iniciar o relacionamento."}], "negotiation": {"lead_objection": "Preciso pensar", "close_rate_risk": "muito alto — estimativa de perda superior a 90% sem intervenção no follow-up", "objection_trigger": "Lead perguntou ''Quanto custa?'' após apresentação superficial, sem valor construído", "objection_response": "Preço revelado de forma direta e reativa: R$ 3.500", "negotiation_outcome": "Sem fechamento. Lead postergou decisão sem compromisso real.", "missed_opportunities": ["Não isolou a objeção real por trás do ''preciso pensar''", "Não reforçou valor antes de aceitar o adiamento", "Não criou urgência legítima", "Não ofereceu down sell como alternativa", "Não obteve compromisso concreto para o retorno", "Não identificou se a objeção era financeira, de confiança ou de tempo"], "negotiation_attempted": false, "closer_response_to_objection": "Aceitação passiva da objeção e proposta de retorno no dia seguinte"}, "overall_label": "critical", "overall_score": 1.8, "classification": "CRITICA", "protocol_version": "16-stage-commercial-protocol-v1", "training_actions": [{"type": "treinamento_imediato", "title": "Imersão em SPIN Selling", "format": "roleplay supervisionado + feedback gravado", "urgency": "imediata", "action_id": 1, "description": "Treinamento intensivo nas 4 camadas do SPIN com roleplay de pelo menos 10 simulações até que as perguntas sejam fluidas e naturais. Foco especial em Implicação e Necessidade."}, {"type": "treinamento_imediato", "title": "Protocolo de tratamento de objeções", "format": "script + roleplay + escuta de calls modelo", "urgency": "imediata", "action_id": 2, "description": "Treinar as 5 objeções mais comuns do produto com script de isolamento, qualificação e resposta. Incluir ''preciso pensar'', ''está caro'', ''vou falar com meu cônjuge'', ''não é o momento'' e ''já tentei antes''."}, {"type": "treinamento_imediato", "title": "Estrutura completa do protocolo de 16 etapas", "format": "workshop + material de referência impresso", "urgency": "imediata", "action_id": 3, "description": "Revisão integral do protocolo com mapa visual de cada etapa, critérios de aprovação e exemplos de falas para cada momento da conversa."}, {"type": "monitoramento", "title": "Escuta de calls por 30 dias", "format": "auditoria diária com scorecard", "urgency": "imediata", "action_id": 4, "description": "Todas as calls da closer Evelyn devem ser revisadas pelo supervisor comercial nos próximos 30 dias, com feedback estruturado baseado no scorecard das 16 etapas após cada call."}, {"type": "desenvolvimento", "title": "Construção de repertório de rapport e quebra-gelo", "format": "banco de scripts + prática em dupla", "urgency": "curto prazo", "action_id": 5, "description": "Desenvolver banco de perguntas e abordagens personalizadas para os primeiros 3 minutos da call, segmentadas por perfil de lead."}, {"type": "desenvolvimento", "title": "Treinamento em ancoragem de valor e apresentação de preço", "format": "treinamento prático com simulação de fechamento", "urgency": "curto prazo", "action_id": 6, "description": "Ensinar a técnica de ancoragem de valor antes da revelação de preço, incluindo comparação com custo do problema, custo de oportunidade e projeção de resultado."}, {"type": "acompanhamento", "title": "Meta de requalificação", "format": "avaliação formal com scorecard + devolutiva documentada", "urgency": "curto prazo", "action_id": 7, "description": "Estabelecer meta de score mínimo 6.0 no protocolo de 16 etapas dentro de 21 dias. Nova auditoria formal após o período de treinamento para avaliação de progresso."}], "executive_summary": "A call analisada representa uma falha estrutural severa no protocolo comercial de 16 etapas. Das 16 etapas obrigatórias, apenas 2 foram minimamente executadas (Quebra-gelo e Apresentação Produto parcial), enquanto 14 etapas foram completamente ignoradas ou skipped. A closer Evelyn não realizou rapport, nenhuma etapa do SPIN Selling, nenhum pacto, nenhuma ancoragem de valor, nenhum isolamento de objeção e nenhuma negociação estruturada. O preço foi revelado de forma reativa, sem contexto de valor, diretamente em resposta à pergunta do lead, resultando em objeção imediata (''preciso pensar'') que foi abandonada sem qualquer tratamento. A call durou aproximadamente 90 segundos e encerrou sem fechamento, sem diagnóstico do lead e sem qualquer mapeamento de necessidade. Risco alto de perda total do lead.", "objections_detected": [{"type": "preço_prematuro", "moment": "00:01:30 — imediatamente após apresentação superficial", "phrase": "Quanto custa?", "root_cause": "Lead não recebeu valor suficiente para justificar interesse na solução antes de questionar preço", "objection_id": 1, "closer_handling": "Respondeu diretamente com o valor sem ancoragem", "recommended_handling": "Redirecionar: ''Ótima pergunta, vou chegar lá. Antes, preciso entender melhor sua situação para saber qual opção faz mais sentido para você. Posso te fazer algumas perguntas?''"}, {"type": "adiamento_decisao", "moment": "00:01:30 — imediatamente após revelação do preço", "phrase": "Preciso pensar", "root_cause": "Ausência total de valor construído, diagnóstico e rapport. Lead não teve razão para decidir.", "objection_id": 2, "closer_handling": "Aceitação passiva com proposta de ligação no dia seguinte", "recommended_handling": "Isolar: ''Entendo, faz sentido. Me ajuda a entender, além de pensar, tem algo específico que te gera dúvida? É sobre o investimento, sobre como funciona ou sobre outra coisa?''"}], "priority_improvements": [{"area": "SPIN Selling completo", "impact": "crítico", "priority": 1, "description": "As 4 etapas do SPIN foram completamente ignoradas. Sem diagnóstico, nenhuma apresentação será eficaz. A closer deve dominar e executar as perguntas de Situação, Problema, Implicação e Necessidade antes de qualquer apresentação."}, {"area": "Construção de valor antes do preço", "impact": "crítico", "priority": 2, "description": "O preço foi revelado de forma reativa sem qualquer ancoragem. O lead não tinha contexto de valor para avaliar o investimento. Nunca revelar preço antes de apresentar método, produto e resultados esperados."}, {"area": "Tratamento de objeções", "impact": "crítico", "priority": 3, "description": "A objeção ''preciso pensar'' foi aceita sem qualquer resistência estruturada. A closer deve aprender a isolar, qualificar e tratar objeções antes de aceitar adiamentos."}, {"area": "Rapport e conexão emocional", "impact": "alto", "priority": 4, "description": "A call foi fria e transacional do início ao fim. Sem rapport, o lead não tem razão emocional para confiar na closer ou na solução."}, {"area": "Pactos estruturantes", "impact": "alto", "priority": 5, "description": "Pacto Inicial e Pacto de Transição são ferramentas de controle da conversa. Sem eles, a call deriva para onde o lead conduz, resultando em perguntas prematuras de preço e resistência."}, {"area": "Ancoragem e estrutura de preço", "impact": "alto", "priority": 6, "description": "A apresentação de preço deve seguir uma sequência: ancoragem de valor, preço tabela contextualizado e preço protagonista. A closer deve ser treinada nessa sequência obrigatória."}]}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"area": "SPIN Selling completo", "impact": "crítico", "priority": 1, "description": "As 4 etapas do SPIN foram completamente ignoradas. Sem diagnóstico, nenhuma apresentação será eficaz. A closer deve dominar e executar as perguntas de Situação, Problema, Implicação e Necessidade antes de qualquer apresentação."}, {"area": "Construção de valor antes do preço", "impact": "crítico", "priority": 2, "description": "O preço foi revelado de forma reativa sem qualquer ancoragem. O lead não tinha contexto de valor para avaliar o investimento. Nunca revelar preço antes de apresentar método, produto e resultados esperados."}, {"area": "Tratamento de objeções", "impact": "crítico", "priority": 3, "description": "A objeção ''preciso pensar'' foi aceita sem qualquer resistência estruturada. A closer deve aprender a isolar, qualificar e tratar objeções antes de aceitar adiamentos."}, {"area": "Rapport e conexão emocional", "impact": "alto", "priority": 4, "description": "A call foi fria e transacional do início ao fim. Sem rapport, o lead não tem razão emocional para confiar na closer ou na solução."}, {"area": "Pactos estruturantes", "impact": "alto", "priority": 5, "description": "Pacto Inicial e Pacto de Transição são ferramentas de controle da conversa. Sem eles, a call deriva para onde o lead conduz, resultando em perguntas prematuras de preço e resistência."}, {"area": "Ancoragem e estrutura de preço", "impact": "alto", "priority": 6, "description": "A apresentação de preço deve seguir uma sequência: ancoragem de valor, preço tabela contextualizado e preço protagonista. A closer deve ser treinada nessa sequência obrigatória."}]'::jsonb, '[{"type": "treinamento_imediato", "title": "Imersão em SPIN Selling", "format": "roleplay supervisionado + feedback gravado", "urgency": "imediata", "action_id": 1, "description": "Treinamento intensivo nas 4 camadas do SPIN com roleplay de pelo menos 10 simulações até que as perguntas sejam fluidas e naturais. Foco especial em Implicação e Necessidade."}, {"type": "treinamento_imediato", "title": "Protocolo de tratamento de objeções", "format": "script + roleplay + escuta de calls modelo", "urgency": "imediata", "action_id": 2, "description": "Treinar as 5 objeções mais comuns do produto com script de isolamento, qualificação e resposta. Incluir ''preciso pensar'', ''está caro'', ''vou falar com meu cônjuge'', ''não é o momento'' e ''já tentei antes''."}, {"type": "treinamento_imediato", "title": "Estrutura completa do protocolo de 16 etapas", "format": "workshop + material de referência impresso", "urgency": "imediata", "action_id": 3, "description": "Revisão integral do protocolo com mapa visual de cada etapa, critérios de aprovação e exemplos de falas para cada momento da conversa."}, {"type": "monitoramento", "title": "Escuta de calls por 30 dias", "format": "auditoria diária com scorecard", "urgency": "imediata", "action_id": 4, "description": "Todas as calls da closer Evelyn devem ser revisadas pelo supervisor comercial nos próximos 30 dias, com feedback estruturado baseado no scorecard das 16 etapas após cada call."}, {"type": "desenvolvimento", "title": "Construção de repertório de rapport e quebra-gelo", "format": "banco de scripts + prática em dupla", "urgency": "curto prazo", "action_id": 5, "description": "Desenvolver banco de perguntas e abordagens personalizadas para os primeiros 3 minutos da call, segmentadas por perfil de lead."}, {"type": "desenvolvimento", "title": "Treinamento em ancoragem de valor e apresentação de preço", "format": "treinamento prático com simulação de fechamento", "urgency": "curto prazo", "action_id": 6, "description": "Ensinar a técnica de ancoragem de valor antes da revelação de preço, incluindo comparação com custo do problema, custo de oportunidade e projeção de resultado."}, {"type": "acompanhamento", "title": "Meta de requalificação", "format": "avaliação formal com scorecard + devolutiva documentada", "urgency": "curto prazo", "action_id": 7, "description": "Estabelecer meta de score mínimo 6.0 no protocolo de 16 etapas dentro de 21 dias. Nova auditoria formal após o período de treinamento para avaliação de progresso."}]'::jsonb, '[{"type": "preço_prematuro", "moment": "00:01:30 — imediatamente após apresentação superficial", "phrase": "Quanto custa?", "root_cause": "Lead não recebeu valor suficiente para justificar interesse na solução antes de questionar preço", "objection_id": 1, "closer_handling": "Respondeu diretamente com o valor sem ancoragem", "recommended_handling": "Redirecionar: ''Ótima pergunta, vou chegar lá. Antes, preciso entender melhor sua situação para saber qual opção faz mais sentido para você. Posso te fazer algumas perguntas?''"}, {"type": "adiamento_decisao", "moment": "00:01:30 — imediatamente após revelação do preço", "phrase": "Preciso pensar", "root_cause": "Ausência total de valor construído, diagnóstico e rapport. Lead não teve razão para decidir.", "objection_id": 2, "closer_handling": "Aceitação passiva com proposta de ligação no dia seguinte", "recommended_handling": "Isolar: ''Entendo, faz sentido. Me ajuda a entender, além de pensar, tem algo específico que te gera dúvida? É sobre o investimento, sobre como funciona ou sobre outra coisa?''"}]'::jsonb, 'claude-sonnet-4-6', 601, 5361, 0.0822, '2026-03-28T01:42:35.08672+00:00', '2026-03-28T01:42:35.08672+00:00');
