ustification": "Não houve down sell.", "suggested_fix": ["Não aplicável"], "missed_actions": ["Não aplicável - conteúdo educativo"], "evidence_excerpt": ""}], "negotiation": {"cac_explained": false, "downsell_used": false, "silence_applied": false, "who_spoke_first": null, "negotiation_firmness": null, "table_price_presented": false, "downsell_narrative_quality": null, "protagonist_transition_quality": null}, "overall_label": "skipped", "overall_score": 0, "classification": "CRITICA", "protocol_version": "v1.0", "training_actions": [{"type": "observacao", "focus": "contexto_comercial", "description": "Esta transcrição é de uma tutoria educativa sobre perfis DISC, não uma call de vendas", "responsible": "auditor", "deadline_days": 1}], "executive_summary": "Esta transcrição não representa uma call comercial de vendas, mas sim uma tutoria educativa sobre temperamentos e perfil DISC. O conteúdo é puramente educacional, sem processo de vendas, lead qualificado ou tentativa de fechamento. Não é aplicável a avaliação do protocolo comercial de 16 etapas.", "objections_detected": [], "priority_improvements": [{"issue": "Conteúdo não é uma call comercial", "stage": "identificacao_contexto", "priority": 1, "recommended_action": "Providenciar transcrições de calls comerciais reais para avaliação"}]}'::jsonb, false, false, NULL, NULL, false, NULL, false, NULL, '[{"issue": "Conteúdo não é uma call comercial", "stage": "identificacao_contexto", "priority": 1, "recommended_action": "Providenciar transcrições de calls comerciais reais para avaliação"}]'::jsonb, '[{"type": "observacao", "focus": "contexto_comercial", "description": "Esta transcrição é de uma tutoria educativa sobre perfis DISC, não uma call de vendas", "responsible": "auditor", "deadline_days": 1}]'::jsonb, '[]'::jsonb, 'claude-sonnet-4-20250514', 18884, 2245, 0.0903, '2026-03-28T17:30:46.92147+00:00', '2026-03-28T17:30:46.92147+00:00');
INSERT INTO supervisor_analyses (id, audit_id, organization_id, protocol_version, prompt_version, overall_score, overall_label, classification, executive_summary, raw_json, table_price_presented, silence_applied, who_spoke_first, protagonist_transition_quality, cac_explained, negotiation_firmness, downsell_used, downsell_narrative_quality, priority_improvements, training_actions, objections_detected, modelo_analise, tokens_input, tokens_output, custo_estimado, created_at, updated_at) VALUES ('5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'e9a06962-8693-4977-b0aa-69d6df9552ed', '4ecd8f2d-d0c5-419c-a5bc-b2e94dca0465', 'v1.0', '1.0', 6.8, 'Boa performance com oportunidades de melhoria', 'REGULAR', 'Evelyn demonstrou habilidades comerciais sólidas com boa condução do rapport, identificação eficaz de necessidades através do SPIN e apresentação estruturada da metodologia. Pontos fortes incluem construção de relacionamento, diagnóstico comercial e negociação flexível. Principais oportunidades: pactos mais claros, ancoragem mais assertiva, isolamento formal de objeções e fechamento mais firme no final.', '{"stages": [{"name": "Quebra-gelo", "score": 8, "stage": 1, "status": "excellent", "weight_pct": 3, "observations": "Quebra-gelo natural sobre localização geográfica (Bahia vs Paraná), criando conexão através de diferenças culturais.", "timestamp_end": "00:01:30", "timestamp_start": "00:00:00"}, {"name": "Rapport", "score": 9, "stage": 2, "status": "excellent", "weight_pct": 5, "observations": "Excelente rapport construído com apresentação pessoal detalhada, compartilhamento de experiência empresarial própria e identificação com desafios do lead.", "timestamp_end": "00:04:51", "timestamp_start": "00:01:30"}, {"name": "Pacto Inicial", "score": 5, "stage": 3, "status": "warning", "weight_pct": 5, "observations": "Pacto implícito mas não formal. Mencionou que Carol passou interesse do lead, mas não estabeleceu acordo claro sobre objetivos da call.", "timestamp_end": "00:05:30", "timestamp_start": "00:04:51"}, {"name": "SPIN Situação", "score": 8, "stage": 4, "status": "excellent", "weight_pct": 5, "observations": "Investigação eficaz da situação atual: 6 meses de consultório próprio, trabalho paralelo na franquia, faturamento de 20-30k, gestão solo.", "timestamp_end": "00:10:08", "timestamp_start": "00:05:30"}, {"name": "SPIN Problema", "score": 9, "stage": 5, "status": "excellent", "weight_pct": 5, "observations": "Identificou problemas principais: tickets baixos (2-3k), leads desqualificados (100 mensagens, 8-10 conversões), falta de estrutura comercial.", "timestamp_end": "00:14:40", "timestamp_start": "00:10:08"}, {"name": "SPIN Implicação", "score": 7, "stage": 6, "status": "ok", "weight_pct": 8, "observations": "Expandiu implicações dos problemas: frustração, comparação com concorrentes, ansiedade na condução comercial, oportunidades perdidas.", "timestamp_end": "00:18:01", "timestamp_start": "00:14:40"}, {"name": "SPIN Necessidade", "score": 8, "stage": 7, "status": "excellent", "weight_pct": 7, "observations": "Lead expressou necessidade clara de dobrar faturamento (objetivo de 50k), melhorar estrutura comercial e ter suporte na condução de vendas.", "timestamp_end": "00:20:54", "timestamp_start": "00:18:01"}, {"name": "Pacto de Transição", "score": 4, "stage": 8, "status": "warning", "weight_pct": 5, "observations": "Transição direta para apresentação sem pacto formal. Faltou confirmar se o lead queria conhecer as soluções disponíveis.", "timestamp_end": "00:21:30", "timestamp_start": "00:20:54"}, {"name": "Apresentação Método", "score": 8, "stage": 9, "status": "excellent", "weight_pct": 10, "observations": "Apresentação estruturada da System Digital: 6 anos de mercado, não é agência nem mentoria mas parceiro, foco em demanda qualificada e comercial.", "timestamp_end": "00:29:03", "timestamp_start": "00:21:30"}, {"name": "Apresentação Produto", "score": 7, "stage": 10, "status": "ok", "weight_pct": 10, "observations": "Apresentou programa de ativação (3 meses) adequado ao perfil, explicou estrutura dos 30-60-90 dias, diferenciou de programa master.", "timestamp_end": "00:37:52", "timestamp_start": "00:29:03"}, {"name": "Isolamento de Objeções", "score": 5, "stage": 11, "status": "warning", "weight_pct": 8, "observations": "Não isolou objeções formalmente. Lead demonstrou interesse mas mencionou necessidade de pensar (financeiro + conhecer mais).", "timestamp_end": "00:44:34", "timestamp_start": "00:42:56"}, {"name": "Ancoragem", "score": 6, "stage": 12, "status": "ok", "weight_pct": 8, "observations": "Ancoragem presente mas não assertiva: mencionou soluções de 5k a 60k, mas poderia ter sido mais estratégica na ordem de apresentação.", "timestamp_end": "00:29:00", "timestamp_start": "00:28:00"}, {"name": "Preço de Tabela", "score": 8, "stage": 13, "status": "excellent", "weight_pct": 5, "observations": "Apresentou preço tabela claramente: 16.500 à vista ou 19.000 parcelado em 12x com juros.", "timestamp_end": "00:46:24", "timestamp_start": "00:44:34"}, {"name": "Preço Protagonista", "score": 4, "stage": 14, "status": "warning", "weight_pct": 5, "observations": "Não aplicou silêncio estratégico. Lead imediatamente disse ''preciso pensar'' e Evelyn não deixou a pressão natural acontecer.", "timestamp_end": "00:47:56", "timestamp_start": "00:46:24"}, {"name": "Negociação", "score": 7, "stage": 15, "status": "ok", "weight_pct": 7, "observations": "Negociação ativa com redução de juros e entrada flexível. Conseguiu reduzir de 19k para 17.881, mas lead não fechou por questões financeiras.", "timestamp_end": "00:57:00", "timestamp_start": "00:47:56"}, {"name": "Down Sell", "score": 3, "stage": 16, "status": "critical", "weight_pct": 4, "observations": "Não apresentou opções de down sell. Poderia ter oferecido consultoria pontual ou produto menor para iniciar relacionamento.", "timestamp_end": "00:59:32", "timestamp_start": "00:57:00"}], "negotiation": {"result": "Lead não fechou, disse que pensaria e daria resposta no dia seguinte", "cac_explained": false, "downsell_used": false, "silence_applied": false, "who_spoke_first": "lead", "anchor_value_used": "soluções de 5k a 60k", "discount_given_pct": 6, "negotiation_firmness": 6, "price_table_presented": "16.500 à vista ou 19.000 parcelado em 12x", "table_price_presented": true, "downsell_narrative_quality": null, "protagonist_transition_quality": 4}, "overall_label": "Boa performance com oportunidades de melhoria", "overall_score": 6.8, "classification": "REGULAR", "protocol_version": "v1.0", "training_actions": [{"type": "role_play", "focus": "Técnica de silêncio pós-preço", "description": "Praticar apresentação de preço com silêncio de 10-15 segundos", "responsible": "Gestor Comercial", "deadline_days": 7}, {"type": "script_review", "focus": "Pactos e transições", "description": "Revisar e praticar scripts de pacto inicial e de transição", "responsible": "Treinador de Vendas", "deadline_days": 14}, {"type": "product_training", "focus": "Opções de down sell", "description": "Criar e treinar apresentação de produtos menores/entrada", "responsible": "Gerente de Produtos", "deadline_days": 21}], "executive_summary": "Evelyn demonstrou habilidades comerciais sólidas com boa condução do rapport, identificação eficaz de necessidades através do SPIN e apresentação estruturada da metodologia. Pontos fortes incluem construção de relacionamento, diagnóstico comercial e negociação flexível. Principais oportunidades: pactos mais claros, ancoragem mais assertiva, isolamento formal de objeções e fechamento mais firme no final.", "objections_detected": [{"id": 1, "type": "financeira", "notes": "Closer iniciou negociação ativa para resolver objeção financeira", "handled": true, "verbatim": "que pensar. que eu tenho interesse, eu tenho que pensar sobre isso", "timestamp": "00:46:24", "handling_quality": "boa"}, {"id": 2, "type": "autoridade/conhecimento", "notes": "Não investigou profundamente o que mais precisava conhecer", "handled": false, "verbatim": "Eu quero fechar, entendeu? Só quero conhecer mais", "timestamp": "00:55:01", "handling_quality": "fraca"}], "priority_improvements": [{"issue": "Falta de pacto formal no início da call", "stage": "Pacto Inicial", "priority": 1, "recommended_action": "Estabelecer acordo claro sobre objetivos e expectativas da reunião"}, {"issue": "Não aplicou silêncio estratégico após apresentar preço", "stage": "Preço Protagonista", "priority": 2, "recommended_action": "Treinar técnica de silêncio - deixar lead falar primeiro após apresentação do valor"}, {"issue": "Não ofereceu alternativas menores quando lead não fechou", "stage": "Down Sell", "priority": 3, "recommended_action": "Desenvolver opções de entrada (consultoria, diagnóstico) para iniciar relacionamento"}]}'::jsonb, true, false, 'lead', 4.0, false, 6.0, false, NULL, '[{"issue": "Falta de pacto formal no início da call", "stage": "Pacto Inicial", "priority": 1, "recommended_action": "Estabelecer acordo claro sobre objetivos e expectativas da reunião"}, {"issue": "Não aplicou silêncio estratégico após apresentar preço", "stage": "Preço Protagonista", "priority": 2, "recommended_action": "Treinar técnica de silêncio - deixar lead falar primeiro após apresentação do valor"}, {"issue": "Não ofereceu alternativas menores quando lead não fechou", "stage": "Down Sell", "priority": 3, "recommended_action": "Desenvolver opções de entrada (consultoria, diagnóstico) para iniciar relacionamento"}]'::jsonb, '[{"type": "role_play", "focus": "Técnica de silêncio pós-preço", "description": "Praticar apresentação de preço com silêncio de 10-15 segundos", "responsible": "Gestor Comercial", "deadline_days": 7}, {"type": "script_review", "focus": "Pactos e transições", "description": "Revisar e praticar scripts de pacto inicial e de transição", "responsible": "Treinador de Vendas", "deadline_days": 14}, {"type": "product_training", "focus": "Opções de down sell", "description": "Criar e treinar apresentação de produtos menores/entrada", "responsible": "Gerente de Produtos", "deadline_days": 21}]'::jsonb, '[{"id": 1, "type": "financeira", "notes": "Closer iniciou negociação ativa para resolver objeção financeira", "handled": true, "verbatim": "que pensar. que eu tenho interesse, eu tenho que pensar sobre isso", "timestamp": "00:46:24", "handling_quality": "boa"}, {"id": 2, "type": "autoridade/conhecimento", "notes": "Não investigou profundamente o que mais precisava conhecer", "handled": false, "verbatim": "Eu quero fechar, entendeu? Só quero conhecer mais", "timestamp": "00:55:01", "handling_quality": "fraca"}]'::jsonb, 'claude-sonnet-4-20250514', 16873, 3068, 0.0966, '2026-03-28T19:30:27.865605+00:00', '2026-03-28T19:30:27.865605+00:00');
INSERT INTO supervisor_analyses (id, audit_id, organization_id, protocol_version, prompt_version, overall_score, overall_label, classification, executive_summary, raw_json, table_price_presented, silence_applied, who_spoke_first, protagonist_transition_quality, cac_explained, negotiation_firmness, downsell_used, downsell_narrative_quality, priority_improvements, training_actions, objections_detected, modelo_analise, tokens_input, tokens_output, custo_estimado, created_at, updated_at) VALUES ('614830f2-c07c-4902-9706-6dd78bb35fc2', '94f54fba-e9e5-4756-9d2f-83af7e1d7a73', '4ecd8f2d-d0c5-419c-a5bc-b2e94dca0465', 'v1.0', '1.0', 4.2, 'Desempenho REGULAR com falhas críticas em estrutura comercial', 'REGULAR', 'A closer Evelyn demonstrou boa capacidade de apresentação e rapport, mas falhou criticamente na aplicação do protocolo comercial estruturado. Não executou SPIN selling, não fez ancoragem de valor adequada, perdeu controle da negociação ao aceitar passivamente as objeções financeiras do lead sem aplicar técnicas de contorno. A apresentação foi extensa mas sem foco comercial estratégico.', '{"stages": [{"name": "Quebra-gelo", "score": 7, "stage": 1, "status": "ok", "weight_pct": 3, "observations": "Início adequado com apresentação pessoal e conexão sobre origem italiana, criou ambiente descontraído", "timestamp_end": "00:04:03", "timestamp_start": "00:03:04"}, {"name": "Rapport", "score": 8, "stage": 2, "status": "excellent", "weight_pct": 5, "observations": "Excelente conexão através da origem italiana comum, descontração adequada, família se sentiu à vontade", "timestamp_end": "00:13:04", "timestamp_start": "00:11:40"}, {"name": "Pacto Inicial", "score": 6, "stage": 3, "status": "ok", "weight_pct": 5, "observations": "Fez pacto básico mencionando análises e adequação, mas sem estrutura clara de expectativas mútuas", "timestamp_end": "00:05:33", "timestamp_start": "00:04:03"}, {"name": "SPIN Situação", "score": 5, "stage": 4, "status": "warning", "weight_pct": 5, "observations": "Questionou superficialmente sobre estrutura da clínica, mas sem profundidade estratégica sobre situação atual", "timestamp_end": "00:14:05", "timestamp_start": "00:08:10"}, {"name": "SPIN Problema", "score": 4, "stage": 5, "status": "warning", "weight_pct": 5, "observations": "Identificou problemas básicos (dependência de indicação, falta de processo), mas sem exploração profunda das dores", "timestamp_end": "00:20:36", "timestamp_start": "00:17:25"}, {"name": "SPIN Implicação", "score": 2, "stage": 6, "status": "critical", "weight_pct": 8, "observations": "Falha crítica: não explorou implicações dos problemas identificados, não agravou as consequências da situação atual", "timestamp_end": "00:21:46", "timestamp_start": "00:20:36"}, {"name": "SPIN Necessidade", "score": 3, "stage": 7, "status": "critical", "weight_pct": 7, "observations": "Não construiu necessidade de mudança adequadamente, apenas assumiu que precisavam da solução", "timestamp_end": "00:28:16", "timestamp_start": "00:21:46"}, {"name": "Pacto de Transição", "score": 7, "stage": 8, "status": "ok", "weight_pct": 5, "observations": "Fez transição adequada para apresentação perguntando se fazia sentido apresentar metodologia", "timestamp_end": "00:35:08", "timestamp_start": "00:34:02"}, {"name": "Apresentação Método", "score": 7, "stage": 9, "status": "ok", "weight_pct": 10, "observations": "Apresentação estruturada dos 8 pilares, boa didática, mas muito extensa sem foco comercial", "timestamp_end": "00:52:39", "timestamp_start": "00:35:08"}, {"name": "Apresentação Produto", "score": 6, "stage": 10, "status": "ok", "weight_pct": 10, "observations": "Mostrou execução e acompanhamento, mas sem personalização para dores específicas do lead", "timestamp_end": "01:06:26", "timestamp_start": "00:58:15"}, {"name": "Isolamento de Objeções", "score": 2, "stage": 11, "status": "critical", "weight_pct": 8, "observations": "Falha crítica: não isolou objeções, aceitou passivamente o ''só financeiro'' sem investigar outras resistências", "timestamp_end": "00:58:15", "timestamp_start": "00:58:15"}, {"name": "Ancoragem", "score": 3, "stage": 12, "status": "critical", "weight_pct": 8, "observations": "Ancoragem fraca com R$ 268.000, sem impacto emocional adequado, não usou silêncio após apresentação", "timestamp_end": "01:12:03", "timestamp_start": "01:10:58"}, {"name": "Preço de Tabela", "score": 5, "stage": 13, "status": "warning", "weight_pct": 5, "observations": "Apresentou preço de R$ 51.000 à vista ou 8x R$ 7.400, mas de forma mecânica", "timestamp_end": "01:13:11", "timestamp_start": "01:13:11"}, {"name": "Preço Protagonista", "score": 2, "stage": 14, "status": "critical", "weight_pct": 5, "observations": "Não aplicou silêncio, não deixou lead falar primeiro, partiu direto para negociação", "timestamp_end": "01:14:39", "timestamp_start": "01:13:11"}, {"name": "Negociação", "score": 2, "stage": 15, "status": "critical", "weight_pct": 7, "observations": "Negociação fraca: aceitou objeções sem firmeza, ofereceu facilidades sem contrapartidas, perdeu controle", "timestamp_end": "01:22:39", "timestamp_start": "01:14:39"}, {"name": "Down Sell", "score": 3, "stage": 16, "status": "critical", "weight_pct": 4, "observations": "Tentou down sell com entrada reduzida, mas sem estruturação adequada da proposta alternativa", "timestamp_end": "01:22:39", "timestamp_start": "01:16:39"}], "negotiation": {"result": "Não fechou - lead ficou de verificar condições financeiras para entrada de R$ 5.000", "cac_explained": false, "downsell_used": true, "silence_applied": false, "who_spoke_first": "closer", "anchor_value_used": "R$ 268.000 (valor de entrega)", "discount_given_pct": null, "negotiation_firmness": 2, "price_table_presented": "R$ 51.000 à vista ou 8x R$ 7.400", "table_price_presented": true, "downsell_narrative_quality": 3, "protagonist_transition_quality": 2}, "overall_label": "Desempenho REGULAR com falhas críticas em estrutura comercial", "overall_score": 4.2, "classification": "REGULAR", "protocol_version": "v1.0", "training_actions": [{"type": "Treinamento Comercial", "focus": "SPIN Selling", "description": "Curso intensivo de questionamento estratégico SPIN", "responsible": "Gerente Comercial", "deadline_days": 15}, {"type": "Role Play", "focus": "Contorno de Objeções", "description": "Simulações de contorno de objeções financeiras e de desconfiança", "responsible": "Supervisor de Vendas", "deadline_days": 7}, {"type": "Mentoria", "focus": "Controle de Negociação", "description": "Acompanhamento em calls reais para desenvolver firmeza comercial", "responsible": "Closer Sênior", "deadline_days": 30}], "executive_summary": "A closer Evelyn demonstrou boa capacidade de apresentação e rapport, mas falhou criticamente na aplicação do protocolo comercial estruturado. Não executou SPIN selling, não fez ancoragem de valor adequada, perdeu controle da negociação ao aceitar passivamente as objeções financeiras do lead sem aplicar técnicas de contorno. A apresentação foi extensa mas sem foco comercial estratégico.", "objections_detected": [{"id": 1, "type": "Financeira", "notes": "Closer aceitou passivamente sem investigar outras possibilidades", "handled": false, "verbatim": "O meu problema é o financeiro", "timestamp": "00:58:15", "handling_quality": "Fraca"}, {"id": 2, "type": "Experiência Passada", "notes": "Explicou diferença da metodologia mas sem aprofundar vantagens competitivas", "handled": true, "verbatim": "Já fizemos duas vezes e as duas vezes tivemos o mesmo problema com tráfego pago", "timestamp": "00:18:25", "handling_quality": "Regular"}, {"id": 3, "type": "Desconfiança", "notes": "Não contornou adequadamente, apenas reconheceu sem demonstrar diferenciação", "handled": false, "verbatim": "Tanta gente já prometeu tanta coisa para mim", "timestamp": "00:54:05", "handling_quality": "Fraca"}], "priority_improvements": [{"issue": "Não executou metodologia SPIN adequadamente", "stage": "SPIN Selling", "priority": 1, "recommended_action": "Treinar técnicas de questionamento para explorar situação, problemas, implicações e necessidades"}, {"issue": "Perdeu controle da negociação aceitando objeções passivamente", "stage": "Negociação", "priority": 2, "recommended_action": "Desenvolver firmeza comercial e técnicas de contorno de objeções"}, {"issue": "Ancoragem sem impacto emocional e sem uso de silêncio", "stage": "Ancoragem", "priority": 3, "recommended_action": "Treinar técnicas de ancoragem de valor e uso estratégico do silêncio"}]}'::jsonb, true, false, 'closer', 2.0, false, 2.0, true, 3.0, '[{"issue": "Não executou metodologia SPIN adequadamente", "stage": "SPIN Selling", "priority": 1, "recommended_action": "Treinar técnicas de questionamento para explorar situação, problemas, implicações e necessidades"}, {"issue": "Perdeu controle da negociação aceitando objeções passivamente", "stage": "Negociação", "priority": 2, "recommended_action": "Desenvolver firmeza comercial e técnicas de contorno de objeções"}, {"issue": "Ancoragem sem impacto emocional e sem uso de silêncio", "stage": "Ancoragem", "priority": 3, "recommended_action": "Treinar técnicas de ancoragem de valor e uso estratégico do silêncio"}]'::jsonb, '[{"type": "Treinamento Comercial", "focus": "SPIN Selling", "description": "Curso intensivo de questionamento estratégico SPIN", "responsible": "Gerente Comercial", "deadline_days": 15}, {"type": "Role Play", "focus": "Contorno de Objeções", "description": "Simulações de contorno de objeções financeiras e de desconfiança", "responsible": "Supervisor de Vendas", "deadline_days": 7}, {"type": "Mentoria", "focus": "Controle de Negociação", "description": "Acompanhamento em calls reais para desenvolver firmeza comercial", "responsible": "Closer Sênior", "deadline_days": 30}]'::jsonb, '[{"id": 1, "type": "Financeira", "notes": "Closer aceitou passivamente sem investigar outras possibilidades", "handled": false, "verbatim": "O meu problema é o financeiro", "timestamp": "00:58:15", "handling_quality": "Fraca"}, {"id": 2, "type": "Experiência Passada", "notes": "Explicou diferença da metodologia mas sem aprofundar vantagens competitivas", "handled": true, "verbatim": "Já fizemos duas vezes e as duas vezes tivemos o mesmo problema com tráfego pago", "timestamp": "00:18:25", "handling_quality": "Regular"}, {"id": 3, "type": "Desconfiança", "notes": "Não contornou adequadamente, apenas reconheceu sem demonstrar diferenciação", "handled": false, "verbatim": "Tanta gente já prometeu tanta coisa para mim", "timestamp": "00:54:05", "handling_quality": "Fraca"}]'::jsonb, 'claude-sonnet-4-20250514', 31515, 3027, 0.14, '2026-03-28T19:31:31.05235+00:00', '2026-03-28T19:31:31.05235+00:00');
INSERT INTO supervisor_analyses (id, audit_id, organization_id, protocol_version, prompt_version, overall_score, overall_label, classification, executive_summary, raw_json, table_price_presented, silence_applied, who_spoke_first, protagonist_transition_quality, cac_explained, negotiation_firmness, downsell_used, downsell_narrative_quality, priority_improvements, training_actions, objections_detected, modelo_analise, tokens_input, tokens_output, custo_estimado, created_at, updated_at) VALUES ('390a8b49-bc1f-4ab4-b385-e9e132317e8b', 'bef46d54-8c64-4403-9f59-d0eda47e0065', '4ecd8f2d-d0c5-419c-a5bc-b2e94dca0465', 'v1.0', '1.0', 5.8, 'Protocolo parcialmente seguido com foco em apresentação de produto, mas falhas críticas em SPIN, ancoragem e negociação', 'REGULAR', 'A call durou 2h44min com venda fechada de R$ 44.000. Evelyn demonstrou conhecimento do produto mas falhou em seguir o protocolo FACE 100K sistematicamente. Faltaram pactos claros, SPIN selling estruturado, ancoragem adequada e negociação firme. A closer cedeu facilmente nos descontos sem usar silêncio. Pontos positivos: rapport construído, apresentação de produto detalhada e fechamento final.', '{"stages": [{"name": "Quebra-gelo", "score": 7, "stage": 1, "status": "ok", "weight_pct": 3, "observations": "Quebra-gelo natural sobre lift da cliente, criou conexão inicial adequada", "timestamp_end": "00:01:25", "timestamp_start": "00:00:00"}, {"name": "Rapport", "score": 8, "stage": 2, "status": "excellent", "weight_pct": 5, "observations": "Excelente rapport construído sobre origem da cliente (Pará), posicionamento no Instagram e conexão pessoal", "timestamp_end": "00:07:07", "timestamp_start": "00:01:25"}, {"name": "Pacto Inicial", "score": 6, "stage": 3, "status": "ok", "weight_pct": 5, "observations": "Pacto mencionado mas não estruturado adequadamente. Faltou clareza sobre sim/não definitivo", "timestamp_end": "00:09:25", "timestamp_start": "00:08:03"}, {"name": "SPIN Situação", "score": 7, "stage": 4, "status": "ok", "weight_pct": 5, "observations": "Coletou informações sobre estrutura da clínica, funcionários e cenário atual", "timestamp_end": "00:15:39", "timestamp_start": "00:10:47"}, {"name": "SPIN Problema", "score": 5, "stage": 5, "status": "warning", "weight_pct": 5, "observations": "Identificou problemas mas não aprofundou adequadamente as dores. Faltou foco em problemas específicos", "timestamp_end": "00:20:44", "timestamp_start": "00:15:39"}, {"name": "SPIN Implicação", "score": 4, "stage": 6, "status": "warning", "weight_pct": 8, "observations": "Implicações mencionadas superficialmente. Não explorou custos emocionais e financeiros dos problemas", "timestamp_end": "00:26:25", "timestamp_start": "00:20:44"}, {"name": "SPIN Necessidade", "score": 5, "stage": 7, "status": "warning", "weight_pct": 7, "observations": "Necessidades identificadas mas não validadas adequadamente pela cliente", "timestamp_end": "00:29:24", "timestamp_start": "00:26:25"}, {"name": "Pacto de Transição", "score": 7, "stage": 8, "status": "ok", "weight_pct": 5, "observations": "Transição para apresentação feita adequadamente com pedido de sim/não", "timestamp_end": "00:30:42", "timestamp_start": "00:29:24"}, {"name": "Apresentação Método", "score": 8, "stage": 9, "status": "excellent", "weight_pct": 10, "observations": "Excelente apresentação da metodologia System Digital, detalhada e estruturada", "timestamp_end": "00:48:47", "timestamp_start": "00:30:42"}, {"name": "Apresentação Produto", "score": 8, "stage": 10, "status": "excellent", "weight_pct": 10, "observations": "Produto apresentado com detalhes dos 8 pilares, cases de sucesso e entregáveis", "timestamp_end": "01:41:14", "timestamp_start": "00:48:47"}, {"name": "Isolamento de Objeções", "score": 6, "stage": 11, "status": "ok", "weight_pct": 8, "observations": "Tentativa de isolamento de objeções mas não seguiu protocolo estruturado", "timestamp_end": "01:42:46", "timestamp_start": "01:41:14"}, {"name": "Ancoragem", "score": 4, "stage": 12, "status": "warning", "weight_pct": 8, "observations": "Ancoragem fraca. Valor de R$ 268.000 mencionado mas não trabalhado adequadamente", "timestamp_end": "01:46:30", "timestamp_start": "01:42:46"}, {"name": "Preço de Tabela", "score": 6, "stage": 13, "status": "ok", "weight_pct": 5, "observations": "Preço tabela de R$ 51.000 apresentado com explicação de condições", "timestamp_end": "01:48:00", "timestamp_start": "01:46:30"}, {"name": "Preço Protagonista", "score": 5, "stage": 14, "status": "warning", "weight_pct": 5, "observations": "Desconto oferecido mas sem usar silêncio nem quem falou primeiro", "timestamp_end": "01:51:15", "timestamp_start": "01:48:00"}, {"name": "Negociação", "score": 4, "stage": 15, "status": "warning", "weight_pct": 7, "observations": "Negociação sem firmeza, cedeu rapidamente aos pedidos da cliente sem resistência", "timestamp_end": "02:26:19", "timestamp_start": "01:51:15"}, {"name": "Down Sell", "score": 0, "stage": 16, "status": "skipped", "weight_pct": 4, "observations": "Não foi necessário pois houve fechamento", "timestamp_end": "00:00:00", "timestamp_start": "00:00:00"}], "negotiation": {"result": "Venda fechada por R$ 44.000 (R$ 5.000 entrada + 8x R$ 4.875)", "cac_explained": true, "downsell_used": false, "silence_applied": false, "who_spoke_first": "lead", "anchor_value_used": "R$ 268.000", "discount_given_pct": 14, "negotiation_firmness": 3, "price_table_presented": "R$ 51.000 em 6x de R$ 8.714", "table_price_presented": true, "downsell_narrative_quality": null, "protagonist_transition_quality": 5}, "overall_label": "Protocolo parcialmente seguido com foco em apresentação de produto, mas falhas críticas em SPIN, ancoragem e negociação", "overall_score": 5.8, "classification": "REGULAR", "protocol_version": "v1.0", "training_actions": [{"type": "role_play", "focus": "SPIN Selling completo", "description": "Treinar descoberta estruturada de problemas, implicações e necessidades", "responsible": "Gerente Comercial", "deadline_days": 7}, {"type": "workshop", "focus": "Técnicas de negociação", "description": "Treinar uso de silêncio, firmeza e contorno de objeções de preço", "responsible": "Diretor Comercial", "deadline_days": 14}, {"type": "shadowing", "focus": "Ancoragem de valor", "description": "Acompanhar calls de closers sênior para observar ancoragem eficaz", "responsible": "Evelyn + Closer Sênior", "deadline_days": 10}], "executive_summary": "A call durou 2h44min com venda fechada de R$ 44.000. Evelyn demonstrou conhecimento do produto mas falhou em seguir o protocolo FACE 100K sistematicamente. Faltaram pactos claros, SPIN selling estruturado, ancoragem adequada e negociação firme. A closer cedeu facilmente nos descontos sem usar silêncio. Pontos positivos: rapport construído, apresentação de produto detalhada e fechamento final.", "objections_detected": [{"id": 1, "type": "preço", "notes": "Closer cedeu facilmente ao parcelamento", "handled": true, "verbatim": "eu achei 8000 mês ainda pesado para mim, assim, achei pesado", "timestamp": "01:48:00", "handling_quality": "regular"}, {"id": 2, "type": "valor_referência", "notes": "Não questionou adequadamente a referência da cliente", "handled": true, "verbatim": "eu tinha uma média de 3,5 a 4 no máximo", "timestamp": "01:49:05", "handling_quality": "regular"}], "priority_improvements": [{"issue": "Não explorou adequadamente os custos dos problemas atuais", "stage": "SPIN Implicação", "priority": 1, "recommended_action": "Aprofundar implicações financeiras e emocionais dos problemas identificados"}, {"issue": "Cedeu rapidamente sem usar técnicas de negociação", "stage": "Negociação", "priority": 2, "recommended_action": "Aplicar silêncio, questionar objeções e manter firmeza nas condições"}, {"issue": "Ancoragem de valor não foi trabalhada adequadamente", "stage": "Ancoragem", "priority": 3, "recommended_action": "Explorar melhor o valor percebido antes de apresentar preço"}]}'::jsonb, true, false, 'lead', 5.0, true, 3.0, false, NULL, '[{"issue": "Não explorou adequadamente os custos dos problemas atuais", "stage": "SPIN Implicação", "priority": 1, "recommended_action": "Aprofundar implicações financeiras e emocionais dos problemas identificados"}, {"issue": "Cedeu rapidamente sem usar técnicas de negociação", "stage": "Negociação", "priority": 2, "recommended_action": "Aplicar silêncio, questionar objeções e manter firmeza nas condições"}, {"issue": "Ancoragem de valor não foi trabalhada adequadamente", "stage": "Ancoragem", "priority": 3, "recommended_action": "Explorar melhor o valor percebido antes de apresentar preço"}]'::jsonb, '[{"type": "role_play", "focus": "SPIN Selling completo", "description": "Treinar descoberta estruturada de problemas, implicações e necessidades", "responsible": "Gerente Comercial", "deadline_days": 7}, {"type": "workshop", "focus": "Técnicas de negociação", "description": "Treinar uso de silêncio, firmeza e contorno de objeções de preço", "responsible": "Diretor Comercial", "deadline_days": 14}, {"type": "shadowing", "focus": "Ancoragem de valor", "description": "Acompanhar calls de closers sênior para observar ancoragem eficaz", "responsible": "Evelyn + Closer Sênior", "deadline_days": 10}]'::jsonb, '[{"id": 1, "type": "preço", "notes": "Closer cedeu facilmente ao parcelamento", "handled": true, "verbatim": "eu achei 8000 mês ainda pesado para mim, assim, achei pesado", "timestamp": "01:48:00", "handling_quality": "regular"}, {"id": 2, "type": "valor_referência", "notes": "Não questionou adequadamente a referência da cliente", "handled": true, "verbatim": "eu tinha uma média de 3,5 a 4 no máximo", "timestamp": "01:49:05", "handling_quality": "regular"}]'::jsonb, 'claude-sonnet-4-20250514', 54614, 2537, 0.2019, '2026-03-28T19:32:26.577788+00:00', '2026-03-28T19:32:26.577788+00:00');
INSERT INTO supervisor_analyses (id, audit_id, organization_id, protocol_version, prompt_version, overall_score, overall_label, classification, executive_summary, raw_json, table_price_presented, silence_applied, who_spoke_first, protagonist_transition_quality, cac_explained, negotiation_firmness, downsell_used, downsell_narrative_quality, priority_improvements, training_actions, objections_detected, modelo_analise, tokens_input, tokens_output, custo_estimado, created_at, updated_at) VALUES ('35a99fab-46c3-47ba-97fb-8d6aa8289c46', 'c110e38a-7b0b-4b90-910e-0222be95455f', '4ecd8f2d-d0c5-419c-a5bc-b2e94dca0465', 'v1.0', '1.0', 5.2, 'Performance Regular com Oportunidades de Melhoria', 'REGULAR', 'Call com performance regular. Evelyn demonstrou boa construção de rapport e aplicação de SPIN, mas perdeu controle na negociação. Apresentou método sem estrutura clara de ancoragem, não trabalhou objeções adequadamente e cedeu muito rapidamente na negociação. Fechamento foi conduzido pelo sócio Renan após perda de liderança comercial.', '{"stages": [{"name": "Quebra-gelo", "score": 8, "stage": 1, "status": "excellent", "weight_pct": 3, "observations": "Excelente quebra-gelo sobre localização (Belém/Curitiba), clima, família e filhos. Criou conexão natural.", "timestamp_end": "00:04:30", "timestamp_start": "00:00:00"}, {"name": "Rapport", "score": 9, "stage": 2, "status": "excellent", "weight_pct": 5, "observations": "Rapport excepcional. Evelyn conectou sobre filhos da mesma idade, futebol, chimarrão. Compartilhou história pessoal criando identificação.", "timestamp_end": "00:10:23", "timestamp_start": "00:04:30"}, {"name": "Pacto Inicial", "score": 7, "stage": 3, "status": "ok", "weight_pct": 5, "observations": "Pacto bem estruturado com três intenções claras: contribuir, entender cenário, apresentar se fizer sentido. Acordou via de mão dupla.", "timestamp_end": "00:10:23", "timestamp_start": "00:09:02"}, {"name": "SPIN Situação", "score": 8, "stage": 4, "status": "excellent", "weight_pct": 5, "observations": "Mapeou bem a situação atual: 5 hospitais, consultório próprio, 2 funcionárias, transição para estética facial.", "timestamp_end": "00:15:21", "timestamp_start": "00:10:23"}, {"name": "SPIN Problema", "score": 8, "stage": 5, "status": "excellent", "weight_pct": 5, "observations": "Identificou problemas claros: trabalha domingo a domingo, longas viagens, dependência de planos de saúde, pouco tempo com família.", "timestamp_end": "00:17:32", "timestamp_start": "00:15:21"}, {"name": "SPIN Implicação", "score": 6, "stage": 6, "status": "ok", "weight_pct": 8, "observations": "Explorou algumas implicações sobre desgaste e necessidade de fluxo particular, mas poderia ter sido mais incisiva nas consequências.", "timestamp_end": "00:18:59", "timestamp_start": "00:17:32"}, {"name": "SPIN Necessidade", "score": 7, "stage": 7, "status": "ok", "weight_pct": 7, "observations": "Lead expressou claramente necessidade urgência 10/10 para aumentar fluxo e mudar cenário ''para ontem''.", "timestamp_end": "00:19:08", "timestamp_start": "00:18:59"}, {"name": "Pacto de Transição", "score": 6, "stage": 8, "status": "ok", "weight_pct": 5, "observations": "Fez pacto para sim/não ao final da apresentação. Adequado mas poderia ter sido mais específico sobre critérios de decisão.", "timestamp_end": "00:20:08", "timestamp_start": "00:18:59"}, {"name": "Apresentação Método", "score": 5, "stage": 9, "status": "warning", "weight_pct": 10, "observations": "Apresentação longa e técnica demais. Face 100K bem apresentado mas faltou simplicidade e foco nos benefícios para o lead.", "timestamp_end": "00:49:27", "timestamp_start": "00:20:08"}, {"name": "Apresentação Produto", "score": 6, "stage": 10, "status": "ok", "weight_pct": 10, "observations": "Apresentou acompanhamento de 6 meses, tutorias, CRM. Boa estrutura mas poderia ter conectado melhor com necessidades específicas do lead.", "timestamp_end": "00:58:29", "timestamp_start": "00:52:42"}, {"name": "Isolamento de Objeções", "score": 3, "stage": 11, "status": "critical", "weight_pct": 8, "observations": "Não isolou objeções adequadamente. Lead mencionou insegurança sobre ROI e questões financeiras, mas não foram tratadas antes do preço.", "timestamp_end": "01:11:54", "timestamp_start": "01:10:53"}, {"name": "Ancoragem", "score": 2, "stage": 12, "status": "critical", "weight_pct": 8, "observations": "Ancoragem confusa com R$67.000, mas imediatamente ofereceu 75% de desconto. Perdeu credibilidade na estratégia de preços.", "timestamp_end": "01:04:04", "timestamp_start": "01:02:58"}, {"name": "Preço de Tabela", "score": 4, "stage": 13, "status": "warning", "weight_pct": 5, "observations": "Apresentou R$51.000 como preço ''do não'' mas lead já havia demonstrado choque com valores anteriores.", "timestamp_end": "01:11:54", "timestamp_start": "01:10:53"}, {"name": "Preço Protagonista", "score": 3, "stage": 14, "status": "critical", "weight_pct": 5, "observations": "R$42.000 apresentado como preço protagonista, mas transição foi abrupta sem trabalhar valor adequadamente.", "timestamp_end": "01:12:19", "timestamp_start": "01:10:53"}, {"name": "Negociação", "score": 2, "stage": 15, "status": "critical", "weight_pct": 7, "observations": "Perdeu controle total da negociação. Chamou o sócio por insegurança e não aplicou técnicas de negociação adequadas.", "timestamp_end": "01:24:00", "timestamp_start": "01:12:19"}, {"name": "Down Sell", "score": 0, "stage": 16, "status": "skipped", "weight_pct": 4, "observations": "Não aplicou down sell. Manteve apenas uma oferta durante toda negociação.", "timestamp_end": null, "timestamp_start": null}], "negotiation": {"result": "Fechamento realizado por R$ 42.000 com parceria do sócio Renan", "cac_explained": false, "downsell_used": false, "silence_applied": false, "who_spoke_first": "lead", "anchor_value_used": "R$ 67.000 com 75% de desconto", "discount_given_pct": 17.6, "negotiation_firmness": 2, "price_table_presented": "R$ 51.000 à vista ou 8x R$ 7.400", "table_price_presented": true, "downsell_narrative_quality": null, "protagonist_transition_quality": 3}, "overall_label": "Performance Regular com Oportunidades de Melhoria", "overall_score": 5.2, "classification": "REGULAR", "protocol_version": "v1.0", "training_actions": [{"type": "Treinamento Técnico", "focus": "Ancoragem e Negociação", "description": "Sessões práticas sobre ancoragem de valor e técnicas de negociação sob pressão", "responsible": "Líder de Vendas", "deadline_days": 7}, {"type": "Role Play", "focus": "Isolamento de Objeções", "description": "Simulações de calls com objeções financeiras e de ROI", "responsible": "Trainer Senior", "deadline_days": 14}, {"type": "Mentoria Individual", "focus": "Estrutura de Apresentação", "description": "Revisão da estrutura de apresentação para ser mais objetiva e focada no lead", "responsible": "Manager Comercial", "deadline_days": 21}], "executive_summary": "Call com performance regular. Evelyn demonstrou boa construção de rapport e aplicação de SPIN, mas perdeu controle na negociação. Apresentou método sem estrutura clara de ancoragem, não trabalhou objeções adequadamente e cedeu muito rapidamente na negociação. Fechamento foi conduzido pelo sócio Renan após perda de liderança comercial.", "objections_detected": [{"id": 1, "type": "Insegurança sobre ROI", "notes": "Chamou o sócio ao invés de trabalhar a objeção", "handled": false, "verbatim": "qual é a minha insegurança? Tipo, e se não der certo um exemplo, entendeu?", "timestamp": "01:10:53", "handling_quality": "inadequate"}, {"id": 2, "type": "Financeira - Momento", "notes": "Não explorou capacidade de investimento adequadamente", "handled": false, "verbatim": "eu tô investido em material, cursos e no meu apartamento que eu não consigo me mudar", "timestamp": "01:11:54", "handling_quality": "inadequate"}, {"id": 3, "type": "Preço - Valor", "notes": "Renan trabalhou parcialmente com confiança mútua", "handled": true, "verbatim": "investir, tipo, a gente dá um jeito, mas é investir não tem retorno", "timestamp": "01:17:21", "handling_quality": "adequate"}], "priority_improvements": [{"issue": "Ancoragem confusa e imediata concessão de desconto", "stage": "Ancoragem", "priority": 1, "recommended_action": "Treinar ancoragem sólida com justificativa de valor antes de apresentar descontos"}, {"issue": "Não isolou objeções antes da negociação", "stage": "Isolamento de Objeções", "priority": 2, "recommended_action": "Implementar técnica de isolamento sistemático antes de apresentar preços"}, {"issue": "Perdeu liderança comercial e precisou de apoio externo", "stage": "Negociação", "priority": 3, "recommended_action": "Fortalecer técnicas de negociação e controle emocional em situações de pressão"}]}'::jsonb, true, false, 'lead', 3.0, false, 2.0, false, NULL, '[{"issue": "Ancoragem confusa e imediata concessão de desconto", "stage": "Ancoragem", "priority": 1, "recommended_action": "Treinar ancoragem sólida com justificativa de valor antes de apresentar descontos"}, {"issue": "Não isolou objeções antes da negociação", "stage": "Isolamento de Objeções", "priority": 2, "recommended_action": "Implementar técnica de isolamento sistemático antes de apresentar preços"}, {"issue": "Perdeu liderança comercial e precisou de apoio externo", "stage": "Negociação", "priority": 3, "recommended_action": "Fortalecer técnicas de negociação e controle emocional em situações de pressão"}]'::jsonb, '[{"type": "Treinamento Técnico", "focus": "Ancoragem e Negociação", "description": "Sessões práticas sobre ancoragem de valor e técnicas de negociação sob pressão", "responsible": "Líder de Vendas", "deadline_days": 7}, {"type": "Role Play", "focus": "Isolamento de Objeções", "description": "Simulações de calls com objeções financeiras e de ROI", "responsible": "Trainer Senior", "deadline_days": 14}, {"type": "Mentoria Individual", "focus": "Estrutura de Apresentação", "description": "Revisão da estrutura de apresentação para ser mais objetiva e focada no lead", "responsible": "Manager Comercial", "deadline_days": 21}]'::jsonb, '[{"id": 1, "type": "Insegurança sobre ROI", "notes": "Chamou o sócio ao invés de trabalhar a objeção", "handled": false, "verbatim": "qual é a minha insegurança? Tipo, e se não der certo um exemplo, entendeu?", "timestamp": "01:10:53", "handling_quality": "inadequate"}, {"id": 2, "type": "Financeira - Momento", "notes": "Não explorou capacidade de investimento adequadamente", "handled": false, "verbatim": "eu tô investido em material, cursos e no meu apartamento que eu não consigo me mudar", "timestamp": "01:11:54", "handling_quality": "inadequate"}, {"id": 3, "type": "Preço - Valor", "notes": "Renan trabalhou parcialmente com confiança mútua", "handled": true, "verbatim": "investir, tipo, a gente dá um jeito, mas é investir não tem retorno", "timestamp": "01:17:21", "handling_quality": "adequate"}]'::jsonb, 'claude-sonnet-4-20250514', 36871, 3149, 0.1578, '2026-03-29T23:24:26.926051+00:00', '2026-03-29T23:24:26.926051+00:00');
INSERT INTO supervisor_analyses (id, audit_id, organization_id, protocol_version, prompt_version, overall_score, overall_label, classification, executive_summary, raw_json, table_price_presented, silence_applied, who_spoke_first, protagonist_transition_quality, cac_explained, negotiation_firmness, downsell_used, downsell_narrative_quality, priority_improvements, training_actions, objections_detected, modelo_analise, tokens_input, tokens_output, custo_estimado, created_at, updated_at) VALUES ('64fa9e59-2ccd-486e-bcbe-958d8596e08d', '5152361d-69e8-4188-bb97-a855c8227ac3', '4ecd8f2d-d0c5-419c-a5bc-b2e94dca0465', 'v1.0', '1.0', 7.8, 'Boa execução com gaps estruturais importantes', 'BOA', 'Evelyn demonstrou boa habilidade comercial ao conduzir uma venda complexa de R$47.160 com cirurgião Buco Maxilo. Executou rapport sólido, SPIN selling bem estruturado, isolamento de objeções eficaz e fechamento com apoio do sócio. Principais deficiências: não seguiu protocolo exato de 16 etapas (pulou pactos formais), ancoragem de valor inadequada (mostrou valor sem âncora), negociação precipitada sem aplicar silêncio. Pontos fortes: diagnóstico de necessidades profundo, apresentação consultiva, manejo de objeções e transição para fechamento.', '{"stages": [{"name": "Quebra-gelo", "score": 9, "stage": 1, "status": "excellent", "weight_pct": 3, "observations": "Excelente rapport geográfico, conversas sobre filhos e clima criaram conexão genuína", "timestamp_end": "00:04:30", "timestamp_start": "00:00:00"}, {"name": "Rapport", "score": 9, "stage": 2, "status": "excellent", "weight_pct": 5, "observations": "Profunda conexão pessoal, apresentação detalhada da closer, histórico profissional bem posicionado", "timestamp_end": "00:09:02", "timestamp_start": "00:05:49"}, {"name": "Pacto Inicial", "score": 3, "stage": 3, "status": "critical", "weight_pct": 5, "observations": "Pacto informal e vago - ''três intenções claras'' sem comprometimento específico do lead", "timestamp_end": "00:10:23", "timestamp_start": "00:09:02"}, {"name": "SPIN Situação", "score": 8, "stage": 4, "status": "excellent", "weight_pct": 5, "observations": "Exploração detalhada da situação atual: 5 hospitais, consultório próprio, transição para estética", "timestamp_end": "00:16:29", "timestamp_start": "00:10:23"}, {"name": "SPIN Problema", "score": 8, "stage": 5, "status": "excellent", "weight_pct": 5, "observations": "Identificou problemas claros: falta de tempo, dependência de planos, desgaste com deslocamentos", "timestamp_end": "00:17:32", "timestamp_start": "00:16:29"}, {"name": "SPIN Implicação", "score": 9, "stage": 6, "status": "excellent", "weight_pct": 8, "observations": "Explorou profundamente implicações: falta de qualidade de vida, tempo com filhos, estagnação profissional", "timestamp_end": "00:18:59", "timestamp_start": "00:17:32"}, {"name": "SPIN Necessidade", "score": 8, "stage": 7, "status": "excellent", "weight_pct": 7, "observations": "Lead expressou claramente necessidade de mudança urgente (nota 10), confirmou disposição para abraçar solução", "timestamp_end": "00:20:08", "timestamp_start": "00:18:59"}, {"name": "Pacto de Transição", "score": 5, "stage": 8, "status": "warning", "weight_pct": 5, "observations": "Pacto básico para ''sim ou não'' ao final, mas sem critérios específicos de avaliação", "timestamp_end": "00:20:08", "timestamp_start": "00:18:59"}, {"name": "Apresentação Método", "score": 8, "stage": 9, "status": "excellent", "weight_pct": 10, "observations": "Apresentação estruturada do Face 100K, posicionamento como especialistas, diferenciação de agências", "timestamp_end": "00:30:01", "timestamp_start": "00:20:08"}, {"name": "Apresentação Produto", "score": 8, "stage": 10, "status": "excellent", "weight_pct": 10, "observations": "Detalhou bem metodologia, mandala de serviços, funis comerciais, treinamento de equipe", "timestamp_end": "00:52:42", "timestamp_start": "00:30:01"}, {"name": "Isolamento de Objeções", "score": 8, "stage": 11, "status": "excellent", "weight_pct": 8, "observations": "Isolou bem objeções: ''faz sentido'', ''acredita que ajudaria'', confirmações sucessivas", "timestamp_end": "01:02:58", "timestamp_start": "00:49:27"}, {"name": "Ancoragem", "score": 4, "stage": 12, "status": "critical", "weight_pct": 8, "observations": "Mostrou valor R$67.000 sem ancoragem adequada, causou susto desnecessário no lead", "timestamp_end": "01:04:04", "timestamp_start": "01:02:58"}, {"name": "Preço de Tabela", "score": 6, "stage": 13, "status": "ok", "weight_pct": 5, "observations": "Apresentou R$51.000 como ''valor do não'', estrutura adequada mas transição abrupta", "timestamp_end": "01:11:54", "timestamp_start": "01:10:53"}, {"name": "Preço Protagonista", "score": 7, "stage": 14, "status": "ok", "weight_pct": 5, "observations": "R$42.000 como ''valor do sim'', boa diferenciação mas faltou justificativa do desconto", "timestamp_end": "01:13:19", "timestamp_start": "01:10:53"}, {"name": "Negociação", "score": 8, "stage": 15, "status": "excellent", "weight_pct": 7, "observations": "Excelente manejo de objeções financeiras, entrada do sócio, parcelamento estratégico", "timestamp_end": "01:31:19", "timestamp_start": "01:13:19"}, {"name": "Down Sell", "score": 0, "stage": 16, "status": "skipped", "weight_pct": 4, "observations": "Não aplicável - lead fechou no produto principal", "timestamp_end": "N/A", "timestamp_start": "N/A"}], "negotiation": {"result": "Fechamento R$47.160 (12x R$3.931) - cirurgião Buco Maxilo iniciando estética facial", "cac_explained": false, "downsell_used": false, "silence_applied": false, "who_spoke_first": "lead", "anchor_value_used": "R$67.000", "discount_given_pct": 17.6, "negotiation_firmness": 8, "price_table_presented": "R$51.000 à vista ou 8x R$740", "table_price_presented": true, "downsell_narrative_quality": null, "protagonist_transition_quality": 7}, "overall_label": "Boa execução com gaps estruturais importantes", "overall_score": 7.8, "classification": "BOA", "protocol_version": "v1.0", "training_actions": [{"type": "individual", "focus": "Estruturação de Pactos", "description": "Treinar formulação de pactos claros com critérios específicos de tomada de decisão", "responsible": "Gestor Comercial", "deadline_days": 7}, {"type": "role_play", "focus": "Ancoragem de Valor", "description": "Praticar ancoragens contextualizadas para diferentes perfis de cliente", "responsible": "Trainer Senior", "deadline_days": 14}, {"type": "workshop", "focus": "Técnicas de Silêncio", "description": "Workshop sobre aplicação estratégica do silêncio em negociações B2B", "responsible": "Head de Vendas", "deadline_days": 21}], "executive_summary": "Evelyn demonstrou boa habilidade comercial ao conduzir uma venda complexa de R$47.160 com cirurgião Buco Maxilo. Executou rapport sólido, SPIN selling bem estruturado, isolamento de objeções eficaz e fechamento com apoio do sócio. Principais deficiências: não seguiu protocolo exato de 16 etapas (pulou pactos formais), ancoragem de valor inadequada (mostrou valor sem âncora), negociação precipitada sem aplicar silêncio. Pontos fortes: diagnóstico de necessidades profundo, apresentação consultiva, manejo de objeções e transição para fechamento.", "objections_detected": [{"id": 1, "type": "financeira", "notes": "Evelyn trouxe sócio para dar garantias e abordar receio de ROI", "handled": true, "verbatim": "e se não der certo um exemplo, entendeu? porque quando eu te falei, eu tô investido em material, cursos", "timestamp": "01:10:53", "handling_quality": "excelente"}, {"id": 2, "type": "autoridade", "notes": "Closer manteve pressão consultiva, lead decidiu na call", "handled": true, "verbatim": "eu tenho que pensar aqui", "timestamp": "01:11:54", "handling_quality": "boa"}, {"id": 3, "type": "preço", "notes": "Firmeza no valor, ofereceu parcelamento e desconto via plataforma", "handled": true, "verbatim": "qual é o menor preço mesmo. Menor, menor preço", "timestamp": "01:12:19", "handling_quality": "excelente"}], "priority_improvements": [{"issue": "Pacto informal sem comprometimento claro", "stage": "Pacto Inicial", "priority": 1, "recommended_action": "Implementar pactos estruturados com critérios específicos de avaliação"}, {"issue": "Âncora causou susto desnecessário", "stage": "Ancoragem", "priority": 2, "recommended_action": "Desenvolver âncoras contextualizadas com valor percebido adequado"}, {"issue": "Não aplicou técnica do silêncio", "stage": "Negociação", "priority": 3, "recommended_action": "Treinar aplicação sistemática do silêncio pós-preço"}]}'::jsonb, true, false, 'lead', 7.0, false, 8.0, false, NULL, '[{"issue": "Pacto informal sem comprometimento claro", "stage": "Pacto Inicial", "priority": 1, "recommended_action": "Implementar pactos estruturados com critérios específicos de avaliação"}, {"issue": "Âncora causou susto desnecessário", "stage": "Ancoragem", "priority": 2, "recommended_action": "Desenvolver âncoras contextualizadas com valor percebido adequado"}, {"issue": "Não aplicou técnica do silêncio", "stage": "Negociação", "priority": 3, "recommended_action": "Treinar aplicação sistemática do silêncio pós-preço"}]'::jsonb, '[{"type": "individual", "focus": "Estruturação de Pactos", "description": "Treinar formulação de pactos claros com critérios específicos de tomada de decisão", "responsible": "Gestor Comercial", "deadline_days": 7}, {"type": "role_play", "focus": "Ancoragem de Valor", "description": "Praticar ancoragens contextualizadas para diferentes perfis de cliente", "responsible": "Trainer Senior", "deadline_days": 14}, {"type": "workshop", "focus": "Técnicas de Silêncio", "description": "Workshop sobre aplicação estratégica do silêncio em negociações B2B", "responsible": "Head de Vendas", "deadline_days": 21}]'::jsonb, '[{"id": 1, "type": "financeira", "notes": "Evelyn trouxe sócio para dar garantias e abordar receio de ROI", "handled": true, "verbatim": "e se não der certo um exemplo, entendeu? porque quando eu te falei, eu tô investido em material, cursos", "timestamp": "01:10:53", "handling_quality": "excelente"}, {"id": 2, "type": "autoridade", "notes": "Closer manteve pressão consultiva, lead decidiu na call", "handled": true, "verbatim": "eu tenho que pensar aqui", "timestamp": "01:11:54", "handling_quality": "boa"}, {"id": 3, "type": "preço", "notes": "Firmeza no valor, ofereceu parcelamento e desconto via plataforma", "handled": true, "verbatim": "qual é o menor preço mesmo. Menor, menor preço", "timestamp": "01:12:19", "handling_quality": "excelente"}]'::jsonb, 'claude-sonnet-4-20250514', 36870, 3041, 0.1562, '2026-03-29T23:32:02.515033+00:00', '2026-03-29T23:32:02.515033+00:00');
INSERT INTO supervisor_analyses (id, audit_id, organization_id, protocol_version, prompt_version, overall_score, overall_label, classification, executive_summary, raw_json, table_price_presented, silence_applied, who_spoke_first, protagonist_transition_quality, cac_explained, negotiation_firmness, downsell_used, downsell_narrative_quality, priority_improvements, training_actions, objections_detected, modelo_analise, tokens_input, tokens_output, custo_estimado, created_at, updated_at) VALUES ('a8a835fc-04b7-406a-a0db-6a1c98ac403f', 'c110e38a-7b0b-4b90-910e-0222be95455f', '4ecd8f2d-d0c5-419c-a5bc-b2e94dca0465', 'v1.0', '1.0', 6.2, 'Performance regular com pontos de melhoria significativos', 'REGULAR', 'A closer Evelyn demonstrou competência em rapport e apresentação do método, mas falhou criticamente em etapas fundamentais do protocolo. Não estabeleceu pactos claros, executou SPIN de forma incompleta, não apresentou ancoragem nem preços específicos, e não conduziu negociação estruturada. O lead demonstrou interesse e necessidade clara, mas a venda não foi finalizada adequadamente.', '{"stages": [{"name": "Quebra-gelo", "score": 8, "stage": 1, "status": "excellent", "weight_pct": 3, "observations": "Excelente quebra-gelo com conversas sobre localização, família e filhos. Criou conexão natural.", "timestamp_end": "00:02:29", "timestamp_start": "00:00:00"}, {"name": "Rapport", "score": 9, "stage": 2, "status": "excellent", "weight_pct": 5, "observations": "Rapport muito bem construído, conversas sobre filhos, rotina, interesses comuns. Conexão genuína estabelecida.", "timestamp_end": "00:05:49", "timestamp_start": "00:02:29"}, {"name": "Pacto Inicial", "score": 4, "stage": 3, "status": "warning", "weight_pct": 5, "observations": "Pacto fraco e incompleto. Mencionou ''três intenções'' mas não estabeleceu acordo claro sobre processo e tempo.", "timestamp_end": "00:10:23", "timestamp_start": "00:09:02"}, {"name": "SPIN Situação", "score": 7, "stage": 4, "status": "ok", "weight_pct": 5, "observations": "Boa investigação da situação atual: hospitais, consultório, funcionários, horários de atendimento.", "timestamp_end": "00:14:05", "timestamp_start": "00:10:23"}, {"name": "SPIN Problema", "score": 6, "stage": 5, "status": "ok", "weight_pct": 5, "observations": "Identificou problemas: trabalho excessivo, pouco tempo com família, dependência de planos. Poderia ter aprofundado mais.", "timestamp_end": "00:17:32", "timestamp_start": "00:14:05"}, {"name": "SPIN Implicação", "score": 5, "stage": 6, "status": "warning", "weight_pct": 8, "observations": "Explorou parcialmente as implicações: desgaste, falta de tempo com filhos, mas não amplificou suficientemente o custo emocional.", "timestamp_end": "00:18:59", "timestamp_start": "00:17:32"}, {"name": "SPIN Necessidade", "score": 8, "stage": 7, "status": "excellent", "weight_pct": 7, "observations": "Lead expressou claramente necessidade urgência 10/10: ''para ontem'', quer fluxo para cirurgias estéticas.", "timestamp_end": "00:19:30", "timestamp_start": "00:18:59"}, {"name": "Pacto de Transição", "score": 3, "stage": 8, "status": "critical", "weight_pct": 5, "observations": "Pacto muito fraco, apenas pediu ''sim ou não'' no final sem estruturar adequadamente a transição.", "timestamp_end": "00:20:08", "timestamp_start": "00:18:59"}, {"name": "Apresentação Método", "score": 8, "stage": 9, "status": "excellent", "weight_pct": 10, "observations": "Excelente apresentação do método Face 100K, explicou diferencial, cases, estrutura da empresa.", "timestamp_end": "00:37:04", "timestamp_start": "00:20:08"}, {"name": "Apresentação Produto", "score": 7, "stage": 10, "status": "ok", "weight_pct": 10, "observations": "Boa apresentação dos pilares, mandala, processos. Detalhou bem a metodologia mas perdeu foco em alguns momentos.", "timestamp_end": "00:49:27", "timestamp_start": "00:37:04"}, {"name": "Isolamento de Objeções", "score": 4, "stage": 11, "status": "warning", "weight_pct": 8, "observations": "Não isolou objeções adequadamente. Lead mencionou ''teoria é linda, prática...'' mas não foi trabalhada.", "timestamp_end": "00:50:33", "timestamp_start": "00:49:27"}, {"name": "Ancoragem", "score": 0, "stage": 12, "status": "skipped", "weight_pct": 8, "observations": "Não executou ancoragem de valor. Não apresentou valor de referência ou contextualizou investimento.", "timestamp_end": "N/A", "timestamp_start": "N/A"}, {"name": "Preço de Tabela", "score": 0, "stage": 13, "status": "skipped", "weight_pct": 5, "observations": "Não apresentou preço de tabela. Call foi interrompida antes da apresentação de valores.", "timestamp_end": "N/A", "timestamp_start": "N/A"}, {"name": "Preço Protagonista", "score": 0, "stage": 14, "status": "skipped", "weight_pct": 5, "observations": "Não chegou a apresentar preço protagonista devido à interrupção da call.", "timestamp_end": "N/A", "timestamp_start": "N/A"}, {"name": "Negociação", "score": 0, "stage": 15, "status": "skipped", "weight_pct": 7, "observations": "Não houve negociação estruturada. Call foi interrompida antes do fechamento.", "timestamp_end": "N/A", "timestamp_start": "N/A"}, {"name": "Down Sell", "score": 0, "stage": 16, "status": "skipped", "weight_pct": 4, "observations": "Não aplicou down sell pois não chegou à fase de fechamento.", "timestamp_end": "N/A", "timestamp_start": "N/A"}], "negotiation": {"result": "Call interrompida antes do fechamento. Lead demonstrou interesse (''Face 500K?'') mas não houve apresentação de preços nem negociação.", "cac_explained": false, "downsell_used": false, "silence_applied": false, "who_spoke_first": "unknown", "anchor_value_used": null, "discount_given_pct": null, "negotiation_firmness": 0, "price_table_presented": null, "table_price_presented": false, "downsell_narrative_quality": null, "protagonist_transition_quality": 0}, "overall_label": "Performance regular com pontos de melhoria significativos", "overall_score": 6.2, "classification": "REGULAR", "protocol_version": "v1.0", "training_actions": [{"type": "treino_pratico", "focus": "Ancoragem e Precificação", "description": "Roleplay intensivo de ancoragem de valor e apresentação de preços com casos similares", "responsible": "Gestor Comercial", "deadline_days": 7}, {"type": "mentoria", "focus": "Estrutura de Pactos", "description": "Sessão de mentoria específica sobre estabelecimento de pactos efetivos", "responsible": "Closer Sênior", "deadline_days": 3}, {"type": "estudo_teorico", "focus": "Tratamento de Objeções", "description": "Estudo de scripts e técnicas para isolamento e tratamento de objeções", "responsible": "Evelyn", "deadline_days": 5}], "executive_summary": "A closer Evelyn demonstrou competência em rapport e apresentação do método, mas falhou criticamente em etapas fundamentais do protocolo. Não estabeleceu pactos claros, executou SPIN de forma incompleta, não apresentou ancoragem nem preços específicos, e não conduziu negociação estruturada. O lead demonstrou interesse e necessidade clara, mas a venda não foi finalizada adequadamente.", "objections_detected": [{"id": 1, "type": "ceticismo", "notes": "Objeção importante sobre teoria vs prática não foi isolada nem tratada adequadamente.", "handled": false, "verbatim": "Na teoria é lindo. Vai na prática. Aí já é perfeito.", "timestamp": "00:49:27", "handling_quality": "critical"}, {"id": 2, "type": "tempo", "notes": "Lead mencionou falta de tempo para processos estruturados. Closer não isolou nem trabalhou esta objeção.", "handled": false, "verbatim": "isso requer tempo, reuniões, é muito difícil para mim. Meu tempo é muito complicado.", "timestamp": "00:16:29", "handling_quality": "warning"}], "priority_improvements": [{"issue": "Não executou ancoragem de valor antes de apresentar preços", "stage": "Ancoragem", "priority": 1, "recommended_action": "Treinar técnicas de ancoragem com valores de referência do mercado e CAC"}, {"issue": "Pactos fracos e incompletos durante a call", "stage": "Pactos", "priority": 2, "recommended_action": "Reforçar treinamento de estabelecimento de pactos claros e específicos"}, {"issue": "Não isolou nem tratou objeções importantes do lead", "stage": "Isolamento de Objeções", "priority": 3, "recommended_action": "Treinar técnicas de isolamento e tratamento de objeções estruturado"}]}'::jsonb, false, false, 'unknown', NULL, false, NULL, false, NULL, '[{"issue": "Não executou ancoragem de valor antes de apresentar preços", "stage": "Ancoragem", "priority": 1, "recommended_action": "Treinar técnicas de ancoragem com valores de referência do mercado e CAC"}, {"issue": "Pactos fracos e incompletos durante a call", "stage": "Pactos", "priority": 2, "recommended_action": "Reforçar treinamento de estabelecimento de pactos claros e específicos"}, {"issue": "Não isolou nem tratou objeções importantes do lead", "stage": "Isolamento de Objeções", "priority": 3, "recommended_action": "Treinar técnicas de isolamento e tratamento de objeções estruturado"}]'::jsonb, '[{"type": "treino_pratico", "focus": "Ancoragem e Precificação", "description": "Roleplay intensivo de ancoragem de valor e apresentação de preços com casos similares", "responsible": "Gestor Comercial", "deadline_days": 7}, {"type": "mentoria", "focus": "Estrutura de Pactos", "description": "Sessão de mentoria específica sobre estabelecimento de pactos efetivos", "responsible": "Closer Sênior", "deadline_days": 3}, {"type": "estudo_teorico", "focus": "Tratamento de Objeções", "description": "Estudo de scripts e técnicas para isolamento e tratamento de objeções", "responsible": "Evelyn", "deadline_days": 5}]'::jsonb, '[{"id": 1, "type": "ceticismo", "notes": "Objeção importante sobre teoria vs prática não foi isolada nem tratada adequadamente.", "handled": false, "verbatim": "Na teoria é lindo. Vai na prática. Aí já é perfeito.", "timestamp": "00:49:27", "handling_quality": "critical"}, {"id": 2, "type": "tempo", "notes": "Lead mencionou falta de tempo para processos estruturados. Closer não isolou nem trabalhou esta objeção.", "handled": false, "verbatim": "isso requer tempo, reuniões, é muito difícil para mim. Meu tempo é muito complicado.", "timestamp": "00:16:29", "handling_quality": "warning"}]'::jsonb, 'claude-sonnet-4-20250514', 18290, 2903, 0.0984, '2026-03-29T23:41:01.733893+00:00', '2026-03-29T23:41:01.733893+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('1fc07ae9-514c-431c-a2a4-76be118e0f8f', '0c030f3c-ee45-4310-be50-0700928ee556', 'stage_2', 'Rapport', 2, 0.0, 10.0, 0.05, 'skipped', '', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('7744dcc4-b8df-47b3-952c-f6a7d39c7da5', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_1', 'Quebra-gelo', 1, 7.0, 10.0, 0.03, 'ok', 'Quebra-gelo natural e espontâneo. Evelyn compartilhou contexto pessoal (chuva em Cascavel), gerou reciprocidade e identificou localização da lead. Houve humor leve e conexão genuína. Ponto fraco: duração um pouco extensa para a função (>2 min) e encerramento abrupto com ''Vamos lá, então, Karina'' sem transição suave para o próximo estágio.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('4974a1de-dbca-443d-a955-7f1c18540ef4', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_2', 'Rapport', 2, 7.0, 10.0, 0.05, 'ok', 'Bom rapport construído através de perguntas sobre a trajetória profissional da Karina: formação, especialização, clínica própria, estrutura de equipe e expansão para o Pará. Evelyn demonstrou interesse genuíno e validou respostas com expressões positivas. Ponto negativo: rapport misturou-se com SPIN situação sem delimitação clara, diluindo a fase de conexão emocional pura. A celebração dos cases da lead (''já tem case já!'') foi eficaz como reforço positivo.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('1be0f0e5-c598-452b-ac2d-d5615b54a5eb', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_3', 'Pacto Inicial', 3, 0.0, 10.0, 0.05, 'skipped', 'Etapa completamente omitida. Evelyn não estabeleceu as regras do jogo para a reunião: não definiu agenda, não obteve comprometimento da lead com honestidade nas respostas, não alinhou expectativas de tempo nem obteve permissão explícita para fazer perguntas. Isso impactou negativamente o controle da call — a lead fez perguntas no meio da apresentação (ex.: ''Quanto custa uma lipo de papada?'', ''Quem vai fazer cada fatia do bolo?'') desviando o fluxo protocolar várias vezes.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('55049799-25c7-46e8-9fd4-5c494f4114b6', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_4', 'SPIN - Situação', 4, 6.0, 10.0, 0.05, 'ok', 'Levantamento situacional razoável: identificou especialidade (harmonização + lipo de papada iniciante), clínica própria, equipe (secretária + enfermeira), presença no Pará por 8-10 dias/mês, faturamento atual de R$20-22k/mês e meta de R$100k. Pontos negativos: SPIN foi misturado com rapport e apresentação prematura do produto (Evelyn começou a apresentar a System antes de concluir o diagnóstico situacional completo). Perguntas situacionais foram superficiais em algumas áreas — não aprofundou ticket médio atual de harmonização, volume de pacientes, tempo médio de atendimento ou sazonalidade.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('193742c3-9195-48d8-b7d5-79e2f4d167b5', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_5', 'SPIN - Problema', 5, 6.0, 10.0, 0.05, 'ok', 'Problema central identificado corretamente: baixa conversão de leads (70 leads, zero vendas de lipo), falta de processo comercial, leads não comparecem, secretária sem treinamento em vendas high ticket. A lead confirmou espontaneamente ''vender, converter'' como seu maior desafio. Ponto negativo: o problema foi identificado de forma reativa (a lead revelou) e não extraído ativamente por Evelyn. A pergunta ''o que que você considera mais desafiador?'' foi boa mas veio tardiamente. Evelyn começou a apresentar soluções prematuramente antes de concluir todo o SPIN.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('de77136e-310d-4f39-995e-798c38349545', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_6', 'SPIN - Implicação', 6, 4.0, 10.0, 0.08, 'warning', 'Implicação foi conduzida de forma superficial e misturada com apresentação de produto. Evelyn fez algumas conexões causa-efeito (''não adianta fazer só marketing, se o comercial não souber o processo, todo trabalho é perdido'', ''queimou dinheiro''), mas não aprofundou as consequências emocionais e financeiras reais do problema para a Karina. Não quantificou a perda: ''70 leads não convertidos × R$9k = R$630k deixados na mesa''. Não explorou o impacto na dependência do marido (tema emocional poderoso que a própria lead citou). A implicação foi didática/racional e não visceral/emocional, perdendo oportunidade de ampliar a dor.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('20a0ede1-c98b-42ed-8dea-94f174edf6f8', '0c030f3c-ee45-4310-be50-0700928ee556', 'stage_3', 'Pacto Inicial', 3, 0.0, 10.0, 0.05, 'skipped', '', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('a3203fbd-b62c-4b62-ac34-af4c96cba84d', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_7', 'SPIN - Necessidade', 7, 5.0, 10.0, 0.07, 'ok', 'Necessidade parcialmente trabalhada. A meta de R$100k foi identificada e conectada ao desejo de liberdade financeira e independência do marido — elemento emocional poderoso revelado pela lead. Evelyn validou (''liberdade financeira e pessoal também'') mas não aprofundou nem fez a lead verbalizar o custo de não resolver o problema. A pergunta ''qual o seu maior objetivo em bater esse faturamento?'' foi excelente e extraiu a motivação real. Contudo, a necessidade de solução não foi suficientemente amarrada antes da transição para apresentação.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('52ad5c11-c02b-49e9-8b01-324806e795ca', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_8', 'Pacto de Transição', 8, 3.0, 10.0, 0.05, 'critical', 'Pacto de transição executado de forma muito fraca. A frase ''Vamos lá, vou me apresentar um pouquinho'' foi usada prematuramente (antes de concluir o SPIN) e sem obter comprometimento da lead. Evelyn abriu o mapa mental dizendo ''vou abrir um mapa mental para entender seus objetivos, a partir dele criamos estratégia específica'' — isso é positivo como intenção, mas não configurou um pacto formal com compromisso de reciprocidade. A lead não confirmou explicitamente que, se a solução fizesse sentido, avançaria. Ausência de ''se eu mostrar X, você estaria disposta a Y?''', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('0213a43d-72e5-4170-9a7a-6e862d834535', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_9', 'Apresentação do Método', 9, 6.0, 10.0, 0.1, 'ok', 'Apresentação do método estruturada e com clareza razoável. Evelyn apresentou: método ''Face sem K'' / R$100k, histórico de 6 anos da System, perfil dos sócios (Renan e Mateus), cases relevantes (Débora 150k→500k, Sandy 70k em uma semana), diferencial de parceria vs agência. Utilizou compartilhamento de tela e mostrou a mandala de pilares. Pontos negativos: apresentação foi longa (~16 minutos), com repetições e desvios de fluxo por perguntas da lead (que não foram controladas pelo pacto inicial ausente). O case da Débora foi apresentado com inconsistências (ora ''4 meses para 500k'', ora ''dentista de Parauapebas perto de mim'' — coincidência usada bem). Faltou storytelling mais emocional conectado diretamente à dor da Karina.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('7c768d7a-9d85-440b-b394-407a6b98a361', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_10', 'Apresentação do Produto', 10, 6.0, 10.0, 0.1, 'ok', 'Apresentação do produto (programa de 6 meses) razoável: explicou reuniões de onboarding, grupo VIP estratégico + operacional, tutorias diárias, CRM de bônus, gestor de tráfego exclusivo, scripts/playbooks com acesso ilimitado, protocolos de caixa rápida. A divisão entre grupo estratégico (Karina) e operacional (secretária) foi bem explicada. Pontos negativos: apresentação muito técnica/racional sem ancoragem emocional adequada nos benefícios. Não personalizou suficientemente a apresentação ao perfil da Karina (8-10 dias no Pará, secretária única, início com lipo de papada). A pergunta ''de 0 a 10 você daria qual nota?'' foi boa técnica de validação — lead respondeu 10.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('b5e5d747-59e7-4772-ab6f-01d1bd6ec70d', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_11', 'Isolamento de Objeções', 11, 1.0, 10.0, 0.08, 'critical', 'Etapa praticamente ausente. Quando a lead sinalizou preocupação com o preço (''Tô com medo do valor'', ''minha mão tá gelada''), Evelyn tentou tranquilizar de forma genérica (''conta preso, fica tranquila'') mas não isolou a objeção adequadamente. Não fez perguntas como: ''Além do investimento, existe alguma outra coisa que te impediria de avançar hoje?'' ou ''Se resolvermos a questão financeira, você estaria pronta para começar?''. A objeção financeira emergiu naturalmente (''comprei muita máquina'', ''preciso começar a ganhar'') mas nunca foi formalmente isolada e trabalhada. Isso enfraqueceu toda a negociação subsequente.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('df0ccb7b-4abe-4c95-9ac5-f0254e4b86ed', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_12', 'Ancoragem', 12, 4.0, 10.0, 0.08, 'warning', 'Ancoragem executada com estrutura correta (analogia do imóvel + valor âncora de R$268k com 75% de desconto) mas com falhas de execução relevantes. Pontos positivos: usou analogia tangível do imóvel, contextualizou diferença entre valor e preço, trouxe o âncora antes do preço real. Pontos negativos: o valor âncora de R$268k não foi construído progressivamente ao longo da call — surgiu de forma abrupta sem base sólida. A pergunta ''se eu te der 75% de desconto, você se tornaria cliente?'' foi respondida com hesitação pela lead (''hoje em potencial não é isso''), sinalizando que o âncora não foi suficientemente convincente. A analogia do imóvel foi genérica demais para uma profissional de saúde de alto nível.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('1780f511-aa8c-4491-bae9-5a357f29ac7a', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_13', 'Preço Tabela', 13, 6.0, 10.0, 0.05, 'ok', 'Preço tabela apresentado de forma adequada: R$51.000 à vista ou 8x R$740 para o pacote completo de 6 meses. A apresentação foi direta e sem rodeios excessivos. Ponto positivo: Evelyn mencionou cases de resultado imediatamente antes do preço, reforçando valor. Ponto negativo: o parcelamento de 8x R$740 é inconsistente matematicamente (8 × 740 = R$5.920, muito abaixo do R$51k à vista), sugerindo erro de comunicação ou confusão entre modalidades — isso pode ter gerado confusão na lead. Não houve pausa estratégica após revelar o preço para deixar o lead processar.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('cc9e1234-70a2-40d0-a33f-805cd43371f8', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_14', 'Preço Protagonista', 14, 4.0, 10.0, 0.05, 'warning', 'A técnica do preço protagonista foi parcialmente aplicada ao oferecer opção de ''programa de ativação'' antes do pacote completo como alternativa de entrada. Evelyn perguntou ''o quanto você estaria disposta a investir'' e abriu espaço para negociação. Pontos negativos: a oferta de down-sell foi apresentada prematuramente e sem estrutura clara de o que seria esse programa menor. Não houve uma oferta protagonista claramente definida e apresentada com orgulho antes de entrar em negociação. A transição do preço tabela para a negociação foi muito rápida, sem sustentar o valor do investimento.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('f2c7b8b0-738f-4609-bd57-c8eb7e92eb68', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_15', 'Negociação', 15, 3.0, 10.0, 0.07, 'critical', 'Negociação conduzida sem autoridade e com múltiplas concessões unilaterais. Evelyn aceitou R$3.500/12x (total R$42k) sem resistência, sem contrapartida e sem consultar limites previamente. Precisou interromper a call para ligar ao Renan ao vivo para aprovação, sinalizando à lead que a closer não tem poder decisório — enfraquecendo a autoridade e criando janela para lead reconsiderar. A lead propôs os termos (''3.500 em 12 vezes'') e Evelyn simplesmente aceitou. Não houve técnica de concessão gradual, não houve pedido de contrapartida (entrada, assinatura, compromisso formal), e o fechamento ficou em aberto com ''vou ligar pro Renan, aguenta aí''.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('809b522d-1e16-47f9-86ff-2e368c393eeb', 'adaafc04-1533-4737-9205-9844a79d88d9', 'stage_16', 'Down Sell', 16, 4.0, 10.0, 0.04, 'warning', 'Down sell mencionado superficialmente (''programa de ativação primeiro, depois upgrade'') mas sem estrutura definida. Evelyn citou a possibilidade de fazer 3 meses em vez de 6 meses, mas não apresentou um produto down sell claro com nome, entregáveis, prazo e preço específico. A oferta alternativa ficou vaga (''faz uma ativação primeiro''). Não foi posicionado como opção legítima e valorosa — pareceu mais uma concessão defensiva do que uma oferta estratégica. A lead não demonstrou interesse no down sell pois sinalizou querer o programa completo mas com condições de pagamento ajustadas.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
