INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('89e201cd-89d8-438e-b496-a82dea57a6ce', '0c030f3c-ee45-4310-be50-0700928ee556', 'stage_16', 'Down Sell', 16, 0.0, 10.0, 0.04, 'skipped', '', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('2e208b78-b9d8-4616-87cc-66720a16d750', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_1', 'Quebra-gelo', 1, 8.0, 10.0, 0.03, 'excellent', 'Evelyn inicia com leveza, pergunta sobre a cidade do lead, menciona experiência pessoal em Barueri/Alphaville, palestra do Pablo Marçal, cria conexão geográfica natural. Conversa fluiu de forma orgânica nos primeiros 2 minutos. Ponto de melhoria: poderia ter sido um pouco mais curta para não gastar tempo em tópicos sem relação com o perfil do lead.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('f0359d96-4405-4834-9e1e-2ce64e3d5fc6', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_2', 'Rapport', 2, 9.0, 10.0, 0.05, 'excellent', 'Rapport muito bem construído ao longo de toda a call. Evelyn conecta experiência laboratorial/clínica com o universo do lead, cria identificação genuína com a jornada de pai dentista, família, três filhos, transição de carreira. Lead compartilhou informações pessoais profundas (relação com o pai, casamento anterior, bebê de 6 meses, rotina da esposa), sinal claro de alta confiança estabelecida. Pontos de conexão humanizados foram consistentes e bem distribuídos na call.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('b903b3bb-791b-4c8b-9342-e50bce1a5017', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_3', 'Pacto Inicial', 3, 7.0, 10.0, 0.05, 'ok', 'Executado em ~04:17 com a frase ''eu queria entender um pouquinho mais de você… antes de eu iniciar aqui para fazer algumas perguntas''. Há uma segunda tentativa mais estruturada em ~22:51 onde Evelyn propõe ir até parte da apresentação e agendar segunda call para negociação. O pacto foi cumprido, porém com linguagem difusa e sem alinhamento claro de tempo e agenda da call. A condição do sim/não ao final foi bem posicionada, mas a divisão em duas calls não foi apresentada como standard desde o início, o que gerou estranheza quando foi invocada para justificar a ausência de preço.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('9b73d7a3-7753-4d2e-b148-8e19d1aa7d09', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_4', 'SPIN – Situação', 4, 8.0, 10.0, 0.05, 'excellent', 'Coleta situacional robusta: clínica solo sem secretária, ticket médio R$25-35k/mês, especialidade principal em resinas, 20% de taxa de conversão, investimento de ~R$1.200/mês em tráfego próprio, lead a R$5, 5-10 leads/dia, experiência prévia de 18 meses com a Smile de Curitiba, esposa dentista com clínica separada, pai dentista com referência de resultado em cirurgias. Dados coletados naturalmente durante o diálogo, sem soar como formulário.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('01ed8912-516e-4fa6-a4d5-02818e653bf0', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_5', 'SPIN – Problema', 5, 7.0, 10.0, 0.05, 'ok', 'Problemas identificados: estagnação de faturamento, leads não qualificados, dependência de processo próprio sem time, ausência de secretária, desgaste operacional, hora clínica depreciando com recorrência, falta de tempo para família (3 filhos). A closer mapeou corretamente os problemas mas não aprofundou perguntas específicas do tipo ''quanto tempo você perde com leads que não convertem?'' ou ''o que acontece quando você tira um dia de folga?''. Problemas vieram mais pelo relato espontâneo do lead do que por perguntas diagnósticas intencionais.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('5d81b637-dac5-4443-9910-19012e59f3df', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_6', 'SPIN – Implicação', 6, 5.0, 10.0, 0.08, 'warning', 'A implicação foi tocada superficialmente: Evelyn menciona que sem processo comercial a secretária leva o processo embora ao sair, que leads caros sem qualificação queimam dinheiro, e que sobrecarga leva à frustração. Mas não houve pergunta de implicação estruturada do tipo ''o que acontece com a sua família se você continuar faturando R$30k/mês pelos próximos 6 meses?'' ou ''se você não resolver o lado comercial agora que vai entrar em cirurgias, qual o risco de iniciar mal esse novo serviço?''. A dor ficou identificada mas não amplificada suficientemente para criar urgência emocional e financeira no lead.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('2db48d64-b18c-47c7-883a-4ce6efc5fff7', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_7', 'SPIN – Necessidade', 7, 6.0, 10.0, 0.07, 'ok', 'O lead verbalizou sua necessidade de forma espontânea: ticket maior, mais tempo com a família, escalabilidade com cirurgias, ter alguém para cuidar do comercial. Evelyn validou bem esses pontos e conectou à solução. Porém, a closer não aprofundou a visão de futuro do lead com perguntas como ''se em 6 meses você estiver operando e com faturamento de R$100k, como isso muda sua vida?'' — o que teria fortalecido o desejo de solução antes da apresentação.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('bd659d13-585d-4dc1-8423-29f6de8f06ce', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_8', 'Pacto de Transição', 8, 6.0, 10.0, 0.05, 'ok', 'Executado em ~25:54 com a frase ''Deixa eu te apresentar um pouquinho então agora sobre o que que é System Digital''. Há uma tentativa de validação antes de iniciar a apresentação. O pacto foi feito, mas sem pedir permissão explícita ou confirmar que o lead estava pronto para avançar para o próximo estágio. A transição da fase de diagnóstico para apresentação poderia ter sido marcada com mais clareza e energia.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('891adafc-73b7-4452-91c7-e4f777db6f2c', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_9', 'Apresentação do Método', 9, 7.0, 10.0, 0.1, 'ok', 'Apresentação do método Face Sem K executada com clareza: 6 pilares (tráfego, posicionamento, esteira de produtos, funil de vendas, pré-vendas/secretária, revenda de base). Uso de casos (Dra. Débora: R$70k/semana) para validação social. Evelyn conectou bem os resultados ao cenário do Bruno, especialmente o estratégia de revender cirurgias para a base de pacientes de resina. Pontos negativos: apresentação foi interrompida várias vezes por perguntas do lead que poderiam ter sido gerenciadas de forma mais controlada; a explicação sobre LTV foi correta mas longa; o slide de ''sistema da System'' foi descrito sem clareza visual para o auditor, indicando possível falta de fluidez na apresentação gráfica.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('dc1a9e2f-d450-4856-9df5-133e4822a142', '390a8b49-bc1f-4ab4-b385-e9e132317e8b', 'stage_16', 'Down Sell', 16, 0.0, 10.0, 0.04, 'skipped', 'Não foi necessário pois houve fechamento', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:32:26.618081+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('a9211ae6-4136-4c3e-858c-cc53c90144fd', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_10', 'Apresentação do Produto', 10, 6.0, 10.0, 0.1, 'ok', 'Produto apresentado como programa de 6 meses com: tráfego pago incluso, treinamento de secretária, funil de pré-vendas, CRM, protocolos de caixa rápido, acompanhamento individual (não mentoria em grupo), reuniões personalizadas, grupo exclusivo. Evelyn diferenciou bem da mentoria tradicional e da agência de tráfego pago. Porém, os entregáveis não foram listados de forma sequencial e organizada — o lead fez a síntese (''é uma mentoria para minha clínica rodar e vender''), indicando que a apresentação não foi suficientemente clara sobre o que é entregue, quando e como. Faltou apresentar SLA de atendimento, frequência das reuniões e cronograma dos 6 meses.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('777ccce9-9997-4dca-bdbe-61cb648898b2', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_11', 'Isolamento de Objeções', 11, 4.0, 10.0, 0.08, 'warning', 'A principal objeção gerenciada foi a presença da esposa para tomada de decisão financeira. Evelyn identificou corretamente que a esposa é influenciadora de decisão e insistiu em trazê-la para a segunda call. A técnica foi aplicada de forma repetitiva e gerou tensão com o lead, que pediu explicitamente o valor (''me fala porque daí eu já vou meio que conversar com ela''). Evelyn não isolou outras possíveis objeções (momento de início, estrutura atual sem secretária, incerteza sobre o novo serviço de cirurgias). Não houve checagem de outras objeções antes de encerrar a call.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('154be29e-cdf3-4e29-9c2c-2b7b0164533f', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_12', 'Ancoragem', 12, 2.0, 10.0, 0.08, 'critical', 'Ancoragem praticamente ausente. Evelyn mencionou que há ''dois tipos de valores: para tomada de decisão em call e para depois da call'' — o que é uma âncora de urgência, não de valor. Não houve ancoragem pelo custo do problema (ex: ''você fatura R$30k, com cirurgias e processo comercial poderia fazer R$100k em duas semanas — quanto você deixa de ganhar por mês sem isso?''), nem ancoragem por comparação de mercado, nem ancoragem pelo investimento da concorrência. A ausência de ancoragem enfraquece significativamente o poder de persuasão antes da revelação do preço.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('54c1a3de-99e7-40db-958f-21653bc83a9b', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_13', 'Preço Tabela', 13, 0.0, 10.0, 0.05, 'skipped', 'Preço tabela não apresentado. Evelyn optou conscientemente por não revelar o valor sem a presença da esposa do lead, afirmando que valores são diferentes ''em call'' e ''fora da call''. Lead solicitou explicitamente o valor e foi bloqueado. Essa decisão, embora estratégica para proteger o desconto em call, pode ter gerado frustração e reduzido a probabilidade de fechamento na segunda call.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('0391015f-d9b6-4496-bc11-00b0689b1260', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_14', 'Preço Protagonista', 14, 0.0, 10.0, 0.05, 'skipped', 'Não executado. Consequência direta da ausência do Preço Tabela. A estratégia de apresentar o investimento como protagonista do lead (conectado ao ROI e ao cenário de transformação) não ocorreu. Oportunidade perdida de fazer o lead calcular mentalmente o retorno antes de ver o valor real.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('bb51068c-070d-450f-9f84-d33562cf3fb8', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_15', 'Negociação', 15, 0.0, 10.0, 0.07, 'skipped', 'Não executado. Nenhuma negociação foi conduzida. A call encerrou em reagendamento. Evelyn mencionou que o valor fica ''congelado por até 30 dias'' como alternativa à negociação imediata, mas sem especificar percentuais, condições de parcelamento ou bônus por fechamento imediato que poderiam ter motivado o lead a tomar decisão ainda nesta call.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('b9089a6e-4ae5-457a-a023-ddfec2cc89b7', 'f411560b-e95f-430c-9b7d-c267bfcf94ee', 'stage_16', 'Down Sell', 16, 0.0, 10.0, 0.04, 'skipped', 'Não executado. Sem apresentação de valor, sem negociação, não houve oportunidade de aplicar down sell. Nenhuma oferta alternativa de entrada foi apresentada (ex: um diagnóstico pago, acesso a um módulo inicial, período de teste). A call encerrou sem qualquer compromisso financeiro ou comercial do lead.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('418b0ff7-d929-46a7-83a1-ad66cf64ef33', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_1', 'Quebra-gelo', 1, 2.0, 10.0, 0.03, 'critical', 'A abertura foi caótica: câmera apagada, ruídos de setup, lead falando com terceiros sobre atendimento de paciente, interrupção imediata para pronto-socorro. Evelyn não estabeleceu qualquer elemento de rapport ou leveza. Tentou reagendar sem explorar a oportunidade, perdendo controle do frame logo no início.', NULL, '["Nenhuma frase de aquecimento ou humanização", "Não recuperou o ambiente após a interrupção", "Tentativa de reagendamento prematura sem avaliar viabilidade da continuação"]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('6dec8af8-20f0-4ca6-955e-6b8b33eca598', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_2', 'Rapport', 2, 2.0, 10.0, 0.05, 'critical', 'Evelyn pulou direto para explicações sobre o método da empresa assim que a lead fez a primeira pergunta sobre entrega de pacientes. Não houve reconhecimento genuíno da trajetória da Dra. Luciana, elogio ao posicionamento dela ou criação de conexão emocional. A lead foi quem dominou o diálogo com informações espontâneas.', NULL, '["Zero espelhamento emocional", "Nenhuma validação da experiência médica da lead", "Closer não criou identidade de parceiro — posicionou-se como avaliadora crítica desde o início"]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('b15aeec3-3b0f-4c5e-ae80-2825e5ebd353', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_3', 'Pacto Inicial', 3, 2.0, 10.0, 0.05, 'critical', 'Não houve alinhamento de agenda, definição de tempo, objetivo da reunião ou comprometimento mútuo. Evelyn mencionou ''diagnóstico'' de forma vaga, mas não estabeleceu as regras do jogo. A lead chegou com dúvidas sobre o produto sem saber o que a call significava, e isso nunca foi corrigido.', NULL, '["Sem definição clara do propósito da reunião", "Sem acordo de tempo", "Sem comprometimento da lead para ouvir a proposta ao final", "A interrupção do pronto-socorro não foi gerenciada com pacto de retomada"]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('bf17de13-fb04-429c-a757-6c42a43a24c7', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_4', 'SPIN - Situação', 4, 4.0, 10.0, 0.05, 'warning', 'Evelyn coletou dados básicos de situação de forma reativa — respondendo às falas espontâneas da lead. Mapeou: vínculo com hospital, estrutura de secretária, ticket atual (R$15-20k/mês), especialidades, público majoritariamente plano/baixa renda. Contudo, as perguntas foram dispersas e não seguiram uma sequência lógica de diagnóstico.', NULL, '["Não mapeou há quanto tempo está no mercado de estética", "Não investigou volume atual de procedimentos particulares", "Não perguntou sobre canais de comunicação ativos", "Perguntas situacionais vieram misturadas com explicações do produto"]'::jsonb, '["Identificou que a secretária é exclusiva", "Entendeu a dinâmica de atendimento dentro do hospital", "Mapeou faturamento atual"]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('41e16127-c51a-49e2-ac8d-69fba5b602ed', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_5', 'SPIN - Problema', 5, 4.0, 10.0, 0.05, 'warning', 'A lead verbalizou os problemas espontaneamente e com riqueza: falta de conversão de pacientes, frustração com agências anteriores, base de pacientes de baixa renda, queda de movimento no hospital, isolamento dentro da estrutura hospitalar. Evelyn ouviu mas não aprofundou ativamente — deixou a lead diagnosticar sozinha.', NULL, '["Evelyn não fez perguntas exploratórias sobre os problemas", "Não quantificou as perdas financeiras com agências anteriores", "Não perguntou sobre tentativas de venda direta para pacientes da base"]'::jsonb, '["Lead verbalizou claramente ''já gastei muito dinheiro e não tive retorno''", "Identificou gargalo de conversão (''morendo na praia'')"]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('214ef347-fb28-48ed-874b-13a5524904c3', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_6', 'SPIN - Implicação', 6, 1.0, 10.0, 0.08, 'critical', 'Etapa praticamente ausente. Evelyn nunca explorou as consequências dos problemas identificados: quanto a lead está deixando de ganhar por mês, qual o impacto na renda de longo prazo, o que acontece se continuar sem solução, o risco de perder espaço no mercado local de estética, o custo emocional do desânimo acumulado. A implicação é a etapa que cria urgência — e foi completamente negligenciada.', NULL, '["Nenhuma pergunta de implicação formulada", "Não conectou os problemas a consequências financeiras mensuráveis", "Não explorou o risco de inação", "Perdeu a oportunidade de aprofundar a dor quando a lead disse ''estou cansada de pagar e não ter retorno''"]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('5b0cb921-9a79-4d65-b583-be9841995818', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_7', 'SPIN - Necessidade', 7, 2.0, 10.0, 0.07, 'critical', 'A lead sinalizou necessidade de valor em múltiplos momentos (''quero método'', ''preciso de retorno'', ''preciso organizar a casa''), mas Evelyn não conduziu perguntas que fizessem a lead verbalizar o valor da solução. Não houve construção da necessidade de payoff — o que a solução representaria para a Dra. Luciana em termos de realização, crescimento e alívio.', NULL, '["Evelyn não perguntou ''O que significaria para você atingir esses 70k?''", "Não explorou o sonho por trás da meta", "Não fez a lead imaginar a solução funcionando"]'::jsonb, '["Lead verbalizou meta de R$60-70k/mês espontaneamente", "Lead reconheceu necessidade de treinamento de vendas para si e secretária"]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('681f8b80-3f53-465b-bbac-721d8261f4ac', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_8', 'Pacto de Transição', 8, 1.0, 10.0, 0.05, 'critical', 'Não houve transição estruturada para a apresentação. Evelyn começou a falar sobre produtos da empresa de forma orgânica e confusa, misturando diagnóstico com apresentação. Nenhuma frase de transição como ''Baseado no que você me contou, vou te apresentar como a gente pode ajudar'' foi utilizada.', NULL, '["Sem resumo das dores identificadas antes da transição", "Sem validação da lead para prosseguir", "Apresentação de produto iniciada sem convite formal"]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('49e37ade-03e5-46cf-8813-38bf7efcebb1', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_9', 'Apresentação do Método', 9, 2.0, 10.0, 0.1, 'critical', 'O método foi descrito de forma fragmentada, reativa e repetitiva ao longo de toda a call, sem uma apresentação estruturada. Evelyn mencionou as frentes de tráfego pago + estrutura comercial, a importância da secretária, esteira de produtos e oferta — mas sempre de forma introdutória, nunca aprofundando o diferencial. Não usou cases, não demonstrou resultados, não conectou o método à realidade específica da lead.', NULL, '["Sem estrutura clara (início, meio, fim)", "Sem prova social ou case de médico em contexto similar", "Sem demonstração visual ou storytelling", "Método foi usado como argumento de exclusão (''não se encaixa no seu cenário'') em vez de solução"]'::jsonb, '["Mencionou que o foco não é tráfego pago isolado", "Explicou a lógica de ''organizar a casa antes de trazer pacientes''"]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('27bd0605-ae53-4817-b449-babd5fcf803f', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_10', 'Apresentação do Produto', 10, 2.0, 10.0, 0.1, 'critical', 'Três produtos foram mencionados (Aceleração ~R$70k, Ativação, Mentoria ~R$550/mês) de forma passageira e desqualificadora. Evelyn apresentou cada produto já sinalizando por que não serviria para a lead, sem construir valor em nenhum deles. A apresentação foi feita ao contrário: em vez de elevar desejo e depois endereçar objeções, começou descartando antes mesmo de apresentar.', NULL, '["Nenhum produto foi apresentado com seus benefícios e resultados", "Evelyn autodescartou todos os produtos sem dar chance à lead de decidir", "Sem demonstração de ROI potencial", "Sem storytelling de transformação vinculado a cada oferta"]'::jsonb, '["Apresentou três níveis de produto, o que demonstra ecossistema"]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('984c0e16-0559-4e27-b07a-32d7f0866bac', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_11', 'Isolamento de Objeções', 11, 0.0, 10.0, 0.08, 'skipped', 'Etapa completamente ausente. A lead levantou múltiplas objeções implícitas (preço alto, cenário limitante, base fraca, vinculação ao hospital) e Evelyn as aceitou e reforçou em vez de isolá-las. Não foi feita nenhuma tentativa de separar a objeção real da objeção de fumaça, nem de entender se havia uma objeção principal bloqueando a decisão.', NULL, '["Nenhuma técnica de isolamento aplicada", "Evelyn validou todas as objeções como intransponíveis", "Perdeu a oportunidade de perguntar: ''Se o cenário fosse diferente, faria sentido avançar?''", "Não separou objeção de preço de objeção de viabilidade"]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('31906196-445c-40a5-b230-6a487f2577ee', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_12', 'Ancoragem', 12, 0.0, 10.0, 0.08, 'skipped', 'Nenhuma ancoragem de valor foi realizada. O preço do Aceleração (R$70k) foi jogado de forma crua, sem contexto, sem comparação com o custo do problema, sem âncora alta para criar percepção de valor relativo. A lead reagiu com choque (''Nossa Senhora'') e Evelyn imediatamente concordou que não fazia sentido — encerrando qualquer possibilidade de negociação.', NULL, '["Preço apresentado sem preparação de valor", "Sem âncora de perda (''quanto você deixa de ganhar por mês sem isso?'')", "Sem comparação com investimentos anteriores sem retorno", "Sem contextualização do ROI potencial antes do preço"]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('9f1fbfca-b7c1-429b-bf34-bbfc7e14a8df', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_13', 'Preço Tabela', 13, 1.0, 10.0, 0.05, 'critical', 'O preço foi mencionado de forma improvisada (''deixa eu abrir minha tabela'') sem preparação. Aceleração: ~R$70k. Mentoria: ~R$550/mês (~R$6k). Não houve apresentação formal de tabela, pacotes ou condições. A forma de revelar o preço comunicou insegurança e falta de preparo.', NULL, '["Preço revelado sem valor construído previamente", "Linguagem informal e despreparada na revelação do preço", "Sem apresentação de condições de pagamento", "Sem contextualização de o que está incluído em cada preço"]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('f845f985-4525-41d6-b5dd-2d8bfcd690dc', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_14', 'Preço Protagonista', 14, 0.0, 10.0, 0.05, 'skipped', 'Etapa completamente ausente. Após mencionar o preço, Evelyn não conduziu nenhuma técnica de protagonismo — como fazer a lead calcular o retorno sobre o investimento, visualizar o cenário após 90 dias, ou comparar o investimento com o custo da inação. A lead foi deixada sozinha com o número, sem narrativa de transformação.', NULL, '["Sem cálculo de ROI conduzido com a lead", "Sem projeção de cenário futuro", "Sem técnica de ''se você fechar X procedimentos por mês, em quanto tempo recupera?''"]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('cc36366d-30b9-46b8-a3e0-ba0e73a7d06f', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_15', 'Negociação', 15, 0.0, 10.0, 0.07, 'skipped', 'Nenhuma negociação ocorreu. Evelyn não apresentou proposta formal, não tentou customizar condição, não ofereceu plano de entrada, não criou urgência, não usou concessão estratégica. A call encerrou sem qualquer tentativa de fechamento ou próximo passo concreto.', NULL, '["Zero tentativa de fechamento", "Sem proposta formal apresentada", "Sem criação de urgência ou escassez", "Sem definição de próximo passo (follow-up, nova reunião, proposta por escrito)"]'::jsonb, '[]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('b2c843e4-29a0-48fd-9fb6-e1ba77521c68', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_12', 'Ancoragem', 12, 6.0, 10.0, 0.08, 'ok', 'Ancoragem presente mas não assertiva: mencionou soluções de 5k a 60k, mas poderia ter sido mais estratégica na ordem de apresentação.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('a3ae01d0-65bf-4908-98e2-9e29730bf49b', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_13', 'Preço de Tabela', 13, 8.0, 10.0, 0.05, 'excellent', 'Apresentou preço tabela claramente: 16.500 à vista ou 19.000 parcelado em 12x com juros.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('f49f2a66-2031-4f8c-98b2-cb43aed6694f', '50843289-0dda-45f4-ae2b-f79281d8ba4f', 'stage_16', 'Down Sell', 16, 1.0, 10.0, 0.04, 'critical', 'Embora a Mentoria (~R$550/mês) tenha sido mencionada como opção mais acessível, ela foi apresentada e imediatamente descartada pela própria closer (''não te recomendaria comprar nem esse''). O down sell foi suicidado antes de ser oferecido. A lead demonstrou interesse implícito (''quanto custa essa mentoria?'') e mesmo assim Evelyn não aproveitou o sinal de compra.', NULL, '["Down sell descartado pela própria closer antes de ser tentado", "Não explorou o interesse demonstrado pela lead na mentoria", "Não criou uma proposta de entrada mínima para manter o relacionamento", "Não ofereceu diagnóstico gratuito, conteúdo ou qualquer isca para próximo contato"]'::jsonb, '["Lead perguntou espontaneamente o preço da mentoria — sinal de compra claro"]'::jsonb, '2026-03-28T05:37:05.883347+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('c83213d0-8131-422d-977d-690305729587', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_1', 'Quebra-gelo', 1, 8.0, 10.0, 0.03, 'excellent', 'Quebra-gelo natural sobre localização geográfica (Bahia vs Paraná), criando conexão através de diferenças culturais.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('1afedded-9fd1-46b8-9c95-83c90bad4e1a', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_2', 'Rapport', 2, 9.0, 10.0, 0.05, 'excellent', 'Excelente rapport construído com apresentação pessoal detalhada, compartilhamento de experiência empresarial própria e identificação com desafios do lead.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('da411ab5-0bc2-4bbd-b83d-0758788462f7', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_3', 'Pacto Inicial', 3, 5.0, 10.0, 0.05, 'warning', 'Pacto implícito mas não formal. Mencionou que Carol passou interesse do lead, mas não estabeleceu acordo claro sobre objetivos da call.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('cffdd339-9052-478f-a5d3-74b61afc409e', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_4', 'SPIN Situação', 4, 8.0, 10.0, 0.05, 'excellent', 'Investigação eficaz da situação atual: 6 meses de consultório próprio, trabalho paralelo na franquia, faturamento de 20-30k, gestão solo.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('0210d944-3471-4a1d-a009-3a355856a020', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_5', 'SPIN Problema', 5, 9.0, 10.0, 0.05, 'excellent', 'Identificou problemas principais: tickets baixos (2-3k), leads desqualificados (100 mensagens, 8-10 conversões), falta de estrutura comercial.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('6d5aa776-a9a0-4501-bb99-c67dd0557226', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_6', 'SPIN Implicação', 6, 7.0, 10.0, 0.08, 'ok', 'Expandiu implicações dos problemas: frustração, comparação com concorrentes, ansiedade na condução comercial, oportunidades perdidas.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('dc73c219-e2b9-4451-af31-6a2add84da51', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_7', 'SPIN Necessidade', 7, 8.0, 10.0, 0.07, 'excellent', 'Lead expressou necessidade clara de dobrar faturamento (objetivo de 50k), melhorar estrutura comercial e ter suporte na condução de vendas.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('746fa9a5-9322-4fec-b198-caba50634327', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_8', 'Pacto de Transição', 8, 4.0, 10.0, 0.05, 'warning', 'Transição direta para apresentação sem pacto formal. Faltou confirmar se o lead queria conhecer as soluções disponíveis.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('155b2d5f-8ac5-44d4-91b6-b58d6fbe0308', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_9', 'Apresentação Método', 9, 8.0, 10.0, 0.1, 'excellent', 'Apresentação estruturada da System Digital: 6 anos de mercado, não é agência nem mentoria mas parceiro, foco em demanda qualificada e comercial.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('dafa33a0-378e-4863-9d1c-2fba596c22bf', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_10', 'Apresentação Produto', 10, 7.0, 10.0, 0.1, 'ok', 'Apresentou programa de ativação (3 meses) adequado ao perfil, explicou estrutura dos 30-60-90 dias, diferenciou de programa master.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('59e5ff7a-3ff7-4aa0-82b9-02875c11b381', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_11', 'Isolamento de Objeções', 11, 5.0, 10.0, 0.08, 'warning', 'Não isolou objeções formalmente. Lead demonstrou interesse mas mencionou necessidade de pensar (financeiro + conhecer mais).', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('b941fcc4-1d50-4ef1-8a7f-b6ccc558e310', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_14', 'Preço Protagonista', 14, 4.0, 10.0, 0.05, 'warning', 'Não aplicou silêncio estratégico. Lead imediatamente disse ''preciso pensar'' e Evelyn não deixou a pressão natural acontecer.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('e6475973-2386-4b64-90b7-3416603cc980', '5a89f6c9-2119-4311-a5d1-4c40b9b92f0d', 'stage_15', 'Negociação', 15, 7.0, 10.0, 0.07, 'ok', 'Negociação ativa com redução de juros e entrada flexível. Conseguiu reduzir de 19k para 17.881, mas lead não fechou por questões financeiras.', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:30:27.976676+00:00');
