INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('162799ba-894e-413f-805f-34fc481d504c', '614830f2-c07c-4902-9706-6dd78bb35fc2', 'stage_1', 'Quebra-gelo', 1, 7.0, 10.0, 0.03, 'ok', 'Início adequado com apresentação pessoal e conexão sobre origem italiana, criou ambiente descontraído', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:31:31.10756+00:00');
