INSERT INTO supervisor_stage_scores (id, analysis_id, stage_key, stage_name, stage_order, score, max_score, weight, status, justification, evidence_excerpt, missed_actions, suggested_fix, created_at) VALUES ('6c2357bd-5425-4803-8273-0c5e0c46d65b', '614830f2-c07c-4902-9706-6dd78bb35fc2', 'stage_7', 'SPIN Necessidade', 7, 3.0, 10.0, 0.07, 'critical', 'Não construiu necessidade de mudança adequadamente, apenas assumiu que precisavam da solução', NULL, '[]'::jsonb, '[]'::jsonb, '2026-03-28T19:31:31.10756+00:00');
